/*!
 * Zeugma · représentation JSON
 * Format versionné. Les pierres collées sont imbriquées comme un arbre : une tête de chaîne contient
 * sa suite (`next`), ses adjacentes hautes (`top`) et basses (`bottom`). Les fils sont listés à part :
 * ils relient deux points de deux pierres quelconques. Un générateur parcourt ce JSON sans le moteur.
 *
 * {
 *   "format": "kantoaplo.domino", "version": 2,
 *   "editor": { "id": "kanto", "name": "Kanto" },
 *   "context": { … },
 *   "parties": [
 *     { "id": "main", "kind": "main", "name": "Programme", "dominos": [
 *       { "id": "r1", "type": "k.number", "position": { "x": 0, "y": 0 }, "fields": { "value": 40 },
 *         "top":    [{ "pip": 1, "domino": { … } }],
 *         "bottom": [{ "pip": 0, "domino": { … } }],
 *         "next":   [{ "pip": 0, "map": [0], "label": "ok", "domino": { … } }] } ] },
 *     { "id": "decl", "kind": "declarations", "name": "Déclarations", "dominos": [ … ] },
 *     { "id": "c1", "kind": "body", "owner": "c1", "name": "Panier", "dominos": [ … ] } ],
 *   "wires": [
 *     { "id": "f1", "from": { "domino": "p1", "pip": 0, "name": "ajouter" }, "to": { "domino": "a1", "pip": 0, "name": "fonction" }, "blocking": false } ]
 * }
 */
(function (root) {
  'use strict';
  const D = root.Domino;

  /** Migrations : version n → n + 1. Le format peut évoluer sans casser les projets enregistrés. */
  const MIGRATIONS = {
    // v1 → v2 : les fils et le genre des parties.
    1(json) {
      json.version = 2;
      json.wires = json.wires || [];
      for (const p of json.parties || []) if (!p.kind) p.kind = p.id === 'main' ? 'main' : 'component';
      return json;
    },
  };
  /** Ordre de chargement : les déclarations et leurs corps d'abord (les instances lisent leur signature). */
  const ORDER = { declarations: 0, body: 1, main: 2, component: 3 };

  const Serializer = {
    MIGRATIONS,

    toJSON(ws, { context = true, partie = null } = {}) {
      const parties = [...ws.parties.values()].filter((p) => !partie || p.id === partie);
      const keep = new Set(parties.map((p) => p.id));
      const pipName = (id, side, i) => { const n = ws.get(id); const q = n && ws.pipsOf(n)[side][i]; return q ? q.name : undefined; };
      const wires = [...ws.wires.values()].filter((w) => { const a = ws.get(w.from.id), b = ws.get(w.to.id); return a && b && keep.has(a.partie); });
      return D.compact({
        format: D.FORMAT,
        version: D.FORMAT_VERSION,
        editor: ws.editorInfo ? D.clone(ws.editorInfo) : undefined,
        name: ws.name,
        context: context ? ws.context.snapshot() : undefined,
        assets: !partie && ws.assets && ws.assets.size ? Object.fromEntries([...ws.assets].map(([k, v]) => [k, D.clone(v)])) : undefined,
        parties: parties.map((p) => D.compact({
          id: p.id, kind: p.kind || (p.id === 'main' ? 'main' : 'component'), name: p.name, owner: p.owner || undefined,
          dominos: ws.roots(p.id).map((n) => Serializer.nodeToJSON(ws, n)),
        })),
        wires: wires.map((w) => D.compact({
          id: w.id,
          from: D.compact({ domino: w.from.id, pip: w.from.pip, name: pipName(w.from.id, 'right', w.from.pip) }),
          to: D.compact({ domino: w.to.id, pip: w.to.pip, name: pipName(w.to.id, 'left', w.to.pip) }),
          blocking: w.blocking === false ? false : undefined,
          label: w.label, enabled: w.enabled === false ? false : undefined,
          type: w.type || undefined, fields: w.fields && Object.keys(w.fields).length ? D.clone(w.fields) : undefined,
          meta: w.meta,
          trace: w.trace ? D.clone(w.trace) : undefined,
        })),
      });
    },

    nodeToJSON(ws, n, { next = true } = {}) {
      const kid = (id) => Serializer.nodeToJSON(ws, ws.get(id), { next: true });
      const meta = { ...n.meta };
      delete meta.unknownType;
      return D.compact({
        id: n.id,
        type: n.meta.unknownType || n.type,
        label: n.label,
        position: !n.parent && n.position ? { x: n.position.x, y: n.position.y } : undefined,
        fields: Object.keys(n.fields).length ? D.clone(n.fields) : undefined,
        turn: n.turn ? (n.turn === 'straight' ? 'straight' : D.DIR_PUBLIC[n.turn]) : undefined,
        top: n.top.filter((a) => ws.get(a.id)).map((a) => ({ pip: a.pip, domino: kid(a.id) })),
        bottom: n.bottom.filter((a) => ws.get(a.id)).map((a) => ({ pip: a.pip, domino: kid(a.id) })),
        next: next ? n.next.map((l, i) => (l && ws.get(l.id) ? D.compact({ pip: i, map: l.map, label: l.label, cond: l.cond, enabled: l.enabled === false ? false : undefined, domino: kid(l.id) }) : null)).filter(Boolean) : undefined,
        note: n.note || undefined,
        disabled: n.disabled || undefined,
        locked: n.locked || undefined,
        tags: n.tags && n.tags.length ? [...n.tags] : undefined,
        meta,
        trace: n.trace ? D.clone(n.trace) : undefined,
      });
    },

    /**
     * Charge un projet. Remplace le contenu de l'espace.
     * @returns {{ ok: boolean, errors: string[], warnings: string[], count: number }}
     */
    load(ws, json, { context = true, silent = false, history = 'reset' } = {}) {
      const report = { ok: true, errors: [], warnings: [], count: 0 };
      if (typeof json === 'string') { try { json = JSON.parse(json); } catch (err) { return { ...report, ok: false, errors: [`JSON invalide : ${err.message}`] }; } }
      // Une ressource (Project ou List, voir domino.resource.js) se lit comme le v2 qu'elle enveloppe.
      if (D.Resource && D.Resource.isResource(json)) { try { json = D.Resource.unwrap(json); } catch (err) { return { ...report, ok: false, errors: [err.message] }; } }
      report.errors.push(...Serializer.check(json));
      if (report.errors.length) { report.ok = false; return report; }
      let v = json.version || 1;
      if (v < D.FORMAT_VERSION) json = D.clone(json);
      while (v < D.FORMAT_VERSION) { json = MIGRATIONS[v](json); v++; }

      const prev = { tx: ws._tx, quiet: ws._quiet, restoring: ws._restoring };
      ws._tx = { label: 'load', events: [] };
      ws._quiet = true;
      ws._restoring = silent;
      try {
        ws.nodes.clear();
        ws.wires.clear();
        if (ws._resetIndexes) ws._resetIndexes();
        ws.rev = (ws.rev || 0) + 1;
        ws.diagnostics.clear();
        const keepDecl = ws.parties.get('decl');
        ws.parties = new Map([['main', { id: 'main', name: 'Partie principale', owner: null, kind: 'main' }]]);
        if (keepDecl) ws.parties.set('decl', { ...keepDecl });
        if (json.name) ws.name = json.name;
        if (json.editor) ws.editorInfo = D.clone(json.editor);
        if (context && json.context) ws.context.data = D.clone(json.context);
        // Les ressources du projet (documents importés) : remplacées par celles du fichier.
        if (ws.assets) {
          const sig = JSON.stringify(json.assets || {});
          if (sig !== ws._assetsSig) {
            ws.assets.clear();
            for (const [k, v] of Object.entries(json.assets || {})) ws.assets.set(k, D.clone(v));
            ws._assetsSig = sig;
            ws.assetsRev = (ws.assetsRev || 0) + 1;
          }
        }
        for (const p of json.parties) {
          if (p.id === 'main') { if (p.name) ws.parties.get('main').name = p.name; continue; }
          ws.parties.set(p.id, { id: p.id, name: p.name || p.id, owner: p.owner || null, kind: p.kind || 'component' });
        }
        const sorted = [...json.parties].sort((a, b) => (ORDER[a.kind || (a.id === 'main' ? 'main' : 'component')] ?? 3) - (ORDER[b.kind || (b.id === 'main' ? 'main' : 'component')] ?? 3));
        // Trois temps : les pierres, puis les fils (ils changent certaines faces : un appel non bloquant gagne une sortie),
        // puis les collages, dans l'ordre du fichier.
        const links = [];
        for (const p of sorted) for (const d of p.dominos || []) Serializer.loadNode(ws, d, p.id, { report, defer: links });
        for (const w of json.wires || []) Serializer.loadWire(ws, w, { report });
        for (const l of links) Serializer._linkLoaded(ws, l, report);
      } finally {
        ws._tx = prev.tx; ws._quiet = prev.quiet; ws._restoring = prev.restoring;
      }
      if (history === 'reset') { ws._undo = []; ws._redo = []; }
      report.count = ws.nodes.size;
      if (!silent) {
        ws.emit('load', { type: 'load', count: report.count, warnings: report.warnings.length, at: Date.now() });
        ws.emit('change', { type: 'change', reason: 'load' });
      }
      return report;
    },

    /** Charge une pierre (et ce qui y est collé) dans une partie. `freshIds` pour coller une copie. */
    loadNode(ws, j, partie, { freshIds = false, report = { warnings: [], errors: [] }, defer = null } = {}) {
      const known = ws.registry.has(j.type);
      const n = ws.create(j.type, {
        id: freshIds ? undefined : j.id, partie, fields: j.fields, label: j.label, turn: j.turn,
        position: j.position ? { x: j.position.x, y: j.position.y } : null, meta: j.meta,
        note: j.note, disabled: j.disabled, locked: j.locked, tags: j.tags,
        // Une copie (coller, dupliquer, importer) a sa propre provenance : elle dit d'où elle vient.
        trace: freshIds ? undefined : j.trace, how: freshIds ? 'copie' : undefined, from: freshIds ? j.id : undefined,
      });
      if (!known) report.warnings.push(`« ${j.id} » : type inconnu « ${j.type} », conservé tel quel.`);
      if (!freshIds && j.id && n.id !== j.id) report.warnings.push(`Identifiant « ${j.id} » déjà pris : renommé « ${n.id} ».`);
      if (report.ids) report.ids[j.id] = n.id;
      for (const via of ['top', 'bottom', 'next']) {
        for (const a of j[via] || []) {
          if (!a || !a.domino) continue;
          const c = Serializer.loadNode(ws, a.domino, partie, { freshIds, report, defer });
          const l = { n, c, via, a };
          if (defer) defer.push(l); else Serializer._linkLoaded(ws, l, report);
        }
      }
      return n;
    },
    _linkLoaded(ws, { n, c, via, a }, report) {
      const { left, right } = ws.pipsOf(n);
      const max = via === 'top' ? left.length : right.length;
      if (!(a.pip >= 0 && a.pip < max)) {
        report.warnings.push(`« ${n.id} » n’a pas de point n° ${a.pip + 1} pour « ${c.id} » (${via}) : la pierre est posée à part.`);
        return;
      }
      const check = ws.canConnect(n.id, c.id, via, a.pip);
      if (!check.ok && !/types|count|rule/.test(check.code)) { report.warnings.push(`${check.reason} (« ${c.id} » posée à part)`); return; }
      if (!check.ok) report.warnings.push(`${check.reason} (gardé, signalé dans les problèmes)`);
      ws._link(n, c, via, a.pip, via === 'next' ? { map: a.map || (check.ok ? check.map : [0]), label: a.label, cond: a.cond, enabled: a.enabled } : {});
    },

    /** Charge un fil. Un fil dont un bout manque est écarté ; un fil aux couleurs incompatibles est gardé et signalé. */
    loadWire(ws, j, { report = { warnings: [] }, ids = null } = {}) {
      const from = ids ? ids[j.from.domino] : j.from.domino, to = ids ? ids[j.to.domino] : j.to.domino;
      if (!ws.get(from) || !ws.get(to)) { report.warnings.push(`Fil « ${j.id || '?'} » : une de ses pierres manque, il est écarté.`); return null; }
      const r = ws.canWire(from, j.from.pip, to, j.to.pip);
      if (!r.ok && !/types|cycle|taken|rule|hook/.test(r.code)) { report.warnings.push(`Fil « ${j.id || '?'} » : ${r.reason} Il est écarté.`); return null; }
      if (!r.ok) report.warnings.push(`Fil « ${j.id || '?'} » : ${r.reason} (gardé, signalé dans les problèmes)`);
      const w = new D.Wire({ id: j.id && !ws.wires.has(j.id) ? j.id : ws.newWireId(), from: { id: from, pip: j.from.pip }, to: { id: to, pip: j.to.pip }, blocking: j.blocking, label: j.label, enabled: j.enabled, meta: j.meta, trace: j.trace, type: j.type, fields: j.fields });
      ws._addWire(w);
      return w;
    },

    /** Vérification de forme, avec des messages qui disent où est l'erreur. */
    check(json) {
      const errs = [];
      if (!D.isPlainObject(json)) return ['Le projet doit être un objet JSON.'];
      if (json.format && json.format !== D.FORMAT) errs.push(`« format » vaut « ${json.format} », attendu « ${D.FORMAT} ».`);
      if (json.version && (!Number.isInteger(json.version) || json.version > D.FORMAT_VERSION)) errs.push(`Version ${json.version} non prise en charge (au plus ${D.FORMAT_VERSION}).`);
      if (!Array.isArray(json.parties) || !json.parties.length) errs.push('« parties » doit être une liste non vide.');
      const ids = new Set();
      const walk = (d, where) => {
        if (!D.isPlainObject(d)) { errs.push(`${where} : une pierre doit être un objet.`); return; }
        if (!d.type) errs.push(`${where} : « type » manquant.`);
        if (d.id) { if (ids.has(d.id)) errs.push(`${where} : l’identifiant « ${d.id} » est utilisé deux fois.`); ids.add(d.id); }
        if (d.turn && !['right', 'down', 'left', 'up', 'straight'].includes(d.turn)) errs.push(`${where} : « turn » vaut right, down, left, up ou straight.`);
        for (const via of ['top', 'bottom', 'next']) {
          if (d[via] === undefined) continue;
          if (!Array.isArray(d[via])) { errs.push(`${where} : « ${via} » doit être une liste.`); continue; }
          d[via].forEach((a, i) => {
            if (!D.isPlainObject(a) || !Number.isInteger(a.pip) || a.pip < 0) errs.push(`${where}.${via}[${i}] : « pip » doit être un entier ≥ 0.`);
            else walk(a.domino, `${where}.${via}[${i}].domino`);
          });
        }
      };
      (json.parties || []).forEach((p, i) => {
        if (!D.isPlainObject(p) || !p.id) { errs.push(`parties[${i}] : « id » manquant.`); return; }
        if (p.kind && !['main', 'declarations', 'body', 'component'].includes(p.kind)) errs.push(`parties[${i}] : « kind » vaut main, declarations, body ou component.`);
        (p.dominos || []).forEach((d, k) => walk(d, `parties[${i}].dominos[${k}]${d && d.id ? ` (${d.id})` : ''}`));
      });
      if (json.wires !== undefined && !Array.isArray(json.wires)) errs.push('« wires » doit être une liste.');
      (json.wires || []).forEach((w, i) => {
        const end = (e, k) => { if (!D.isPlainObject(e) || typeof e.domino !== 'string' || !Number.isInteger(e.pip) || e.pip < 0) errs.push(`wires[${i}].${k} : { domino, pip } attendu.`); };
        if (!D.isPlainObject(w)) { errs.push(`wires[${i}] : un fil doit être un objet.`); return; }
        end(w.from, 'from'); end(w.to, 'to');
      });
      return errs;
    },
  };

  /** JSON Schema (2020-12) du format : pour valider ou générer des outils hors du moteur. */
  Serializer.schema = {
    $schema: 'https://json-schema.org/draft/2020-12/schema',
    $id: 'https://kantoaplo.dev/schema/domino/2.json',
    title: 'Projet Zeugma',
    type: 'object',
    required: ['format', 'version', 'parties'],
    properties: {
      format: { const: 'kantoaplo.domino' },
      version: { type: 'integer', minimum: 1 },
      editor: { type: 'object', properties: { id: { type: 'string' }, name: { type: 'string' } } },
      name: { type: 'string' },
      context: { type: 'object', description: 'Valeurs du contexte, lues par les liaisons { "$bind": "clé" } et les gabarits {{clé}}.' },
      assets: { type: 'object', description: 'Ressources du projet : des documents JSON attachés ou importés (une collection d’API, des environnements, un jeu de données…), par clé. Le langage les lit ; sa boîte à outils peut en tirer des pierres.', additionalProperties: true },
      parties: { type: 'array', minItems: 1, items: { $ref: '#/$defs/partie' } },
      wires: { type: 'array', items: { $ref: '#/$defs/wire' }, description: 'Fils : d’un point de sortie à un point d’entrée, entre deux pierres de la même partie.' },
    },
    $defs: {
      partie: {
        type: 'object', required: ['id'],
        properties: {
          id: { type: 'string' }, name: { type: 'string' },
          kind: { enum: ['main', 'declarations', 'body', 'component'], description: 'main : la partie principale ; declarations : classes, bibliothèques, fonctions ; body : le corps d’une déclaration ; component : la sous-partie d’une pierre conteneur.' },
          owner: { type: 'string', description: 'Pierre (conteneur ou déclaration) qui ouvre cette partie.' },
          dominos: { type: 'array', items: { $ref: '#/$defs/domino' } },
        },
      },
      domino: {
        type: 'object', required: ['type'],
        properties: {
          id: { type: 'string' }, type: { type: 'string' }, label: { type: 'string' },
          position: { type: 'object', properties: { x: { type: 'number' }, y: { type: 'number' } }, description: 'Têtes de chaîne et pierres libres seulement.' },
          fields: { type: 'object', additionalProperties: { anyOf: [{}, { $ref: '#/$defs/binding' }, { $ref: '#/$defs/ref' }] } },
          turn: { enum: ['right', 'down', 'left', 'up', 'straight'] },
          top: { type: 'array', items: { $ref: '#/$defs/adjacent' }, description: 'Adjacentes hautes : chacune alimente l’entrée n° pip.' },
          bottom: { type: 'array', items: { $ref: '#/$defs/adjacent' }, description: 'Adjacentes basses : chacune consomme la sortie n° pip.' },
          next: { type: 'array', items: { $ref: '#/$defs/link' }, description: 'Suite de la chaîne : la sortie n° pip mène à la pierre suivante.' },
          note: { type: 'string', description: 'Note de l’utilisateur.' },
          disabled: { type: 'boolean', description: 'Neutralisée : l’effet domino la traverse sans l’exécuter.' },
          locked: { type: 'boolean', description: 'Verrouillée pour l’utilisateur.' },
          tags: { type: 'array', items: { type: 'string' } },
          meta: { type: 'object' },
          trace: { $ref: '#/$defs/trace' },
        },
      },
      adjacent: { type: 'object', required: ['pip', 'domino'], properties: { pip: { type: 'integer', minimum: 0 }, domino: { $ref: '#/$defs/domino' } } },
      link: {
        type: 'object', required: ['pip', 'domino'],
        properties: { pip: { type: 'integer', minimum: 0 }, map: { type: 'array', items: { type: 'integer', minimum: 0 }, description: 'Entrées de la pierre suivante câblées sur cette sortie.' }, label: { type: 'string' }, cond: { anyOf: [{ type: 'string' }, { type: 'object' }], description: 'Condition : expression JavaScript courte (texte) ou expression déclarative (objet, voir expr.schema.json).' }, enabled: { type: 'boolean' }, domino: { $ref: '#/$defs/domino' } },
      },
      wire: {
        type: 'object', required: ['from', 'to'],
        properties: {
          id: { type: 'string' },
          from: { $ref: '#/$defs/end', description: 'Point de sortie (face droite).' },
          to: { $ref: '#/$defs/end', description: 'Point d’entrée (face gauche).' },
          blocking: { type: 'boolean', description: 'false : l’appelant n’attend pas (appel non bloquant). Absent : bloquant.' },
          type: { type: 'string', description: 'Genre de lien (langage : edges) : transition, relation…' },
          fields: { type: 'object', description: 'Champs du lien (événement, garde, cardinalité…).' },
          label: { type: 'string' }, enabled: { type: 'boolean' }, meta: { type: 'object' }, trace: { $ref: '#/$defs/trace' },
        },
      },
      end: { type: 'object', required: ['domino', 'pip'], properties: { domino: { type: 'string' }, pip: { type: 'integer', minimum: 0 }, name: { type: 'string', description: 'Nom du point (lecture seule, pour les générateurs).' } } },
      binding: { type: 'object', required: ['$bind'], properties: { $bind: { type: 'string' } }, additionalProperties: false },
      ref: { type: 'object', required: ['$ref'], properties: { $ref: { type: 'string', description: 'Identifiant d’une pierre, d’une partie, d’une déclaration ou d’une variable.' } }, additionalProperties: false },
      trace: {
        type: 'object', description: 'Provenance.',
        properties: {
          created: { type: 'object', properties: { at: { type: 'string', format: 'date-time' }, by: { type: 'string' }, how: { type: 'string', description: 'pioche, ajout rapide, copie, import, api…' }, from: { type: 'string', description: 'L’original d’une copie.' } } },
          modified: { type: 'object', properties: { at: { type: 'string', format: 'date-time' }, by: { type: 'string' }, count: { type: 'integer' }, last: { type: 'string' } } },
        },
      },
    },
  };

  D.Serializer = Serializer;
})(typeof globalThis !== 'undefined' ? globalThis : window);
