/*!
 * Zeugma · ressources (format « élément » professionnel)
 *
 * Toute chose que la plateforme enregistre ou échange (un projet, une pierre, un fil, une partie, un langage,
 * un espace de travail) peut s'écrire comme une RESSOURCE, une enveloppe stable et extensible :
 *
 *   {
 *     "apiVersion": "kantoaplo.dev/v1",          groupe/version de l'enveloppe
 *     "kind": "Domino",                           Project · Domino · Wire · Partie · Language · Workspace · List
 *     "metadata": { uid, name, title, description, labels, annotations, created, modified, revision, etag },
 *     "spec":     { … },                          ce qui est déclaré : fait autorité, seul lu au chargement
 *     "status":   { … },                          ce qui est calculé (rôle, points, diagnostics…) : jamais relu
 *     "extensions": { "com.acme.review/v1": { … } }   données d'outils tiers, conservées à l'aller-retour
 *   }
 *
 * Deux formes, sans perte de l'une à l'autre :
 *  - canonique (enregistrée) : une ressource Project dont spec.content est EXACTEMENT le format v2 du
 *    sérialiseur (voir domino.serializer.js) ; les générateurs et Serializer.load la lisent telle quelle ;
 *  - à plat : une ressource List de Partie, Domino et Wire (une ressource par élément) pour les API par
 *    élément, les diffs et la résolution fine des conflits. explode() et assemble() passent de l'une à l'autre.
 *
 * Règles d'extension :
 *  - les clés d'extensions sont « domaine/nom[/vN] » ; le préfixe « kantoaplo.dev/ » est réservé au moteur ;
 *  - un lecteur DOIT conserver les extensions qu'il ne connaît pas ;
 *  - les données propres au langage vont dans spec.fields (définies par la pierre), pas dans les extensions ;
 *  - un ajout facultatif garde apiVersion v1 ; une rupture donne v2 et une conversion dans CONVERSIONS.
 *    Le contenu (spec.content) garde son propre versionnage (format kantoaplo.domino, MIGRATIONS).
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const API_VERSION = 'kantoaplo.dev/v1';
  const KINDS = ['Project', 'Domino', 'Wire', 'Partie', 'Language', 'Workspace', 'List'];
  const RESERVED = 'kantoaplo.dev/';
  /** Les clés de meta (v2) qui ont une place propre dans la ressource ; les autres vont dans l'extension « kantoaplo.dev/meta ». */
  const META_PLACED = ['uid', 'display', 'faces', 'tint', 'extensions'];
  const NAME = /^[A-Za-z_][\w.-]{0,63}$/;

  const clone = (v) => (v === undefined ? undefined : D.clone(v));
  const compact = D.compact;

  /** Un identifiant opaque, stable une fois donné (« p_k3x9a1q2 »). */
  function newUid(prefix = 'r') {
    let s;
    const c = root.crypto && typeof root.crypto.getRandomValues === 'function' ? root.crypto : null;
    if (c) { const a = new Uint32Array(2); c.getRandomValues(a); s = a[0].toString(36) + a[1].toString(36); } else s = Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);
    return `${prefix}_${s.slice(0, 10)}`;
  }
  /** Un nom lisible à partir d'un titre (« Mon projet » → « mon-projet »). */
  function slug(t, fallback = 'projet') {
    const s = String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9_.-]+/g, '-').replace(/^[-.]+|[-.]+$/g, '').slice(0, 60);
    return /^[a-z_]/.test(s) ? s : s ? `p-${s}`.slice(0, 64) : fallback;
  }

  // ---------------------------------------------------------------------------
  // meta (v2) ⇄ presentation, extensions
  // ---------------------------------------------------------------------------
  function splitMeta(meta) {
    const m = meta || {};
    const rest = {};
    for (const [k, v] of Object.entries(m)) if (!META_PLACED.includes(k)) rest[k] = clone(v);
    const ext = { ...(clone(m.extensions) || {}) };
    if (Object.keys(rest).length) ext[`${RESERVED}meta`] = rest;
    return { uid: m.uid, presentation: compact({ display: m.display, faces: clone(m.faces), tint: m.tint }), extensions: compact(ext) };
  }
  function joinMeta(uid, presentation, extensions) {
    const p = presentation || {}, x = { ...(extensions || {}) };
    const rest = x[`${RESERVED}meta`] || {};
    delete x[`${RESERVED}meta`];
    return compact({ ...clone(rest), uid, display: p.display, faces: clone(p.faces), tint: p.tint, extensions: Object.keys(x).length ? clone(x) : undefined });
  }
  const traceToMeta = (t) => (t ? compact({ created: clone(t.created), modified: clone(t.modified) }) : {});
  const metaToTrace = (m) => compact({ created: clone(m.created), modified: clone(m.modified) });

  // ---------------------------------------------------------------------------
  // Pierres, fils, parties : v2 ⇄ ressources à plat
  // ---------------------------------------------------------------------------
  function dominoResource(j, placement) {
    const m = splitMeta(j.meta);
    return compact({
      apiVersion: API_VERSION, kind: 'Domino',
      metadata: compact({ name: j.id, uid: m.uid, title: j.label, ...traceToMeta(j.trace) }),
      spec: compact({
        type: j.type,
        fields: clone(j.fields),
        placement: compact(placement),
        flags: compact({ disabled: j.disabled || undefined, locked: j.locked || undefined }),
        note: j.note, tags: clone(j.tags),
        presentation: m.presentation,
      }),
      extensions: m.extensions,
    });
  }
  function dominoFromResource(r) {
    const md = r.metadata || {}, s = r.spec || {}, pl = s.placement || {}, f = s.flags || {};
    return compact({
      id: md.name, type: s.type, label: md.title,
      position: pl.position ? { x: pl.position.x, y: pl.position.y } : undefined,
      fields: clone(s.fields), turn: pl.turn,
      note: s.note, disabled: f.disabled || undefined, locked: f.locked || undefined, tags: clone(s.tags),
      meta: joinMeta(md.uid, s.presentation, r.extensions),
      trace: metaToTrace(md),
    });
  }
  function wireResource(w) {
    const m = splitMeta(w.meta);
    return compact({
      apiVersion: API_VERSION, kind: 'Wire',
      metadata: compact({ name: w.id, uid: m.uid, ...traceToMeta(w.trace) }),
      spec: compact({
        from: compact({ element: w.from.domino, pip: w.from.pip, name: w.from.name }),
        to: compact({ element: w.to.domino, pip: w.to.pip, name: w.to.name }),
        blocking: w.blocking, label: w.label, enabled: w.enabled,
        edgeType: w.type, fields: clone(w.fields),
        presentation: m.presentation,
      }),
      extensions: m.extensions,
    });
  }
  function wireFromResource(r) {
    const md = r.metadata || {}, s = r.spec || {};
    return compact({
      id: md.name,
      from: compact({ domino: s.from.element, pip: s.from.pip, name: s.from.name }),
      to: compact({ domino: s.to.element, pip: s.to.pip, name: s.to.name }),
      blocking: s.blocking, label: s.label, enabled: s.enabled,
      type: s.edgeType, fields: clone(s.fields),
      meta: joinMeta(md.uid, s.presentation, r.extensions),
      trace: metaToTrace(md),
    });
  }

  // ---------------------------------------------------------------------------
  // L'API publique
  // ---------------------------------------------------------------------------
  const Resource = {
    API_VERSION, KINDS, NAME,
    newUid, slug,

    /** Vrai si json est une ressource (apiVersion + kind). */
    isResource(json) { return !!json && typeof json === 'object' && typeof json.apiVersion === 'string' && typeof json.kind === 'string'; },

    /**
     * Projet v2 (Serializer.toJSON) → ressource Project canonique.
     * @param {object} v2
     * @param {{ uid?, name?, title?, description?, labels?, annotations?, revision?, etag?, created?, modified?, settings?, status?, extensions? }} meta
     */
    fromProject(v2, meta = {}) {
      const content = clone(v2);
      const lang = content.editor || {};
      return compact({
        apiVersion: API_VERSION, kind: 'Project',
        metadata: compact({
          uid: meta.uid || newUid('p'),
          name: meta.name || slug(meta.title || content.name),
          title: meta.title || content.name,
          description: meta.description,
          labels: compact({ language: lang.id, ...(meta.labels || {}) }),
          annotations: clone(meta.annotations),
          created: clone(meta.created), modified: clone(meta.modified),
          revision: meta.revision, etag: meta.etag,
        }),
        spec: compact({ language: compact({ id: lang.id, name: lang.name }), settings: clone(meta.settings), content }),
        status: clone(meta.status),
        extensions: clone(meta.extensions),
      });
    },

    /** Ressource Project → projet v2 exact (ce que lisent Serializer.load et les générateurs). */
    toProject(res) {
      if (!res || res.kind !== 'Project') throw new D.DominoError('resource.kind', `Une ressource « Project » est attendue (reçu « ${res && res.kind} »).`);
      const r = Resource.convert(res, API_VERSION);
      if (!r.spec || !r.spec.content) throw new D.DominoError('resource.content', 'La ressource Project n’a pas de spec.content.');
      return clone(r.spec.content);
    },

    /** Accepte un projet v2, une ressource Project ou une ressource List ; rend toujours du v2. */
    unwrap(json) {
      if (!Resource.isResource(json)) return json;
      if (json.kind === 'Project') return Resource.toProject(json);
      if (json.kind === 'List') return Resource.toProject(Resource.assemble(json));
      throw new D.DominoError('resource.kind', `Une ressource « ${json.kind} » n’est pas un projet.`);
    },

    /**
     * Forme à plat : une ressource par partie, pierre et fil, dans l'ordre de lecture.
     * La placement d'une pierre dit où elle est : tête de chaîne (partie, position, virage) ou collée
     * (attachedTo : élément, via next/top/bottom, point, et pour une suite map, label, cond, enabled ; order).
     */
    explode(projectRes) {
      const v2 = Resource.toProject(projectRes);
      const items = [];
      (v2.parties || []).forEach((p, order) => {
        items.push(compact({ apiVersion: API_VERSION, kind: 'Partie', metadata: compact({ name: p.id, title: p.name }), spec: compact({ kind: p.kind, owner: p.owner, order }) }));
        const walk = (j, placement) => {
          items.push(dominoResource(j, placement));
          for (const via of ['top', 'bottom', 'next']) {
            (j[via] || []).forEach((a, k) => {
              if (!a || !a.domino) return;
              walk(a.domino, { partie: p.id, turn: a.domino.turn, attachedTo: compact({ element: j.id, via, pip: a.pip, map: clone(a.map), label: a.label, cond: a.cond, enabled: a.enabled, order: k }) });
            });
          }
        };
        (p.dominos || []).forEach((j, k) => walk(j, { partie: p.id, position: j.position ? { x: j.position.x, y: j.position.y } : undefined, turn: j.turn, order: k }));
      });
      for (const w of v2.wires || []) items.push(wireResource(w));
      return compact({
        apiVersion: API_VERSION, kind: 'List',
        metadata: clone(projectRes.metadata),
        spec: compact({ language: clone(projectRes.spec.language), settings: clone(projectRes.spec.settings), project: compact({ format: v2.format, version: v2.version, editor: clone(v2.editor), name: v2.name, context: clone(v2.context), assets: clone(v2.assets) }) }),
        status: clone(projectRes.status),
        extensions: clone(projectRes.extensions),
        items,
      });
    },

    /** Inverse exact de explode() : rend la ressource Project canonique. */
    assemble(list) {
      if (!list || list.kind !== 'List') throw new D.DominoError('resource.kind', 'Une ressource « List » est attendue.');
      const s = list.spec || {}, head = s.project || {};
      const parties = [], byPartie = new Map(), byName = new Map(), wires = [];
      const pending = [];
      for (const it of list.items || []) {
        if (it.kind === 'Partie') {
          const p = compact({ id: it.metadata.name, kind: it.spec && it.spec.kind, name: it.metadata.title, owner: it.spec && it.spec.owner });
          p.dominos = [];
          parties.push({ p, order: (it.spec && it.spec.order) ?? parties.length });
          byPartie.set(p.id, p);
        } else if (it.kind === 'Domino') {
          const j = dominoFromResource(it);
          byName.set(j.id, j);
          pending.push({ j, pl: (it.spec && it.spec.placement) || {} });
        } else if (it.kind === 'Wire') wires.push(wireFromResource(it));
      }
      const roots = new Map(), kids = [];
      for (const { j, pl } of pending) {
        const a = pl.attachedTo;
        if (a) kids.push({ j, a });
        else { if (!roots.has(pl.partie)) roots.set(pl.partie, []); roots.get(pl.partie).push({ j, order: pl.order ?? 0 }); }
      }
      for (const { j, a } of kids) {
        const parent = byName.get(a.element);
        if (!parent) throw new D.DominoError('resource.orphan', `« ${j.id} » est collée à « ${a.element} », introuvable.`);
        (parent[a.via] ||= []).push({ order: a.order ?? 0, entry: compact(a.via === 'next' ? { pip: a.pip, map: clone(a.map), label: a.label, cond: a.cond, enabled: a.enabled, domino: j } : { pip: a.pip, domino: j }) });
      }
      // Les listes de collage sont rangées par « order », puis débarrassées de ce champ de travail.
      for (const j of byName.values()) for (const via of ['top', 'bottom', 'next']) if (j[via]) j[via] = j[via].sort((x, y) => x.order - y.order).map((x) => x.entry);
      for (const [pid, list2] of roots) { const p = byPartie.get(pid); if (p) p.dominos = list2.sort((x, y) => x.order - y.order).map((x) => x.j); }
      // Comme Serializer.toJSON : une partie sans pierre n'a pas de liste « dominos ».
      const ps = parties.sort((x, y) => x.order - y.order).map((x) => { const q = { ...x.p }; if (!q.dominos.length) delete q.dominos; return q; });
      const v2 = compact({ format: head.format, version: head.version, editor: clone(head.editor), name: head.name, context: clone(head.context), assets: clone(head.assets), parties: ps, wires });
      return compact({ apiVersion: API_VERSION, kind: 'Project', metadata: clone(list.metadata), spec: compact({ language: clone(s.language), settings: clone(s.settings), content: v2 }), status: clone(list.status), extensions: clone(list.extensions) });
    },

    /** Une pierre vivante → ressource Domino, avec son état calculé (status). */
    fromNode(ws, n) {
      const j = D.Serializer.nodeToJSON(ws, n, { next: false });
      delete j.top; delete j.bottom;
      const p = n.parent;
      const link = p && p.via === 'next' ? (ws.get(p.id).next[p.pip] || {}) : {};
      const placement = p
        ? { partie: n.partie, turn: j.turn, attachedTo: compact({ element: p.id, via: p.via, pip: p.pip, map: clone(link.map), label: link.label, cond: link.cond, enabled: link.enabled === false ? false : undefined }) }
        : { partie: n.partie, position: j.position, turn: j.turn };
      const r = dominoResource(j, placement);
      const { left, right } = ws.pipsOf(n), sem = ws.semanticsOf(n);
      const pip = (q) => compact({ name: q.name, type: q.type, required: q.required === false ? false : undefined });
      r.status = compact({
        role: sem.role, meaning: sem.label,
        pips: { left: left.map(pip), right: right.map(pip) },
        diagnostics: (ws.diagnostics.get(n.id) || []).map((d) => compact({ level: d.level, code: d.code, message: d.message })),
        represents: n.def.represents,
      });
      return r;
    },

    /**
     * Vérifie une ressource. Rend la liste des erreurs (vide si tout va bien), en français, avec le chemin.
     * Pour un Project, la forme de spec.content est vérifiée par Serializer.check.
     */
    validate(res) {
      const errs = [];
      if (!D.isPlainObject(res)) return ['Une ressource doit être un objet JSON.'];
      if (!CONVERSIONS[res.apiVersion]) errs.push(`apiVersion « ${res.apiVersion} » inconnue (connues : ${Object.keys(CONVERSIONS).join(', ')}).`);
      if (!KINDS.includes(res.kind)) errs.push(`kind « ${res.kind} » inconnu (connus : ${KINDS.join(', ')}).`);
      const md = res.metadata;
      if (!D.isPlainObject(md)) errs.push('metadata manque.');
      else {
        if (res.kind !== 'List' && (typeof md.name !== 'string' || !NAME.test(md.name))) errs.push(`metadata.name « ${md.name} » : lettres, chiffres, « _ », « - » ou « . », 64 au plus, sans commencer par un chiffre.`);
        for (const k of ['labels', 'annotations']) if (md[k] !== undefined && (!D.isPlainObject(md[k]) || Object.values(md[k]).some((v) => typeof v !== 'string'))) errs.push(`metadata.${k} : un objet de chaînes.`);
      }
      if (res.extensions !== undefined) {
        if (!D.isPlainObject(res.extensions)) errs.push('extensions : un objet.');
        else for (const k of Object.keys(res.extensions)) if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+\/[\w.-]+(\/v\d+)?$/i.test(k)) errs.push(`extensions : la clé « ${k} » doit s’écrire « domaine/nom[/vN] ».`);
      }
      if (res.kind === 'Project') {
        if (!res.spec || !res.spec.content) errs.push('spec.content manque.');
        else errs.push(...D.Serializer.check(res.spec.content).map((m) => `spec.content : ${m}`));
      }
      if (res.kind === 'Domino' && !(res.spec && typeof res.spec.type === 'string')) errs.push('spec.type manque.');
      if (res.kind === 'Wire' && !(res.spec && res.spec.from && res.spec.to)) errs.push('spec.from et spec.to sont requis.');
      if (res.kind === 'List') (res.items || []).forEach((it, i) => errs.push(...Resource.validate(it).map((m) => `items[${i}] : ${m}`)));
      return errs;
    },

    /** Convertit une ressource vers une apiVersion (CONVERSIONS : une fonction par version source). */
    convert(res, apiVersion = API_VERSION) {
      let r = res, guard = 0;
      while (r.apiVersion !== apiVersion) {
        const step = CONVERSIONS[r.apiVersion];
        if (!step || !step.to || ++guard > 8) throw new D.DominoError('resource.version', `Pas de conversion de « ${r.apiVersion} » vers « ${apiVersion} ».`);
        r = step.up(clone(r));
      }
      return r;
    },
  };
  /** Table des conversions : { 'kantoaplo.dev/v1': { to: null } } ; une v2 ajoutera { to: 'kantoaplo.dev/v2', up(r) { … } } à v1. */
  const CONVERSIONS = { [API_VERSION]: { to: null } };
  Resource.CONVERSIONS = CONVERSIONS;

  // ---------------------------------------------------------------------------
  // Schéma publié (engine/schema/resource.schema.json)
  // ---------------------------------------------------------------------------
  const str = { type: 'string' };
  const strMap = { type: 'object', additionalProperties: { type: 'string' } };
  Resource.schema = {
    $schema: 'https://json-schema.org/draft/2020-12/schema',
    $id: 'https://kantoaplo.dev/schema/resource/v1.json',
    title: 'Ressource Kantoaplo (apiVersion kantoaplo.dev/v1)',
    description: 'Enveloppe commune : apiVersion, kind, metadata, spec (déclaré), status (calculé, jamais relu), extensions (outils tiers, conservées).',
    type: 'object',
    required: ['apiVersion', 'kind', 'metadata'],
    properties: {
      apiVersion: { const: API_VERSION },
      kind: { enum: KINDS },
      metadata: { $ref: '#/$defs/metadata' },
      spec: { type: 'object' },
      status: { type: 'object', description: 'Calculé par le moteur ; ignoré au chargement.' },
      extensions: { $ref: '#/$defs/extensions' },
      items: { type: 'array', items: { $ref: '#' }, description: 'kind List seulement : les ressources Partie, Domino et Wire, dans l’ordre de lecture.' },
    },
    $defs: {
      metadata: {
        type: 'object',
        properties: {
          uid: { type: 'string', description: 'Identifiant opaque et stable.' },
          name: { type: 'string', description: 'Identifiant lisible, unique dans son parent (pour une pierre : son id v2).' },
          title: str, description: str, labels: strMap, annotations: strMap,
          created: { type: 'object', properties: { at: str, by: str, how: str, from: str } },
          modified: { type: 'object', properties: { at: str, by: str, count: { type: 'integer' }, last: str } },
          revision: { type: 'integer', minimum: 0 }, etag: str,
        },
      },
      extensions: { type: 'object', description: 'Clés « domaine/nom[/vN] » ; « kantoaplo.dev/ » est réservé au moteur.' },
      dominoSpec: {
        type: 'object', required: ['type'],
        properties: {
          type: str, fields: { type: 'object' },
          placement: {
            type: 'object',
            properties: {
              partie: str, position: { type: 'object', properties: { x: { type: 'number' }, y: { type: 'number' } } }, turn: str, order: { type: 'integer' },
              attachedTo: { type: 'object', required: ['element', 'via', 'pip'], properties: { element: str, via: { enum: ['next', 'top', 'bottom'] }, pip: { type: 'integer', minimum: 0 }, map: { type: 'array', items: { type: 'integer' } }, label: str, cond: str, enabled: { type: 'boolean' }, order: { type: 'integer' } } },
            },
          },
          flags: { type: 'object', properties: { disabled: { type: 'boolean' }, locked: { type: 'boolean' } } },
          note: str, tags: { type: 'array', items: str },
          presentation: { type: 'object', properties: { display: str, faces: { type: 'object' }, tint: str } },
        },
      },
      wireSpec: {
        type: 'object', required: ['from', 'to'],
        properties: { from: { $ref: '#/$defs/end' }, to: { $ref: '#/$defs/end' }, blocking: { type: 'boolean' }, label: str, enabled: { type: 'boolean' }, edgeType: str, fields: { type: 'object' } },
      },
      end: { type: 'object', required: ['element', 'pip'], properties: { element: str, pip: { type: 'integer', minimum: 0 }, name: str } },
      projectSpec: {
        type: 'object', required: ['content'],
        properties: { language: { type: 'object', properties: { id: str, name: str } }, settings: { type: 'object' }, content: { type: 'object', description: 'Le projet au format kantoaplo.domino v2 (schéma domino.schema.json).' } },
      },
    },
  };

  D.API_VERSION = API_VERSION;
  D.Resource = Resource;
})(typeof globalThis !== 'undefined' ? globalThis : window);
