/*!
 * Zeugma · modes d'affichage des pierres
 *
 * Une même table peut se montrer de plusieurs façons. Un MODE dit deux choses :
 *  - ses métriques (l'échelle de la table : unité T, noms, étiquettes, profondeur des adjacentes),
 *    fixées PAR VUE (un onglet, un volet) : la géométrie des chaînes suppose une seule unité par partie ;
 *  - son dessin : ce qu'il ajoute autour d'une pierre (extent, compté par l'anti-collision) et comment
 *    il la dessine (render). Une pierre peut choisir son dessin (meta.display, ou display dans sa définition),
 *    jamais son échelle. Les points restent aux mêmes coordonnées dans tous les modes : fils, aimantation
 *    et clics ne changent pas.
 *
 * Modes livrés : stone (Pierre), compact (Compacte), card (Carte détaillée), outline (Contour).
 *
 *   Domino.Displays.register({
 *     id: 'badge', label: 'Badge', metrics: { T: 60 },
 *     extent: (ctx) => [{ x: 0, y: ctx.bounds.y2 + 4, w: 80, h: 16 }],     // repère de la pierre
 *     render: (ctx) => ({ svg: ctx.kit.svg + '<text …/>' }),                // null : le kit dessine
 *   });
 *   editor.setOption('display', 'card');
 *
 * ctx (render) : { ws, node, def, heading, T, w, h, data (faces, couleurs), kit ({ svg, headSvg }), deco (rects d'extent), editor }
 * ctx (extent) : { ws, node, def, heading, T, w, h, bounds ({ x1, y1, x2, y2 }) }
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const modes = new Map();
  const bus = new D.Emitter();
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  /** Une valeur en quelques caractères. */
  function short(v, max = 22) {
    if (v === undefined) return '—';
    if (v === null) return 'null';
    if (D.Context && D.Context.isBinding && D.Context.isBinding(v)) return `⟨${v.$bind}⟩`;
    if (v && typeof v === 'object' && typeof v.$ref === 'string') return `↪ ${v.$ref}`;
    if (typeof v === 'boolean') return v ? 'vrai' : 'faux';
    if (typeof v === 'number') return String(Math.round(v * 1000) / 1000);
    if (typeof v === 'string') { const s = v.replace(/\s+/g, ' '); return s.length > max ? `${s.slice(0, max - 1)}…` : s || '« »'; }
    if (Array.isArray(v)) return `[${v.length}]`;
    if (typeof v === 'object') { const k = Object.keys(v); return k.length ? `{${k.length} clé${k.length > 1 ? 's' : ''}}` : '{}'; }
    return String(v);
  }

  // ---------------------------------------------------------------------------
  // Carte détaillée : une fiche sous la pierre (points, champs, problèmes)
  // ---------------------------------------------------------------------------
  const CARD = { line: 17, pad: 7, max: 6, minW: 220 };
  /** Les lignes de la fiche d'une pierre : [{ kind: 'pips'|'field'|'diag'|'more', … }]. */
  function cardLines(ws, n) {
    const out = [];
    const { left, right } = ws.pipsOf(n);
    out.push({ kind: 'pips', left, right, label: ws.semanticsOf(n).label });
    for (const [k, f] of Object.entries(n.def.fields || {})) {
      if (f.hidden) continue;
      out.push({ kind: 'field', label: f.label || k, value: n.fields[k] !== undefined ? n.fields[k] : f.default, unit: f.unit });
    }
    for (const d of ws.diagnostics.get(n.id) || []) out.push({ kind: 'diag', level: d.level, text: d.message });
    if (n.note) out.push({ kind: 'note', text: n.note });
    if (out.length > CARD.max) { const more = out.length - (CARD.max - 1); out.length = CARD.max - 1; out.push({ kind: 'more', text: `+ ${more} de plus (I : inspecter)` }); }
    return out;
  }
  const cardBox = (ctx) => {
    const lines = cardLines(ctx.ws, ctx.node);
    const w = Math.max(ctx.w, CARD.minW);
    return { x: (ctx.w - w) / 2, y: ctx.bounds.y2 + 4, w, h: lines.length * CARD.line + CARD.pad * 2, lines };
  };
  function cardSVG(ctx, box) {
    const ws = ctx.ws, T = ws.types;
    const lines = box.lines || cardLines(ws, ctx.node);
    const rows = lines.map((l, i) => {
      const y = box.y + CARD.pad + (i + 0.72) * CARD.line;
      const x = box.x + 9;
      if (l.kind === 'pips') {
        const dots = (list, x0) => list.slice(0, 9).map((q, k) => `<circle cx="${(x0 + k * 9).toFixed(1)}" cy="${(y - 4).toFixed(1)}" r="3.2" fill="${esc(q.color || T.color(q.type))}"><title>${esc(q.name || q.type)} (${esc(T.label(q.type))})</title></circle>`).join('');
        const lw = Math.min(9, l.left.length) * 9;
        return `${dots(l.left, x + 3)}<text x="${(x + lw + 4).toFixed(1)}" y="${y.toFixed(1)}" class="dk-card-sem">→</text>${dots(l.right, x + lw + 18)}<text x="${(x + lw + 18 + Math.min(9, l.right.length) * 9 + 4).toFixed(1)}" y="${y.toFixed(1)}" class="dk-card-sem">${esc(l.label)}</text>`;
      }
      if (l.kind === 'field') return `<text x="${x}" y="${y.toFixed(1)}" class="dk-card-k">${esc(short(l.label, 14))}</text><text x="${(box.x + box.w - 9).toFixed(1)}" y="${y.toFixed(1)}" text-anchor="end" class="dk-card-v">${esc(short(l.value))}${l.unit ? ` ${esc(l.unit)}` : ''}</text>`;
      if (l.kind === 'diag') return `<text x="${x}" y="${y.toFixed(1)}" class="dk-card-d ${l.level === 'error' ? 'err' : 'warn'}">${l.level === 'error' ? '⛔' : '⚠'} ${esc(short(l.text, 34))}</text>`;
      if (l.kind === 'note') return `<text x="${x}" y="${y.toFixed(1)}" class="dk-card-n">✎ ${esc(short(l.text, 34))}</text>`;
      return `<text x="${x}" y="${y.toFixed(1)}" class="dk-card-m">${esc(l.text)}</text>`;
    }).join('');
    return `<g class="dk-card" pointer-events="none"><path d="M${(ctx.w / 2).toFixed(1)} ${(ctx.h).toFixed(1)} V${box.y.toFixed(1)}" class="dk-card-stem"/><rect x="${box.x.toFixed(1)}" y="${box.y.toFixed(1)}" width="${box.w.toFixed(1)}" height="${box.h.toFixed(1)}" rx="7"/>${rows}</g>`;
  }

  // ---------------------------------------------------------------------------
  // Contour : un trait, un titre, des coches de couleur aux points (impression, thème sombre)
  // ---------------------------------------------------------------------------
  function outlineSVG(ctx) {
    const { w, h, T } = ctx, K = root.DominoKit;
    const v = h > w;
    const r = T * 0.13;
    const pips = [];
    if (K && K.pipXY) {
      const o = ctx.orient || {};
      for (const [side, list] of [['in', ctx.data.inPips || []], ['out', ctx.data.outPips || []]]) {
        if (!list.length) continue;
        K.pipXY(list.length, side, T, o.orient, o.flip).forEach((q, i) => pips.push(`<circle cx="${q.x.toFixed(1)}" cy="${q.y.toFixed(1)}" r="${(q.r * 0.9).toFixed(1)}" fill="${esc(list[i] || 'currentColor')}" stroke="var(--panel)" stroke-width="1"/>`));
      }
    }
    const div = v ? `<path d="M${(T * 0.18).toFixed(1)} ${T} H${(w - T * 0.18).toFixed(1)}"/>` : `<path d="M${T} ${(T * 0.18).toFixed(1)} V${(h - T * 0.18).toFixed(1)}"/>`;
    const tint = ctx.data.inFace || ctx.data.outFace;
    return `<g class="dk-outline"><rect class="t-ring" fill="none" x="-4" y="-4" width="${w + 8}" height="${h + 8}" rx="${r + 4}"/><rect class="t-face" x="0.6" y="0.6" width="${(w - 1.2).toFixed(1)}" height="${(h - 1.2).toFixed(1)}" rx="${r.toFixed(1)}"${tint ? ` style="fill:color-mix(in srgb, ${esc(tint)} 18%, var(--raised))"` : ''}/>${div}${pips.join('')}</g>`;
  }

  // ---------------------------------------------------------------------------
  // Registre
  // ---------------------------------------------------------------------------
  const Displays = {
    /**
     * @param {{ id: string, label: string, description?: string, metrics?: { T?, names?, labels?, maxDepth?, headerSize? },
     *           extent?: (ctx) => Array<{x,y,w,h}>, render?: (ctx) => ({ svg, headSvg? }|null), pioche?: 'kit'|'self' }} mode
     */
    register(mode) {
      if (!mode || !mode.id) throw new D.DominoError('display.id', 'Un mode d’affichage a un identifiant.');
      const m = { label: mode.id, metrics: {}, ...mode };
      modes.set(m.id, m);
      bus.emit('register', { id: m.id });
      return () => { if (modes.get(m.id) === m) { modes.delete(m.id); bus.emit('unregister', { id: m.id }); } };
    },
    get(id) { return modes.get(id) || modes.get('stone'); },
    has(id) { return modes.has(id); },
    list() { return [...modes.values()]; },
    /** Le dessin d'une pierre dans une vue : meta.display, puis display de sa définition, puis le mode de la vue. */
    resolve(editor, node) {
      const own = (node.meta && node.meta.display) || (node.def && node.def.display);
      if (own && modes.has(own)) return modes.get(own);
      return Displays.get(editor && editor.o ? editor.o.display : 'stone');
    },
    on(type, fn) { return bus.on(type, fn); },
    cardLines, short,
  };

  Displays.register({ id: 'stone', label: 'Pierre', description: 'La pierre de domino : faces, points, relief, nom en entête.', metrics: { T: 72, names: true, labels: true, maxDepth: 3 } });
  Displays.register({ id: 'compact', label: 'Compacte', description: 'Plus petite et sans entête : pour voir de grands projets d’un coup d’œil (le nom reste au survol et pour les lecteurs d’écran).', metrics: { T: 44, names: false, labels: false, maxDepth: 2 } });
  Displays.register({
    id: 'card', label: 'Carte détaillée', description: 'La pierre et sa fiche : points et leurs types, champs et leurs valeurs, problèmes, note.',
    metrics: { T: 72, names: true, labels: true, maxDepth: 3 },
    extent: (ctx) => { const b = cardBox(ctx); return [{ x: b.x, y: b.y, w: b.w, h: b.h }]; },
    render: (ctx) => {
      const deco = ctx.deco && ctx.deco[0];
      const box = deco ? { ...deco, lines: cardLines(ctx.ws, ctx.node) } : cardBox({ ...ctx, bounds: { y2: ctx.h + 8 } });
      return { svg: ctx.kit.svg + cardSVG(ctx, box) };
    },
  });
  Displays.register({ id: 'outline', label: 'Contour', description: 'Un trait et des points de couleur : sobre, lisible à l’impression et en thème sombre.', metrics: { T: 56, names: true, labels: true, maxDepth: 3 }, render: (ctx) => ({ svg: outlineSVG(ctx) }) });

  D.Displays = Displays;
})(typeof globalThis !== 'undefined' ? globalThis : window);
