/*!
 * Zeugma · générateurs
 * Un générateur transforme le JSON d'un projet en texte (code, configuration, documentation).
 * Il ne lit QUE le JSON : n'importe qui peut écrire le sien, dans le navigateur ou sur un serveur.
 *
 *   const g = new Domino.Generator('express', { extension: 'js' });
 *   g.forType('api.route', (node, g) => `app.${node.fields.method.toLowerCase()}('${node.fields.path}', …)`);
 *   g.generate(editor.toJSON());
 */
(function (root) {
  'use strict';
  const D = root.Domino;

  class Generator {
    /**
     * @param {string} name
     * @param {{ label?: string, extension?: string, indent?: string, language?: string }} o
     */
    constructor(name, o = {}) {
      this.name = name;
      this.label = o.label || name;
      this.extension = o.extension || 'txt';
      this.language = o.language || this.extension;
      this.indentUnit = o.indent || '  ';
      this.byType = new Map();
      this.wireList = [];
      this.hooks = { project: null, partie: null, chain: null, missing: null };
    }
    /** Fonction de génération d'un type de pierre : (node, g) => string. */
    forType(type, fn) { this.byType.set(type, fn); return this; }
    forTypes(map) { Object.entries(map).forEach(([k, fn]) => this.forType(k, fn)); return this; }
    /** Enveloppes : projet, partie, chaîne, pierre sans générateur. */
    on(name, fn) { this.hooks[name] = fn; return this; }

    /** Génère à partir du JSON d'un projet (ou d'un espace, converti en JSON). */
    generate(input) {
      let json = input && input.nodes instanceof Map ? D.Serializer.toJSON(input) : input;
      if (D.Resource && D.Resource.isResource(json)) json = D.Resource.unwrap(json);
      this.json = json;
      this.index = new Map();
      const walk = (n, parent, via) => {
        this.index.set(n.id, { node: n, parent, via });
        for (const v of ['top', 'bottom', 'next']) (n[v] || []).forEach((a) => walk(a.domino, n, v));
      };
      json.parties.forEach((p) => (p.dominos || []).forEach((n) => walk(n, null, null)));
      this.wireList = json.wires || [];
      const parties = json.parties.map((p) => (this.hooks.partie ? this.hooks.partie(p, this) : this.chains(p.dominos || []).join('\n\n')));
      return this.hooks.project ? this.hooks.project(json, this, parties) : parties.filter(Boolean).join('\n\n');
    }
    /** Génère chaque chaîne d'une liste de têtes. */
    chains(heads) { return heads.map((h) => (this.hooks.chain ? this.hooks.chain(h, this) : this.chain(h))).filter((s) => s !== ''); }
    /** Une chaîne : la pierre, puis sa suite principale. Les branches sont laissées au générateur de la pierre. */
    chain(node, sep = '\n') {
      const out = [];
      for (let n = node; n; n = this.next(n, 0)) out.push(this.node(n));
      return out.filter((s) => s !== '').join(sep);
    }
    node(n) {
      const fn = this.byType.get(n.type);
      if (fn) return fn(n, this);
      return this.hooks.missing ? this.hooks.missing(n, this) : `/* ${n.type} : pas de générateur */`;
    }
    /** Pierre suivante sur la sortie n° pip (ou null). */
    next(n, pip = 0) { const l = (n.next || []).find((x) => x.pip === pip); return l ? l.domino : null; }
    link(n, pip = 0) { return (n.next || []).find((x) => x.pip === pip) || null; }
    /** Adjacentes hautes qui alimentent l'entrée n° pip. */
    top(n, pip) { return (n.top || []).filter((a) => pip == null || a.pip === pip).map((a) => a.domino); }
    bottom(n, pip) { return (n.bottom || []).filter((a) => pip == null || a.pip === pip).map((a) => a.domino); }
    /** Code de la valeur qui alimente l'entrée n° pip (adjacente haute), ou `fallback`. */
    valueOf(n, pip, fallback = 'undefined') { const a = this.top(n, pip)[0]; return a ? this.node(a) : fallback; }
    parentOf(n) { const e = this.index.get(n.id); return e ? e.parent : null; }
    partie(id) { return this.json.parties.find((p) => p.id === id) || null; }
    indent(text, level = 1) { const pad = this.indentUnit.repeat(level); return String(text).split('\n').map((l) => (l ? pad + l : l)).join('\n'); }
    /** Valeur d'un champ, liée au contexte du projet si c'est une liaison. */
    field(n, key) {
      const v = (n.fields || {})[key];
      if (D.Context.isBinding(v)) { const r = D.getPath(this.json.context || {}, v.$bind); return r === undefined ? `\${${v.$bind}}` : r; }
      return v;
    }
    /** Liste à plat de toutes les pierres (ordre de lecture). */
    all() { return [...this.index.values()].map((e) => e.node); }
    /** Une pierre par son identifiant. */
    byId(id) { const e = this.index.get(id); return e ? e.node : null; }
    /** Fils entrants d'une pierre (sur l'entrée n° pip, ou tous). */
    wiresInto(n, pip) { return this.wireList.filter((w) => w.to.domino === n.id && (pip == null || w.to.pip === pip)); }
    /** Fils sortants d'une pierre (depuis la sortie n° pip, ou tous). */
    wiresFrom(n, pip) { return this.wireList.filter((w) => w.from.domino === n.id && (pip == null || w.from.pip === pip)); }
    /**
     * Ce qui alimente l'entrée n° pip : { via: 'top'|'wire'|'prev', node, pip?, wire? } ou null.
     * 'prev' : la pierre précédente de la chaîne (selon le câblage `map` de la connexion).
     */
    source(n, pip) {
      const a = this.top(n, pip)[0];
      if (a) return { via: 'top', node: a };
      const w = this.wiresInto(n, pip)[0];
      if (w) return { via: 'wire', node: this.byId(w.from.domino), pip: w.from.pip, wire: w };
      const e = this.index.get(n.id);
      if (e && e.via === 'next') {
        const l = (e.parent.next || []).find((x) => x.domino === n);
        if (l && (l.map || [0]).includes(pip)) return { via: 'prev', node: e.parent, pip: l.pip };
      }
      return null;
    }
    /** Partie qui contient une pierre. */
    partieOf(n) { for (const p of this.json.parties) { const ids = new Set(); const walk = (d) => { ids.add(d.id); for (const v of ['top', 'bottom', 'next']) (d[v] || []).forEach((a) => walk(a.domino)); }; (p.dominos || []).forEach(walk); if (ids.has(n.id)) return p; } return null; }
    /** Déclarations du projet (classes, bibliothèques, fonctions) avec leur signature et leur corps. */
    declarations() {
      const decl = this.json.parties.find((p) => p.kind === 'declarations');
      if (!decl || !D.Modules) return [];
      return (decl.dominos || []).filter((d) => D.Modules.KINDS[d.type]).map((d) => {
        const body = this.json.parties.find((p) => p.owner === d.id);
        return { node: d, body, signature: D.Modules.signatureFromJSON(this.json, d.id) };
      });
    }
  }
  D.Generator = Generator;
})(typeof globalThis !== 'undefined' ? globalThis : window);
