/*!
 * Zeugma · registre des générateurs (point d'extension)
 *
 * Un générateur transforme un projet en texte : du code (JavaScript, Python, SQL…), une configuration,
 * une documentation, un diagramme. Il s'inscrit ici avec un DESCRIPTEUR ; le studio le propose dans
 * « Exécuter › Générer ▸ » et l'inspecteur dans l'onglet Code, pour les langages qu'il sert.
 *
 *   Domino.Codegen.register({
 *     id: 'kanto/python', language: 'kanto', target: 'python', label: 'Python', extension: 'py',
 *     input: 'model',                              // 'project' (JSON v2, par défaut) ou 'model' (document de modèle)
 *     options: { indent: { kind: 'number', default: 4 } },
 *     generate(ctx) {                              // ctx.json, ctx.model(), ctx.options, ctx.file(), ctx.log()
 *       ctx.file('main.py', '…');                  // plusieurs fichiers…
 *       return '…';                                // … ou un seul texte
 *     },
 *   });
 *   Domino.Codegen.run('kanto/python', editor.ws)  // → { files: [{ path, content, mime }], diagnostics, text }
 *                                                  //   (une promesse si generate(ctx) en rend une : runAsync l'attend toujours)
 *   ctx.call(déclaration, membre, args)            // appelle une méthode du projet par le moteur (promesse)
 *
 * `language: '*'` sert tous les langages (un générateur de documentation, de diagramme…).
 * Les générateurs d'un langage (spec.generators, classe Domino.Generator) y sont inscrits d'eux-mêmes,
 * sous l'identifiant « langage/nom » : editor.generate(nom) continue de marcher.
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const reg = new Map();
  const adopted = new WeakSet();
  const bus = new D.Emitter();
  const MIME = { js: 'text/javascript', mjs: 'text/javascript', ts: 'text/typescript', json: 'application/json', yaml: 'application/yaml', yml: 'application/yaml', md: 'text/markdown', mmd: 'text/plain', html: 'text/html', css: 'text/css', py: 'text/x-python', sql: 'application/sql', svg: 'image/svg+xml', xml: 'application/xml', gift: 'text/plain', txt: 'text/plain' };
  const mimeOf = (path) => MIME[String(path).split('.').pop().toLowerCase()] || 'text/plain';

  function normalize(d) {
    if (!d || typeof d.id !== 'string' || !/^[\w.-]+(\/[\w.-]+)?$/.test(d.id)) throw new D.DominoError('codegen.id', `Un générateur a un identifiant « langage/cible » (reçu « ${d && d.id} »).`);
    if (typeof d.generate !== 'function' && typeof d.create !== 'function') throw new D.DominoError('codegen.fn', `Le générateur « ${d.id} » n’a ni generate(ctx) ni create(D).`);
    const extension = d.extension || 'txt';
    return { language: '*', target: extension, label: d.id, input: 'project', options: {}, ...d, extension, mime: d.mime || mimeOf(`x.${extension}`) };
  }

  /** Le projet v2 à partir d'un espace, d'une ressource ou d'un v2. */
  function toProject(input) {
    if (input && input.nodes instanceof Map) return D.Serializer.toJSON(input);
    if (D.Resource && D.Resource.isResource(input)) return D.Resource.unwrap(input);
    return input;
  }
  /** Le document de modèle : depuis l'espace vivant si on l'a, sinon en rechargeant le JSON sans vue. */
  function toModel(input, json, runtime) {
    if (input && input.nodes instanceof Map) return D.describe(input, { runtime });
    const id = json && json.editor && json.editor.id;
    const L = D.Languages ? D.Languages.get(id) : D.packs && D.packs[id];
    if (!L) throw new D.DominoError('codegen.language', `Le langage « ${id} » n’est pas inscrit : impossible de construire le document de modèle.`);
    return D.describe(D.language(L).instantiate(json).ws);
  }

  /** « kanto/javascript » : les générateurs du langage kanto sont adoptés à la première demande. */
  function ensure(id) {
    if (reg.has(id)) return;
    const lang = String(id).split('/')[0];
    const L = D.Languages ? D.Languages.get(lang) : null;
    if (L) Codegen.adopt(L);
  }

  const Codegen = {
    mimeOf,
    /**
     * Inscrit un générateur. Rend une fonction qui le retire.
     * @param {{ id: string, language?: string, target?: string, label?: string, extension?: string, mime?: string,
     *           input?: 'project'|'model', options?: object, description?: string,
     *           generate?: (ctx) => (string|{files, diagnostics}), create?: (D) => Domino.Generator }} descriptor
     */
    register(descriptor) {
      const d = normalize(descriptor);
      reg.set(d.id, d);
      bus.emit('register', { id: d.id });
      return () => { if (reg.get(d.id) === d) { reg.delete(d.id); bus.emit('unregister', { id: d.id }); } };
    },
    get(id) { ensure(id); return reg.get(id) || null; },
    list() { return [...reg.values()]; },
    /** Les générateurs d'un langage : les siens d'abord, puis les génériques (« * »). */
    forLanguage(langId) {
      const L = D.Languages ? D.Languages.get(langId) : null;
      if (L) Codegen.adopt(L);
      const all = [...reg.values()];
      return [...all.filter((d) => d.language === langId), ...all.filter((d) => d.language === '*')];
    },
    targets(langId) { return [...new Set(Codegen.forLanguage(langId).map((d) => d.target))]; },
    /** Inscrit les générateurs d'un langage (spec.generators) sous « langage/nom ». Idempotent. */
    adopt(lang) {
      const L = D.language(lang);
      if (adopted.has(L)) return;
      adopted.add(L);
      for (const g0 of L.generators || []) {
        const g = typeof g0 === 'function' && !(g0.prototype instanceof D.Generator) ? g0(D) : g0;
        if (!g) continue;
        // Un descripteur (generate(ctx)) déclaré par le langage, ou une instance de Domino.Generator.
        if (!(g instanceof D.Generator) && typeof g.generate === 'function' && (g.id || g.name)) {
          const id = String(g.id || g.name).includes('/') ? g.id : `${L.id}/${g.id || g.name}`;
          if (!reg.has(id)) Codegen.register({ ...g, id, language: g.language || L.id });
          continue;
        }
        if (!g.name) continue;
        const id = `${L.id}/${g.name}`;
        if (!reg.has(id)) Codegen.register({ id, language: L.id, target: g.language || g.extension, label: g.label, extension: g.extension, description: g.description, input: 'project', create: () => g });
      }
    },
    /**
     * Exécute un générateur. L'entrée est un espace (ws), un projet v2 ou une ressource.
     * @returns {{ id, files: Array<{ path, content, mime }>, diagnostics: Array<{ level, message, element? }>, text: string }}
     */
    run(id, input, { options = {}, runtime = null, name } = {}) {
      ensure(id);
      const d = reg.get(id);
      if (!d) throw new D.DominoError('codegen.unknown', `Générateur inconnu : « ${id} ».`);
      const json = toProject(input);
      const files = [], diagnostics = [];
      let model = null;
      const opts = {};
      for (const [k, f] of Object.entries(d.options || {})) opts[k] = options[k] !== undefined ? options[k] : f.default;
      Object.assign(opts, options);
      const base = D.Resource ? D.Resource.slug(name || (json && json.name) || 'projet') : 'projet';
      const live = input && input.nodes instanceof Map ? input : null;
      let rt = runtime;
      const ctx = {
        /**
         * Appelle un membre d'une déclaration du projet (méthode d'une classe, fonction), par le moteur :
         * un générateur peut demander des données à une classe (rend une promesse). Seulement quand
         * l'entrée est un espace vivant (ou rechargeable depuis son langage).
         */
        call: (declId, member, args) => {
          if (!rt) {
            const ws = live || (() => { const L = D.Languages && json && json.editor ? D.Languages.get(json.editor.id) : null; return L ? D.language(L).instantiate(json).ws : null; })();
            if (!ws) return Promise.reject(new D.DominoError('codegen.call', 'Aucun moteur pour appeler la déclaration.'));
            rt = new D.Runtime(ws);
          }
          return rt.call(declId, member, args || []);
        },
        json, options: opts, descriptor: d, D,
        language: json && json.editor ? json.editor.id : null,
        model: () => (model ||= toModel(input, json, runtime)),
        file(path, content, mime) { files.push({ path: String(path), content: String(content), mime: mime || mimeOf(path) }); },
        log(level, message, element) { diagnostics.push(D.compact({ level, message, element })); },
      };
      const finish = (out) => {
        if (typeof out === 'string') files.unshift({ path: `${base}.${d.extension}`, content: out, mime: d.mime });
        else if (out && typeof out === 'object') {
          for (const f of out.files || []) files.push({ path: String(f.path), content: String(f.content), mime: f.mime || mimeOf(f.path) });
          diagnostics.push(...(out.diagnostics || []));
        }
        return { id, files, diagnostics, text: files.map((f) => (files.length > 1 ? `// ── ${f.path}\n${f.content}` : f.content)).join('\n\n') };
      };
      const out = d.generate ? d.generate(ctx) : d.create(D).generate(d.input === 'model' ? ctx.model() : json);
      // Un générateur asynchrone (qui interroge le moteur, une API…) : run rend alors une promesse.
      return out && typeof out.then === 'function' ? out.then(finish) : finish(out);
    },
    /** Comme run, mais rend toujours une promesse (générateurs synchrones ou non). */
    async runAsync(id, input, o) { return Codegen.run(id, input, o); },
    on(type, fn) { return bus.on(type, fn); },
  };

  D.Codegen = Codegen;
})(typeof globalThis !== 'undefined' ? globalThis : window);
