  // ---------------------------------------------------------------------------
  // Bus d'événements. `*` reçoit tout. Un écouteur qui lève une erreur n'arrête pas les autres.
  // ---------------------------------------------------------------------------
  class Emitter {
    constructor() { this._l = new Map(); }
    /** @returns {() => void} une fonction qui retire l'écouteur */
    on(type, fn) {
      if (!this._l.has(type)) this._l.set(type, new Set());
      this._l.get(type).add(fn);
      return () => this.off(type, fn);
    }
    once(type, fn) {
      const off = this.on(type, (e) => { off(); fn(e); });
      return off;
    }
    off(type, fn) { const s = this._l.get(type); if (s) s.delete(fn); }
    emit(type, event) {
      for (const key of [type, '*']) {
        const s = this._l.get(key);
        if (!s) continue;
        for (const fn of [...s]) {
          try { fn(event); } catch (err) { if (typeof console !== 'undefined') console.error(`[Domino] écouteur « ${type} » :`, err); }
        }
      }
    }
  }
  D.Emitter = Emitter;

  // ---------------------------------------------------------------------------
  // Erreurs : un code stable (pour le code), un message lisible (pour l'utilisateur), des détails.
  // ---------------------------------------------------------------------------
  class DominoError extends Error {
    constructor(code, message, details = {}) {
      super(message);
      this.name = 'DominoError';
      this.code = code;
      this.details = details;
    }
  }
  D.DominoError = DominoError;

