          shape: { kind: 'select', label: 'Forme (diagramme)', options: SHAPES, default: '', group: 'Comportement' },
          behaviour: { kind: 'json', label: 'Comportement (avancé)', default: {}, group: 'Comportement', help: '{ validate, faces, pips, canConnect, run } : des expressions, jamais de code.' },
