    spec.rules = rules;
    if (F.engine && F.engine !== 'dataflow') spec.execution = { engine: F.engine };
    const views = String(F.views || '').split(',').map((x) => x.trim()).filter(Boolean);
    const pj = D.compact({ default: F.projection && F.projection !== 'dominos' ? F.projection : undefined, list: views.length ? views : undefined, diagram: F.algo && F.algo !== 'layered' ? { algo: F.algo } : undefined });
