    const tb = parseJSON(F.toolbox, 'Langage, boîte à outils', errors);
    if (tb && !empty(tb)) {
      spec.toolbox = tb;
      if (D.Toolbox) D.Toolbox.check(tb).forEach((p) => errors.push({ where: 'Langage, boîte à outils', dominoId: 'lang', message: `${p.path ? `${p.path} : ` : ''}${p.message}` }));
    }
