/*!
 * Zeugma · définitions de pierres
 * Une définition est un objet JSON (sérialisable) plus, facultativement, des callbacks.
 * Les clés dont la valeur est une fonction sont des callbacks ; tout le reste est la définition JSON.
 * Un callback peut aussi être écrit en texte (`code: { run: 'return [inputs[0] * 2]' }`) :
 * un langage entier peut alors vivre dans un fichier JSON.
 *
 *   registry.define({
 *     type: 'mw.auth', name: 'Auth JWT', category: 'Middlewares', kind: 'middleware',
 *     left:  [{ name: 'req', type: 'request' }, { name: 'secret', type: 'secret' }],
 *     right: [{ name: 'req', type: 'request' }],
 *     meaning: { left: 'ce qu’il faut pour vérifier', right: 'la requête autorisée' },
 *     fields: { scheme: { kind: 'select', options: ['bearer', 'basic'], default: 'bearer' } },
 *     run(rc) { … }, validate(api) { … },
 *   });
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const t = (k, p) => D.i18n.t(k, p);

  /** Callbacks reconnus. Tous reçoivent une API (voir model.js : `api`) donnant accès à la pierre, à l'espace et au contexte. */
  const HOOKS = {
    init: 'Une fois, à la création de l’instance (avant les événements).',
    title: 'Rend le nom affiché (ex. « GET /users » d’après les champs).',
    pips: 'Rend { left, right } selon l’instance : les faces changent avec les champs, les fils ou les adjacentes.',
    onCreate: 'Après l’ajout dans l’espace.',
    onDispose: 'Avant la suppression.',
    onChange: 'Après le changement d’un champ, du sens ou d’une connexion de la pierre.',
    onConnect: 'Après qu’une pierre s’est collée à celle-ci (suite, adjacente haute ou basse).',
    onDisconnect: 'Après qu’une pierre s’en est détachée.',
    onAttach: 'Après que cette pierre s’est collée à une autre.',
    onDetach: 'Après que cette pierre s’est détachée.',
    onWire: 'Après qu’un fil a relié un point de cette pierre (en entrée ou en sortie).',
    onUnwire: 'Après qu’un fil relié à cette pierre a été retiré.',
    canConnect: 'Dernier mot sur un assemblage ou un fil : rend true, ou une phrase qui explique le refus.',
    validate: 'Rend des diagnostics { level, message } propres au domaine.',
    run: 'Exécute la pierre (effet domino) : reçoit les entrées, rend les sorties. Peut être asynchrone.',
    contextMenu: 'Complète ou remplace les entrées du menu contextuel.',
    render: 'Décore ou remplace le dessin SVG de la pierre.',
    inspect: 'Ajoute des sections à l’inspecteur pour cette pierre.',
    onSelect: 'Quand la pierre est sélectionnée.',
    faces: 'Rend { left, right } : la couleur de chaque façade selon l’instance (état, déclaration…).',
  };

  /**
   * Genres de champs. `expr` : une expression déclarative (domino.expr.js), écrite en texte, enregistrée en JSON.
   * `table` : des lignes dont chaque colonne est elle-même un champ (`columns`), pour des listes de choix, de cas…
   */
  const FIELD_KINDS = ['text', 'textarea', 'number', 'select', 'toggle', 'code', 'color', 'json', 'list', 'ref', 'expr', 'table'];
  const COLUMN_KINDS = ['text', 'number', 'toggle', 'select', 'expr', 'color'];
  /** Ce qu'un renvoi (champ `ref`) peut viser. */
  const REF_TO = ['domino', 'partie', 'declaration', 'variable'];
  /**
   * Vocabulaire de « ce que représente » une pierre. Libre : un langage peut employer ses propres mots ;
   * ceux-ci sont reconnus par l'inspecteur et le document de modèle.
   */
  const REPRESENTS = ['valeur', 'variable', 'constante', 'expression', 'instruction', 'ligne', 'condition', 'boucle', 'fonction', 'méthode', 'classe', 'instance', 'module', 'bibliothèque', 'projet', 'scénario', 'workflow', 'algorithme', 'événement', 'déclencheur', 'action', 'service', 'règle', 'concept', 'idée', 'argument', 'mécanisme', 'état', 'donnée', 'renvoi', 'pièce'];
  /** Clés connues d'une définition : les autres sont signalées (registry.warnings), pas refusées. */
  const KNOWN = new Set(['type', 'name', 'category', 'description', 'help', 'kind', 'represents', 'meaning', 'left', 'right', 'chain', 'wires', 'where', 'async', 'top', 'bottom', 'fields', 'container', 'inside', 'faces', 'tint', 'identity', 'tags', 'hidden', 'code', 'constraints', 'version', 'deprecated', 'examples', 'extra', 'docs', 'icon', 'display', 'traits', 'behaviour', 'roles', 'notation']);
  /** Où une pierre peut se poser : la partie principale, un corps de déclaration, un composant, la table des déclarations. */
  const WHERE = ['main', 'body', 'component', 'declarations'];

  function normPips(list, side) {
    if (typeof list === 'number') list = Array.from({ length: list }, () => ({}));
    if (!Array.isArray(list)) list = [];
    return list.map((p, i) => {
      if (typeof p === 'string') p = { type: p };
      return D.compact({
        name: p.name || `${side === 'left' ? 'entrée' : 'sortie'} ${i + 1}`,
        type: p.type || 'any',
        label: p.label,
        accepts: p.accepts,
        required: side === 'left' ? p.required !== false : undefined,
        color: p.color, // couleur imposée au point, sinon celle du type
        help: p.help,
        wire: p.wire === false ? false : undefined, // false : ce point ne se relie pas par un fil
        multiple: side === 'left' && p.multiple ? true : undefined, // une entrée qui reçoit plusieurs fils (liste)
        signature: p.signature, // point « call » : ce que la fonction attend et rend
      });
    });
  }

  /** L'intérieur d'une pierre : { kind, partie, template, title }. */
  function inside(v) {
    if (!v) return null;
    if (v === true) return { kind: 'Composant', partie: 'component', template: null };
    return D.compact({ kind: v.kind || 'Composant', partie: v.partie || 'component', template: Array.isArray(v.template) ? v.template : undefined, title: v.title }) ;
  }
  /**
   * Contraintes et permissions d'une pierre (au-delà des faces et des types) :
   *   deletable, movable, editable, duplicable : ce que l'utilisateur peut faire (l'API garde la main) ;
   *   max, maxPerPartie : nombre d'exemplaires ;
   *   allow / deny : quelles pierres (types ou genres, '*' pour toutes) peuvent la suivre (`next`), la précéder (`prev`),
   *   l'alimenter (`top`), la consommer (`bottom`), lui envoyer un fil (`wireIn`), en recevoir un (`wireOut`).
   */
  function constraints(c = {}) {
    c = c || {};
    const list = (o) => (o ? Object.fromEntries(Object.entries(o).map(([k, v]) => [k, [].concat(v)])) : null);
    return {
      deletable: c.deletable !== false, movable: c.movable !== false, editable: c.editable !== false, duplicable: c.duplicable !== false,
      max: c.max || null, maxPerPartie: c.maxPerPartie || null, allow: list(c.allow), deny: list(c.deny),
    };
  }

  /** Callback écrit en texte : `run` reçoit rc (et inputs, fields, ctx, log) ; les autres reçoivent api. */
  const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
  function compileHook(type, name, src) {
    const pre = name === 'run' ? 'const rc = arg0; const { inputs, fields, ctx, log } = arg0;\n' : 'const api = arg0;\n';
    let fn;
    try { fn = new (/\bawait\b/.test(src) ? AsyncFunction : Function)('arg0', 'arg', 'D', `"use strict";\n${pre}${src}`); } catch (err) {
      throw new D.DominoError('def.code', `« ${type} » : le code de ${name}() ne se compile pas : ${err.message}`, { type, hook: name });
    }
    const wrapped = function (a0, arg) { return fn(a0, arg, D); };
    wrapped.source = src;
    return wrapped;
  }

  /**
   * Ce que veulent dire les deux faces. Zéro n'est pas « rien » : c'est une règle.
   * 0 à gauche : la pierre ne se colle après rien (elle commence, ou elle alimente).
   * 0 à droite : rien ne la suit (elle termine, ou elle consomme).
   * Une pierre « libre » (chain: false) ne se colle pas : elle se pose et se relie par des fils.
   * Un langage peut remplacer cette lecture (option `semantics` du langage).
   */
  function semantics(left, right, def) {
    if (def && def.kind === 'declaration') {
      return { role: 'declaration', label: t('role.declaration'), text: t('role.declaration.text', { left, right }), canFollow: false, canPrecede: false, canBeTop: false, canBeBottom: false, startsChain: false, endsChain: false };
    }
    if (def && def.chain === false) {
      return { role: 'free', label: t('role.free'), text: t('role.free.text', { left, right }), canFollow: false, canPrecede: false, canBeTop: false, canBeBottom: false, startsChain: false, endsChain: false };
    }
    const role = !left && !right ? 'value' : !left ? 'source' : !right ? 'terminal' : 'step';
    return {
      role,
      label: t(`role.${role}`),
      text: t(`role.${role}.text`, { left, right }),
      canFollow: left > 0,          // se coller après une autre pierre
      canPrecede: right > 0,        // être suivie
      canBeTop: right > 0 || role === 'value', // alimenter une entrée (adjacente haute)
      canBeBottom: left > 0,        // consommer une sortie (adjacente basse)
      startsChain: left === 0,
      endsChain: right === 0,
    };
  }

  /** Normalise les champs d'une définition (pierre ou lien) : genre, bornes, motif, renvoi, colonnes d'un tableau. */
  function normFields(owner, spec) {
    const fields = {};
    for (const [key, f] of Object.entries(spec || {})) {
      const kind = f.kind || (typeof f.default === 'number' ? 'number' : typeof f.default === 'boolean' ? 'toggle' : 'text');
      if (!FIELD_KINDS.includes(kind)) throw new D.DominoError('def.field', `« ${owner} » : le champ « ${key} » a un genre inconnu « ${kind} » (${FIELD_KINDS.join(', ')}).`);
      if (kind === 'ref' && f.to && ![].concat(f.to).every((x) => REF_TO.includes(x) || typeof x === 'string')) throw new D.DominoError('def.field', `« ${owner} » : le renvoi « ${key} » vise ${REF_TO.join(', ')} ou des types de pierres.`);
      if (f.pattern) { try { new RegExp(f.pattern, 'u'); } catch (err) { throw new D.DominoError('def.field', `« ${owner} » : le motif du champ « ${key} » est invalide : ${err.message}`); } }
      let columns;
      if (kind === 'table') {
        if (!f.columns || typeof f.columns !== 'object' || !Object.keys(f.columns).length) throw new D.DominoError('def.field', `« ${owner} » : le tableau « ${key} » a besoin de colonnes (columns).`);
        columns = {};
        for (const [ck, c] of Object.entries(f.columns)) {
          const cKind = c.kind || 'text';
          if (!COLUMN_KINDS.includes(cKind)) throw new D.DominoError('def.field', `« ${owner} » : la colonne « ${ck} » du tableau « ${key} » a un genre inconnu « ${cKind} » (${COLUMN_KINDS.join(', ')}).`);
          columns[ck] = D.compact({ kind: cKind, label: c.label || ck, default: c.default, options: c.options, required: c.required || undefined, min: c.min, max: c.max, placeholder: c.placeholder, help: c.help, width: c.width });
        }
      }
      // Un champ dit ce qu'il accepte : requis, bornes, motif, options (liste ou fonction de l'instance), renvoi, validation.
      fields[key] = D.compact({
        kind, label: f.label || key, default: f.default, options: f.options, bindable: f.bindable !== false && kind !== 'ref', help: f.help, placeholder: f.placeholder,
        required: f.required || undefined, min: f.min, max: f.max, pattern: f.pattern, to: kind === 'ref' ? f.to || 'domino' : undefined,
        unit: f.unit, group: f.group, hidden: f.hidden || undefined, readonly: f.readonly || undefined, validate: typeof f.validate === 'function' ? f.validate : undefined,
        // Un renvoi « saut » : l'exécution continue à la pierre visée (domino.goto, ou tout champ qui le demande).
        jump: kind === 'ref' && f.jump ? true : undefined,
        columns, vars: f.vars,
      });
      if (kind === 'expr' || kind === 'table') fields[key].bindable = false;
      }
    return fields;
  }

  /** Un genre de lien permet-il ces deux bouts ? (types, genres, ou « ce que représente ») */
  D.edgeAllows = (e, a, b) => {
    const fits = (list, n) => !list || !n || list.includes('*') || list.includes(n.type) || (n.def && (list.includes(n.def.kind) || list.includes(n.def.represents)));
    return fits(e.from, a) && fits(e.to, b);
  };
  D.normFields = (owner, spec) => normFields(owner, spec);

  class Registry {
    /**
     * @param {InstanceType<typeof D.TypeSystem>} types
     * @param {{ semantics?: (left:number, right:number, def:object, base:object) => object }} [o]
     *        `semantics` : la lecture des faces propre au langage (reçoit aussi la lecture par défaut).
     */
    constructor(types, o = {}) {
      this.types = types || new D.TypeSystem();
      /** @type {Map<string, object>} */
      this.defs = new Map();
      this.custom = o.semantics || null;
      /** Définitions calculées (modules : instances, appels de fonctions déclarées). { get(type), list() } */
      this.resolvers = [];
      /** Ce qui ne bloque pas mais mérite d'être su : clés inconnues, pierres dépréciées… */
      this.warnings = [];
      /** Genres de liens (fils typés) : transition, relation, flux… avec leurs champs. */
      this.edges = new Map();
      D.builtins(this);
    }
    /**
     * Un genre de lien : un fil qui porte des champs (événement, garde, cardinalité…).
     * { type, name, description?, color?, dash?, fields?, label? (gabarit « {{event}} » ou fonction), from?, to?
     *   (types ou genres de pierres permis à chaque bout ; '*' ou absent : tous), default?: true, validate?(wire, ws) }
     */
    defineEdge(spec) {
      if (!spec || !spec.type) throw new D.DominoError('edge.type', 'Un genre de lien a un « type ».');
      const e = {
        type: spec.type, name: spec.name || spec.type, description: spec.description || '', color: spec.color || null, dash: !!spec.dash,
        fields: normFields(spec.type, spec.fields), label: spec.label || null,
        from: spec.from ? [].concat(spec.from) : null, to: spec.to ? [].concat(spec.to) : null,
        default: !!spec.default, validate: typeof spec.validate === 'function' ? spec.validate : null,
      };
      this.edges.set(e.type, e);
      return e;
    }
    edge(type) { return (type && this.edges.get(type)) || null; }
    /** Le genre de lien que prend un fil de a vers b sans genre demandé : le premier « default », sinon le premier permis. */
    edgeFor(a, b) {
      const ok = (e) => D.edgeAllows(e, a, b);
      const list = [...this.edges.values()];
      return list.find((e) => e.default && ok(e)) || list.find(ok) || null;
    }
    semantics(left, right, def) {
      const base = semantics(left, right, def);
      if (!this.custom) return base;
      try { return { ...base, ...(this.custom(left, right, def, base) || {}) }; } catch (_) { return base; }
    }

    /**
     * Déclare un type de pierre. Rend la définition normalisée.
     * Les erreurs disent quoi corriger : c'est le premier contact du développeur avec le framework.
     */
    define(spec) {
      const def = this.build(spec);
      this.defs.set(def.type, def);
      return def;
    }
    /** Normalise une définition sans l'enregistrer (définitions calculées : instances, appels). */
    build(spec) {
      if (!spec || typeof spec !== 'object') throw new D.DominoError('def.shape', 'Une définition de pierre doit être un objet.');
      if (!spec.type) throw new D.DominoError('def.type', 'Une définition de pierre doit avoir un « type ».', { spec });
      // Les traits d'abord : la définition se compose de comportements de confiance, puis l'emporte sur eux.
      if (D.Traits && Array.isArray(spec.traits) && spec.traits.length) spec = D.Traits.apply(spec);
      const json = {}, hooks = {};
      for (const [k, v] of Object.entries(spec)) (typeof v === 'function' ? hooks : json)[k] = v;
      for (const k of Object.keys(json)) if (!KNOWN.has(k)) this.warnings.push(`« ${spec.type} » : clé inconnue « ${k} » (ignorée).`);
      for (const [k, src] of Object.entries(json.code || {})) {
        if (!HOOKS[k]) throw new D.DominoError('def.hook', `« ${spec.type} » : callback inconnu « ${k} » dans « code ».`);
        if (!hooks[k] && typeof src === 'string' && src.trim()) hooks[k] = compileHook(spec.type, k, src);
      }
      // Le comportement déclaré (expressions, gabarits) : les callbacks qui manquent encore.
      if (json.behaviour && D.Behaviour) { const bh = D.Behaviour.compile(json.behaviour, spec.type); for (const [k, f] of Object.entries(bh)) if (!hooks[k]) hooks[k] = f; }
      for (const k of Object.keys(hooks)) if (!HOOKS[k]) throw new D.DominoError('def.hook', `« ${spec.type} » : callback inconnu « ${k} ». Callbacks possibles : ${Object.keys(HOOKS).join(', ')}.`);
      const left = normPips(json.left, 'left'), right = normPips(json.right, 'right');
      for (const p of [...left, ...right]) if (!this.types.has(p.type)) throw new D.DominoError('def.pipType', `« ${spec.type} » : le point « ${p.name} » a le type « ${p.type} », qui n’est pas déclaré.`, { type: spec.type });
      const fields = normFields(spec.type, json.fields);
      if (json.where) for (const w of [].concat(json.where)) if (!WHERE.includes(w)) throw new D.DominoError('def.where', `« ${spec.type} » : « where » vaut ${WHERE.join(', ')}.`);
      const chain = json.chain !== false;
      // Une pierre libre (chain: false) garde ses adjacentes hautes (elles alimentent ses entrées), pas de basses.
      // Une famille demandée explicitement (top: {} ou true) est ouverte même si les faces sont calculées (callback pips).
      const side = (v, open) => (v === false || (!open && !v) ? { open: false, max: 0, accepts: null } : { open: true, max: (v && v.max) || Infinity, accepts: (v && v.accepts) || null });
      const def = {
        type: json.type,
        name: json.name || json.type,
        category: json.category || 'Pierres',
        description: json.description || '',
        help: json.help || '',
        kind: json.kind || null,
        meaning: json.meaning || null,
        left, right,
        chain,
        wires: json.wires !== false,
        where: json.where ? [].concat(json.where) : ['main', 'body', 'component'],
        async: !!json.async,
        top: side(json.top, left.length > 0),
        bottom: chain ? side(json.bottom, right.length > 0) : { open: false, max: 0, accepts: null },
        fields,
        // L'intérieur : n'importe quelle pierre peut contenir une partie (algorithme, scénario, module…), ouverte dans un onglet.
        // `container` est l'ancien nom de `inside`.
        container: inside(json.inside !== undefined ? json.inside : json.container),
        represents: json.represents || null,
        constraints: constraints(json.constraints),
        version: json.version || null,
        deprecated: json.deprecated || null,
        examples: json.examples || null,
        faces: json.faces || null,
        tint: json.tint || null,
        identity: json.identity || null,
        tags: json.tags || [],
        hidden: !!json.hidden,
        // Mode d'affichage propre à la pierre (voir domino.display.js) : il change son dessin, jamais son échelle.
        display: json.display || null,
        /** Traits composés (identifiants), rôles sémantiques (lus par les moteurs : état initial, porte…), notations, comportement déclaré. */
        traits: Array.isArray(json.traits) ? json.traits : null,
        roles: json.roles || {},
        notation: json.notation || null,
        behaviour: json.behaviour || null,
        code: json.code || null,
        hooks,
      };
      def.inside = def.container;
      for (const [k, v] of Object.entries(json.extra || {})) def[k] = v;
      def.semantics = this.semantics(def.left.length, def.right.length, def);
      return def;
    }
    defineAll(list) { (list || []).forEach((s) => this.define(s)); return this; }
    _resolve(type) { for (const r of this.resolvers) { const d = r.get(type); if (d) return d; } return null; }
    has(type) { return this.defs.has(type) || !!this._resolve(type); }
    get(type) { return this.defs.get(type) || this._resolve(type) || this.defs.get('domino.unknown'); }
    list({ hidden = false, dynamic = true } = {}) {
      const all = [...this.defs.values(), ...(dynamic ? this.resolvers.flatMap((r) => r.list()) : [])];
      return all.filter((d) => hidden || !d.hidden);
    }
    categories(filter = () => true) {
      const m = new Map();
      for (const d of this.list().filter(filter)) { if (!m.has(d.category)) m.set(d.category, []); m.get(d.category).push(d); }
      return m;
    }

    /** La définition JSON (callbacks en texte s'ils ont été écrits en texte), telle qu'un générateur ou un autre outil la lirait. */
    toJSON(type) {
      const one = (d) => D.compact({
        type: d.type, name: d.name, category: d.category, description: d.description, help: d.help, kind: d.kind || undefined, meaning: d.meaning || undefined,
        left: d.left, right: d.right,
        chain: d.chain ? undefined : false, wires: d.wires ? undefined : false, async: d.async || undefined,
        where: d.where.join() === 'main,body,component' ? undefined : d.where,
        top: d.top.open ? (d.top.max !== Infinity ? { max: d.top.max } : undefined) : false,
        bottom: d.bottom.open ? (d.bottom.max !== Infinity ? { max: d.bottom.max } : undefined) : false,
        represents: d.represents || undefined, version: d.version || undefined, deprecated: d.deprecated || undefined,
        fields: Object.fromEntries(Object.entries(d.fields).map(([k, f]) => [k, D.compact({ ...f, validate: undefined, options: typeof f.options === 'function' ? 'dynamiques' : f.options })])),
        inside: d.inside || undefined, faces: d.faces, tint: d.tint, identity: d.identity, tags: d.tags, display: d.display || undefined,
        traits: d.traits || undefined, roles: d.roles && Object.keys(d.roles).length ? d.roles : undefined, notation: d.notation && Object.keys(d.notation).length ? d.notation : undefined, behaviour: d.behaviour || undefined,
        constraints: JSON.stringify(d.constraints) === JSON.stringify(constraints({})) ? undefined : D.compact({ ...d.constraints }),
        code: d.code || undefined,
        callbacks: Object.keys(d.hooks),
      });
      return type ? one(this.get(type)) : this.list({ hidden: true, dynamic: false }).filter((d) => !d.type.startsWith('domino.unknown')).map(one);
    }
  }

  D.semantics = semantics;
  D.normPips = normPips;
  D.compileHook = compileHook;
  D.Registry = Registry;
  D.HOOKS = HOOKS;
  D.FIELD_KINDS = FIELD_KINDS;
  D.WHERE = WHERE;
  D.REPRESENTS = REPRESENTS;
  D.REF_TO = REF_TO;

  /**
   * Pierres propres au framework : la liaison au contexte et les bornes d'une sous-partie.
   * Elles sont disponibles dans tous les éditeurs, quel que soit le domaine.
   */
  D.builtins = function (registry) {
    registry.define({
      type: 'ctx.get', name: 'Lire le contexte', category: 'Contexte',
      description: 'Fournit une valeur du contexte. En adjacente haute, elle lie une entrée à une clé du contexte.',
      right: [{ name: 'valeur', type: 'any' }],
      fields: { path: { kind: 'text', label: 'Clé', default: 'env.KEY', bindable: false } },
      identity: '#B8893B',
      title(api) { return api.field('path'); },
      run(rc) { return [rc.ctx.get(rc.domino.fields.path)]; },
      validate(api) { return api.context.has(api.domino.fields.path) ? [] : [{ level: 'warn', code: 'binding', message: t('diag.binding', { path: api.domino.fields.path }) }]; },
    });
    registry.define({
      type: 'ctx.set', name: 'Écrire dans le contexte', category: 'Contexte',
      description: 'Écrit la valeur reçue dans le contexte. En adjacente basse, elle publie une sortie.',
      left: [{ name: 'valeur', type: 'any' }],
      fields: { path: { kind: 'text', label: 'Clé', default: 'state.value', bindable: false } },
      title(api) { return `→ ${api.field('path')}`; },
      run(rc) { rc.ctx.set(rc.domino.fields.path, rc.inputs[0]); return []; },
    });
    registry.define({
      type: 'domino.entry', name: 'Entrée de la partie', category: 'Partie', where: ['component'],
      description: 'Dans une sous-partie : reçoit ce que la pierre conteneur reçoit.',
      right: [{ name: 'entrée', type: 'any' }],
      fields: { index: { kind: 'number', label: 'Entrée n°', default: 1, bindable: false } },
      run(rc) { return [rc.partieInputs[(rc.domino.fields.index || 1) - 1]]; },
    });
    registry.define({
      type: 'domino.exit', name: 'Résultat de la partie', category: 'Partie', where: ['component'],
      description: 'Dans une sous-partie : rend une valeur à la pierre conteneur.',
      left: [{ name: 'résultat', type: 'any' }],
      fields: { name: { kind: 'text', label: 'Nom', default: 'résultat', bindable: false } },
      title(api) { return `Résultat « ${api.field('name')} »`; },
      run(rc) { rc.results[rc.domino.fields.name] = rc.inputs[0]; return []; },
    });
    // Renvoi : une pierre qui en désigne une autre (pierre, partie, déclaration, variable), par son identifiant.
    // Double-clic : aller à la cible. Dans une chaîne, elle laisse passer la valeur.
    registry.define({
      type: 'domino.ref', name: 'Renvoi', category: 'Liens', represents: 'renvoi', kind: 'renvoi',
      description: 'Désigne un autre élément du projet (une pierre, une partie, une déclaration, une variable). Le lien tient par l’identifiant : renommer ou déplacer la cible ne le casse pas. Double-clic : y aller.',
      left: [{ name: 'entrée', type: 'any', required: false }], right: [{ name: 'suite', type: 'any' }],
      fields: { target: { kind: 'ref', label: 'Cible', to: ['domino', 'partie', 'declaration', 'variable'], required: true }, why: { kind: 'text', label: 'Pourquoi', default: '', bindable: false } },
      title(api) { const r = api.ref('target'); return r && r.kind !== 'missing' ? `↪ ${r.title}` : '↪ (cible ?)'; },
      run(rc) { return [rc.inputs[0] === undefined ? true : rc.inputs[0]]; },
    });
    // Projet : un projet entier (d'un langage enregistré, même un autre) tient dans une pierre.
    // Il s'ouvre dans un onglet avec l'éditeur de son langage ; l'effet domino l'exécute, entrée et résultat par le contexte.
    registry.define({
      type: 'domino.project', name: 'Projet', category: 'Liens', represents: 'projet', kind: 'projet',
      description: 'Un projet entier dans une pierre, d’un langage enregistré (celui-ci ou un autre). Double-clic : l’ouvrir dans un onglet. L’entrée est écrite dans son contexte, le résultat y est lu.',
      meaning: { left: 'ce que reçoit le projet', right: 'ce qu’il rend' },
      left: [{ name: 'entrée', type: 'any', required: false }], right: [{ name: 'résultat', type: 'any' }],
      fields: {
        language: { kind: 'select', label: 'Langage', options: () => Object.keys(D.packs || {}), default: '', bindable: false, required: true },
        project: { kind: 'json', label: 'Projet', default: null, bindable: false, hidden: true },
        input: { kind: 'text', label: 'Entrée → contexte', default: 'entrée', bindable: false },
        output: { kind: 'text', label: 'Résultat ← contexte', default: 'résultat', bindable: false },
      },
      title(api) { const p = api.raw('project'); const L = (D.packs || {})[api.raw('language')]; return `${L ? L.name : 'Projet'} · ${(p && p.name) || 'sans nom'}`; },
      // Teinté de la couleur de son langage.
      faces(api) { const L = (D.packs || {})[api.raw('language')], Kit = root.DominoKit; return L && Kit ? { left: Kit.mix(L.color, '#FFFFFF', 0.86), right: Kit.mix(L.color, '#FFFFFF', 0.72) } : null; },
      validate(api) {
        const out = [];
        if (!(D.packs || {})[api.raw('language')]) out.push({ level: 'error', code: 'project.language', message: `Langage « ${api.raw('language') || '?'} » non enregistré.` });
        else if (api.raw('project')) { const errs = D.Serializer.check(api.raw('project')); if (errs.length) out.push({ level: 'error', code: 'project.json', message: `Projet embarqué : ${errs[0]}` }); }
        return out;
      },
      async run(rc) {
        const L = (D.packs || {})[rc.fields.language];
        if (!L) throw new Error(`langage « ${rc.fields.language} » non enregistré.`);
        const inner = D.language(L).instantiate(rc.fields.project || undefined);
        if (rc.inputs[0] !== undefined && rc.fields.input) inner.ws.context.set(rc.fields.input, rc.inputs[0]);
        const r = await inner.runtime.run({ silent: true });
        if (!r.ok) throw new Error(`projet « ${inner.ws.name} » : ${r.error}`);
        rc.log('info', `projet « ${inner.ws.name} » (${L.name}) : ${r.trace.length} étapes en ${r.ms} ms`);
        return [rc.fields.output ? r.context.get(rc.fields.output) : r.trace.length];
      },
    });
    // Saut : l'exécution continue à une autre pierre de la même partie (une étape précédente : une boucle ;
    // une étape plus loin : sauter des étapes ; la suite commune de plusieurs branches : les rejoindre).
    // Le nombre de passages est borné : au-delà, la valeur sort par « épuisé » (la chaîne continue là).
    registry.define({
      type: 'domino.goto', name: 'Aller à', category: 'Liens', represents: 'saut', kind: 'saut',
      description: 'Saut : l’exécution continue à la pierre visée, dans la même partie (une étape précédente pour revenir, une étape plus loin pour sauter, la suite commune pour rejoindre des branches). Au-delà du nombre de passages permis, la valeur sort par « épuisé ».',
      meaning: { left: 'la valeur qui saute', right: 'la même valeur, quand les passages sont épuisés' },
      left: [{ name: 'valeur', type: 'any', required: false }], right: [{ name: 'épuisé', type: 'any' }],
      top: false, bottom: false,
      fields: {
        target: { kind: 'ref', label: 'Aller à', to: 'domino', jump: true, required: true, help: 'La pierre où l’exécution continue (⌖ : la choisir sur la table).' },
        max: { kind: 'number', label: 'Passages au plus', default: 3, min: 1, max: 1000, bindable: false, help: 'Garde-fou contre les boucles sans fin.' },
        why: { kind: 'text', label: 'Pourquoi', default: '', bindable: false },
      },
      faces: { left: '#F6E3BF', right: '#EFD3A0' },
      title(api) { const r = api.ref('target'); return r && r.kind !== 'missing' ? `↪ ${r.title}` : '↪ (cible ?)'; },
      validate(api) {
        const r = api.ref('target'), ws = api.workspace, me = api.domino;
        if (!r || r.kind === 'missing' || !r.node) return [];
        if (r.node.id === me.id) return [{ level: 'error', code: 'jump.self', message: 'Un saut ne vise pas sa propre pierre.' }];
        if (r.node.partie !== me.partie) return [{ level: 'error', code: 'jump.partie', message: `La cible « ${r.title} » est dans une autre partie : un saut reste dans sa partie.` }];
        if (!ws.pipsOf(r.node).left.length) return [{ level: 'warn', code: 'jump.noInput', message: `« ${r.title} » ne reçoit rien : elle tombera sans la valeur du saut.` }];
        return [];
      },
      run(rc) {
        const v = rc.inputs[0] === undefined ? true : rc.inputs[0];
        return rc.jump(rc.fields.target, v, { max: rc.fields.max }) ? [undefined] : [v];
      },
    });
    registry.define({ type: 'domino.unknown', name: 'Pierre inconnue', category: 'Système', hidden: true, left: 1, right: 1, tint: '#F3D9D9' });
  };
})(typeof globalThis !== 'undefined' ? globalThis : window);
