/*!
 * Zeugma · traits et comportements déclarés
 *
 * Un langage peut n'être que des DONNÉES : ses pierres composent des traits (des comportements de confiance,
 * livrés avec le moteur) et déclarent le reste en expressions (domino.expr.js). Aucun callback JavaScript,
 * donc aucune confiance à demander à l'import, et tout se vérifie sous Node.
 *
 *   { type: 'sm.state', traits: ['nommé', { id: 'état', final: true }],
 *     behaviour: {
 *       title: '{{name}} ({{nombre(cases)}})',                         // gabarit : {{ expression }}
 *       validate: [{ if: 'vide(name)', level: 'warn', message: 'Sans nom.' }],
 *       faces: [{ if: 'final', left: '#E3F1E7', right: '#C9E6D2' }],
 *       pips: { right: [{ each: 'cases', name: '{{row.label}}', type: 'parcours' }, { name: 'sinon', type: 'parcours' }] },
 *       canConnect: [{ on: 'next', if: 'child.kind == "fin" et parent.kind == "début"', message: 'Pas de fin juste après le début.' }],
 *       run: { set: [{ path: 'contexte.n', value: 'ctx.n + 1' }], log: '"passage " + name', out: ['value'], jump: { field: 'cible', max: 3 } },
 *     } }
 *
 *   Domino.Traits.register('monTrait', (params) => ({ fields: { … }, behaviour: { … } }));
 *
 * Fusion (trait par trait, puis la définition) : les champs et les rôles se fusionnent (la définition
 * l'emporte), les faces de la définition remplacent celles des traits, les vérifications s'additionnent,
 * le premier refus de connexion l'emporte, les étiquettes s'unissent.
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
  const E = (api) => (api && api.language && api.language.exprDialect) || D.Expr;

  // ===========================================================================
  // Expressions et gabarits
  // ===========================================================================
  const parsed = new Map();
  /** Une expression écrite en texte (mise en cache) ou déjà en JSON. */
  function exprOf(v, X = D.Expr) {
    if (typeof v !== 'string') return v;
    const key = v;
    if (!parsed.has(key)) { const r = X.read(v); parsed.set(key, r.errors.length ? { bad: r.errors[0] } : { e: r.expr }); }
    const p = parsed.get(key);
    if (p.bad) throw new D.DominoError('expr.syntax', `« ${v} » : ${p.bad}`);
    return p.e;
  }
  const show = (v) => (v == null ? '' : Array.isArray(v) ? v.map(show).join(', ') : isObj(v) ? JSON.stringify(v) : String(v));
  /** « {{ expression }} » remplacé par sa valeur. */
  function template(str, scope, X = D.Expr) {
    return String(str == null ? '' : str).replace(/\{\{\s*([^}]+?)\s*\}\}/g, (_, src) => { try { return show(X.evaluate(exprOf(src, X), scope)); } catch (err) { return `⚠${src}`; } });
  }
  /** Ce qu'une expression voit d'une pierre : ses champs (à la racine et sous fields), son type, son genre… */
  function summaryOf(api) {
    if (!api) return {};
    const n = api.domino, ws = api.workspace;
    const f = ws.context.resolve(n.fields || {});
    const s = { ...f, fields: f, id: n.id, type: n.type, kind: n.def.kind, represents: n.def.represents, category: n.def.category, name: f.name !== undefined ? f.name : n.def.name };
    Object.defineProperty(s, 'title', { get: () => ws.titleOf(n), enumerable: false });
    Object.defineProperty(s, 'ctx', { get: () => (ws.context.merged ? ws.context.merged() : ws.context.snapshot()), enumerable: false });
    Object.defineProperty(s, 'roles', { get: () => n.def.roles || {}, enumerable: false });
    return s;
  }

  // ===========================================================================
  // Comportements déclarés → callbacks
  // ===========================================================================
  /**
   * Compile la clé `behaviour` d'une définition en callbacks (title, validate, faces, pips, canConnect, run).
   * Les erreurs de syntaxe des expressions sont levées à la définition, pas à l'usage.
   */
  function compile(b, owner = '?') {
    if (!isObj(b)) return {};
    const hooks = {};
    const check = (src, where) => { if (typeof src === 'string') { const r = D.Expr.read(src); if (r.errors.length) throw new D.DominoError('behaviour.expr', `« ${owner} », ${where} « ${src} » : ${r.errors[0]}`); } };
    const tplCheck = (str, where) => { for (const m of String(str || '').matchAll(/\{\{\s*([^}]+?)\s*\}\}/g)) check(m[1], where); };
    if (b.title != null) {
      tplCheck(b.title, 'title');
      hooks.title = (api) => template(b.title, summaryOf(api), E(api));
    }
    if (Array.isArray(b.validate)) {
      b.validate.forEach((v, i) => { check(v.if, `validate[${i}]`); tplCheck(v.message, `validate[${i}].message`); });
      hooks.validate = (api) => {
        const s = summaryOf(api), X = E(api), out = [];
        for (const v of b.validate) if (X.test(exprOf(v.if, X), s)) out.push(D.compact({ level: v.level || 'warn', code: v.code || 'behaviour', message: template(v.message || 'Vérification non satisfaite.', s, X), field: v.field }));
        return out;
      };
    }
    if (Array.isArray(b.faces)) {
      b.faces.forEach((v, i) => check(v.if, `faces[${i}]`));
      hooks.faces = (api) => { const s = summaryOf(api), X = E(api); const f = b.faces.find((v) => v.if == null || X.test(exprOf(v.if, X), s)); return f ? { left: f.left || null, right: f.right || null } : null; };
    }
    if (isObj(b.pips)) {
      // Une face : des points fixes, et des points « each » — un par ligne d'un champ tableau (ou d'une liste calculée).
      const expand = (list, s, X) => {
        if (!Array.isArray(list)) return undefined;
        const out = [];
        for (const p of list) {
          if (p && p.each) {
            const rows = typeof p.each === 'string' && /^[\p{L}_][\p{L}\p{N}_]*$/u.test(p.each) ? s[p.each] : X.evaluate(exprOf(p.each, X), s);
            (Array.isArray(rows) ? rows : []).forEach((row, index) => { const rs = { ...s, row, index }; out.push(D.compact({ name: template(p.name || '{{index + 1}}', rs, X), type: p.type || 'any', required: p.required === undefined ? false : p.required, color: p.color, multiple: p.multiple })); });
          } else if (p) out.push({ ...p, name: p.name && p.name.includes('{{') ? template(p.name, s, X) : p.name });
        }
        return out;
      };
      hooks.pips = (api) => { const s = summaryOf(api), X = E(api); return D.compact({ left: expand(b.pips.left, s, X), right: expand(b.pips.right, s, X) }); };
    }
    if (Array.isArray(b.canConnect)) {
      b.canConnect.forEach((v, i) => check(v.if, `canConnect[${i}]`));
      hooks.canConnect = (api, q) => {
        const me = summaryOf(api), other = summaryOf(q.other);
        const scope = { self: me, other, parent: q.role === 'parent' ? me : other, child: q.role === 'child' ? me : other, via: q.via, pip: q.pip, role: q.role };
        const X = E(api);
        for (const v of b.canConnect) {
          if (v.on && v.on !== '*' && ![].concat(v.on).includes(q.via)) continue;
          if (X.test(exprOf(v.if, X), scope)) return template(v.message || 'Refusé.', scope, X);
        }
        return true;
      };
    }
    if (isObj(b.run)) hooks.run = compileRun(b.run, owner, check);
    return hooks;
  }

  /**
   * L'exécution déclarée :
   *   set   [{ path, value }]   « contexte.x » (ou « ctx.x ») : dans le contexte ; « value.x » : dans la valeur qui passe
   *   log   expression           une ligne dans la console
   *   wait  expression (ms)      une pause (pierre asynchrone)
   *   jump  { field | to, max }  un saut (champ renvoi, ou expression qui rend un identifiant)
   *   out   [expr | { value, if }]  une valeur par sortie ; avec first: true, seule la première sortie retenue tombe
   * Sans out, la pierre laisse passer ce qu'elle reçoit. Portée : value, in, inputs, fields (et les champs à la racine), ctx, args.
   */
  function compileRun(r, owner, check) {
    (r.set || []).forEach((s, i) => check(s.value, `run.set[${i}]`));
    if (r.log) check(r.log, 'run.log');
    if (r.jump && typeof r.jump.max === 'string') check(r.jump.max, 'run.jump.max');
    (Array.isArray(r.out) ? r.out : []).forEach((o, i) => { if (isObj(o)) { check(o.value, `run.out[${i}]`); check(o.if, `run.out[${i}].if`); } else check(o, `run.out[${i}]`); });
    return async (rc) => {
      const ws = rc.api.workspace, X = (ws.language && ws.language.exprDialect) || D.Expr;
      // Un champ « expr » est une formule : dans les expressions du comportement, son nom donne sa valeur calculée.
      const defs = (rc.node && rc.node.def && rc.node.def.fields) || {};
      const scope = () => {
        const s = { ...rc.fields, fields: rc.fields, in: rc.in, inputs: rc.inputs };
        for (const [k, f] of Object.entries(defs)) {
          const src = rc.fields[k];
          if (f.kind !== 'expr' || src == null || src === '') continue;
          try { s[k] = rc.expr(exprOf(src, X), { ...rc.fields, value }); } catch (err) { throw new D.DominoError('behaviour.expr', `Champ « ${f.label || k} » : ${err.message}`); }
        }
        return s;
      };
      let value = rc.inputs[0];
      const ev = (e) => rc.expr(exprOf(e, X), { ...scope(), value });
      for (const s of r.set || []) {
        const v = ev(s.value), path = String(s.path || '');
        if (/^(contexte|ctx)\./.test(path)) rc.ctx.set(path.replace(/^(contexte|ctx)\./, ''), v);
        else if (path.startsWith('value.')) {
          value = isObj(value) ? D.clone(value) : {};
          const parts = path.slice(6).split('.');
          let cur = value;
          parts.slice(0, -1).forEach((p) => { cur = cur[p] = isObj(cur[p]) ? cur[p] : {}; });
          cur[parts[parts.length - 1]] = v;
        } else rc.ctx.set(path, v);
      }
      if (r.log) rc.log('info', show(ev(r.log)));
      if (r.wait) await rc.sleep(Number(ev(r.wait)) || 0);
      if (r.jump) {
        const target = r.jump.field ? rc.fields[r.jump.field] : ev(r.jump.to);
        const max = typeof r.jump.max === 'string' ? Number(ev(r.jump.max)) : r.jump.max;
        if (target && rc.jump(target, value, { max: max || 1 }) && !r.out) return [];
      }
      const right = ws.pipsOf(rc.node).right;
      if (!r.out) return right.map((_, i) => (rc.inputs[i] !== undefined ? rc.inputs[i] : value));
      const outs = [];
      let taken = false;
      right.forEach((_, i) => {
        const o = (Array.isArray(r.out) ? r.out[i] : i === 0 ? r.out : undefined);
        if (o === undefined) { outs.push(undefined); return; }
        if (isObj(o) && o.value === undefined && o.if === undefined) { outs.push(o); return; }
        const ok = !isObj(o) || o.if == null || X.truthy(ev(o.if));
        if (!ok || (r.first && taken)) { outs.push(undefined); return; }
        taken = true;
        outs.push(ev(isObj(o) ? (o.value !== undefined ? o.value : 'value') : o));
      });
      return outs;
    };
  }

  // ===========================================================================
  // Traits
  // ===========================================================================
  const traits = new Map();
  const deep = (a, b) => { if (!isObj(a) || !isObj(b)) return b === undefined ? a : b; const o = { ...a }; for (const [k, v] of Object.entries(b)) o[k] = deep(a[k], v); return o; };
  const HOOK_KEYS = new Set(['validate', 'canConnect', 'onCreate', 'onDispose', 'onChange', 'onConnect', 'onDisconnect', 'onAttach', 'onDetach', 'onWire', 'onUnwire', 'onSelect', 'init']);
  /** Deux callbacks du même nom : validate s'additionne, canConnect garde le premier refus, les événements s'appellent tous. */
  function joinHook(k, f, g) {
    if (!f) return g;
    if (!g) return f;
    if (k === 'validate') return (...a) => [...(f(...a) || []), ...(g(...a) || [])];
    if (k === 'canConnect') return (...a) => { const r = f(...a); if (r !== true && r != null) return r; return g(...a); };
    return (...a) => { f(...a); return g(...a); };
  }
  function merge(base, over) {
    const out = { ...base, ...over };
    out.fields = { ...(base.fields || {}), ...(over.fields || {}) };
    if (!over.left && base.left) out.left = base.left;
    if (!over.right && base.right) out.right = base.right;
    out.roles = deep(base.roles || {}, over.roles || {});
    out.notation = deep(base.notation || {}, over.notation || {});
    if (base.tags || over.tags) out.tags = [...new Set([...(base.tags || []), ...(over.tags || [])])];
    if (base.behaviour || over.behaviour) {
      const a = base.behaviour || {}, b = over.behaviour || {};
      out.behaviour = { ...a, ...b };
      for (const k of ['validate', 'canConnect', 'faces']) if (a[k] || b[k]) out.behaviour[k] = k === 'faces' ? [...(b[k] || []), ...(a[k] || [])] : [...(a[k] || []), ...(b[k] || [])];
    }
    for (const k of HOOK_KEYS) if (typeof base[k] === 'function' || typeof over[k] === 'function') out[k] = joinHook(k, base[k], over[k]);
    return out;
  }
  const Traits = {
    /** Un trait : un objet (fragment de définition) ou une fonction (paramètres) → fragment. */
    register(id, spec, { description = '' } = {}) { traits.set(id, { id, spec, description }); return () => traits.delete(id); },
    get(id) { return traits.get(id) || null; },
    list() { return [...traits.values()].map((t) => ({ id: t.id, description: t.description, parametric: typeof t.spec === 'function' })); },
    /** Une définition avec ses traits appliqués (la définition l'emporte). `traits` y reste (identifiants), pour l'export. */
    apply(spec) {
      if (!spec || !Array.isArray(spec.traits) || !spec.traits.length) return spec;
      let acc = {};
      for (const t of spec.traits) {
        const { id, ...params } = typeof t === 'string' ? { id: t } : t;
        const tr = traits.get(id);
        if (!tr) throw new D.DominoError('trait.unknown', `« ${spec.type} » : trait inconnu « ${id} » (connus : ${[...traits.keys()].join(', ')}).`);
        acc = merge(acc, typeof tr.spec === 'function' ? tr.spec(params) || {} : D.clone(tr.spec));
      }
      const out = merge(acc, spec);
      out.traits = spec.traits;
      return out;
    },
  };

  // ---------------------------------------------------------------------------
  // Les traits livrés : de quoi bâtir sans code des machines à états, des processus, des arbres, des schémas.
  // ---------------------------------------------------------------------------
  const T = (type) => type || 'any';
  Traits.register('nommé', { fields: { name: { kind: 'text', label: 'Nom', default: '', required: true } }, behaviour: { title: '{{name}}' } }, { description: 'Un nom requis, affiché en titre.' });
  Traits.register('décrit', { fields: { description: { kind: 'textarea', label: 'Description', default: '' } } }, { description: 'Une description libre.' });
  Traits.register('libre', { chain: false }, { description: 'Pierre libre : reliée par des fils, pas collée en chaîne.' });
  Traits.register('conteneur', (o = {}) => ({ inside: { kind: o.kind || 'Contenu', partie: 'component' } }), { description: 'Un intérieur qui s’ouvre dans un onglet.' });
  Traits.register('état', (o = {}) => ({
    chain: false, roles: { state: { initial: !!o.initial, final: !!o.final } },
    left: o.initial ? [] : [{ name: 'arrivée', type: T(o.type), multiple: true, required: false }],
    right: o.final ? [] : [{ name: 'départ', type: T(o.type), required: false }],
    fields: o.initial || o.final ? {} : { entry: { kind: 'text', label: 'En entrant', default: '', group: 'Actions' }, exit: { kind: 'text', label: 'En sortant', default: '', group: 'Actions' } },
    notation: { diagram: { shape: o.final ? 'circle' : o.initial ? 'circle' : 'roundrect' } },
  }), { description: 'Un état (initial, final ou ordinaire) d’une machine à états : arrivées multiples, départs par des fils.' });
  Traits.register('début', (o = {}) => ({ chain: false, roles: { flow: { start: true } }, right: [{ name: 'suite', type: T(o.type), required: false }], constraints: { max: 1 }, notation: { diagram: { shape: 'circle' } } }), { description: 'Le départ d’un processus (un seul).' });
  Traits.register('fin', (o = {}) => ({ chain: false, roles: { flow: { end: true } }, left: [{ name: 'arrivée', type: T(o.type), multiple: true, required: false }], right: [], notation: { diagram: { shape: 'circle' } } }), { description: 'Une fin de processus.' });
  Traits.register('tâche', (o = {}) => ({ chain: false, roles: { flow: { task: true } }, left: [{ name: 'arrivée', type: T(o.type), multiple: true, required: false }], right: [{ name: 'suite', type: T(o.type), required: false }], notation: { diagram: { shape: 'roundrect' } } }), { description: 'Une tâche d’un processus.' });
  Traits.register('porte', (o = {}) => ({ chain: false, roles: { flow: { gateway: o.mode || 'xor' } }, left: [{ name: 'arrivée', type: T(o.type), multiple: true, required: false }], right: [{ name: 'sorties', type: T(o.type), required: false }], notation: { diagram: { shape: 'diamond' } } }), { description: 'Une porte : xor (une branche selon les conditions), and (toutes ; en jointure, attend toutes les arrivées).' });
  Traits.register('question', (o = {}) => ({
    roles: { decision: { question: true } },
    fields: { question: { kind: 'text', label: 'Question', default: 'Question ?' }, options: { kind: 'table', label: 'Réponses', default: [{ label: 'Oui', when: null }, { label: 'Non', when: null }], columns: { label: { kind: 'text', label: 'Réponse', required: true }, when: { kind: 'expr', label: 'Si (condition)' } } } },
    left: [{ name: 'arrivée', type: T(o.type), required: false }],
    behaviour: { title: '{{question}}', pips: { right: [{ each: 'options', name: '{{row.label}}', type: T(o.type) }] } },
    notation: { diagram: { shape: 'diamond' } },
  }), { description: 'Un nœud de décision : une sortie par réponse (un tableau), chacune avec sa condition.' });
  Traits.register('feuille', (o = {}) => ({ roles: { decision: { leaf: true } }, left: [{ name: 'arrivée', type: T(o.type), required: false }], right: [], fields: { verdict: { kind: 'text', label: 'Conclusion', default: 'Conclusion' } }, behaviour: { title: '{{verdict}}' }, notation: { diagram: { shape: 'pill' } } }), { description: 'Une conclusion d’arbre de décision.' });
  Traits.register('entité', (o = {}) => ({
    chain: false, roles: { schema: { entity: true } },
    fields: { attributes: { kind: 'table', label: 'Attributs', default: [{ name: 'id', type: 'entier', key: true }], columns: { name: { kind: 'text', label: 'Nom', required: true }, type: { kind: 'text', label: 'Type' }, key: { kind: 'toggle', label: 'Clé' } } } },
    left: [{ name: 'référencée', type: T(o.type), multiple: true, required: false }], right: [{ name: 'référence', type: T(o.type), required: false }],
    behaviour: { validate: [{ if: 'nombre(attributes) == 0', level: 'warn', message: 'Aucun attribut.' }] },
    notation: { diagram: { shape: 'table', rows: { field: 'attributes', text: '{{si(row.key, "🔑 ", "")}}{{row.name}} : {{row.type}}' } } },
  }), { description: 'Une entité d’un schéma de données : ses attributs en tableau, ses relations par des fils.' });
  Traits.register('note', { chain: false, wires: false, left: [], right: [], fields: { text: { kind: 'textarea', label: 'Texte', default: 'Note' } }, behaviour: { title: '{{text}}' }, notation: { diagram: { shape: 'note' } } }, { description: 'Une note libre, sans connexion.' });

  D.Traits = Traits;
  D.Behaviour = { compile, template, summaryOf, exprOf };
})(typeof globalThis !== 'undefined' ? globalThis : window);
