      not: { args: [1, 1], prefix: '!', word: 'non', prec: 3, doc: 'L’inverse.', eval: ([a]) => !truthy(a) },
      eq: { args: [2, 2], infix: '==', prec: 4, doc: 'Égal (nombres et textes ; listes élément par élément).', eval: ([a, b]) => same(a, b) },
      ne: { args: [2, 2], infix: '!=', prec: 4, doc: 'Différent.', eval: ([a, b]) => !same(a, b) },
      like: { args: [2, 2], infix: '~=', prec: 4, doc: 'Égal sans tenir compte des majuscules, des accents ni des espaces autour.', eval: ([a, b]) => norm(a) === norm(b) },
      gt: { args: [2, 2], infix: '>', prec: 4, doc: 'Plus grand.', eval: ([a, b]) => num(a) > num(b) },
      gte: { args: [2, 2], infix: '>=', prec: 4, doc: 'Plus grand ou égal.', eval: ([a, b]) => num(a) >= num(b) },
      lt: { args: [2, 2], infix: '<', prec: 4, doc: 'Plus petit.', eval: ([a, b]) => num(a) < num(b) },
      lte: { args: [2, 2], infix: '<=', prec: 4, doc: 'Plus petit ou égal.', eval: ([a, b]) => num(a) <= num(b) },
      in: { args: [2, 2], infix: 'dans', prec: 4, doc: 'La valeur est dans la liste (ou le texte).', eval: ([a, b]) => (typeof b === 'string' ? b.includes(String(a)) : list(b).some((x) => same(x, a))) },
      contains: { args: [2, 2], infix: 'contient', prec: 4, doc: 'La liste (ou le texte) contient la valeur.', eval: ([a, b]) => (typeof a === 'string' ? a.includes(String(b)) : list(a).some((x) => same(x, b))) },
      add: { args: [2, Infinity], infix: '+', prec: 5, doc: 'Somme (ou texte mis bout à bout).', eval: (v) => (v.some((x) => typeof num(x) !== 'number') ? v.map((x) => (x == null ? '' : String(x))).join('') : v.reduce((s, x) => s + num(x), 0)) },
