          if (i >= src.length) break;
          re.lastIndex = i;
          const m = re.exec(src);
          if (!m) throw new ExprError(`Caractère inattendu « ${src[i]} » (position ${i + 1}).`, i);
          const pos = i;
          i = re.lastIndex;
