/*!
 * Zeugma · registre des langages
 *
 * Tous les langages connus d'une application, rangés en groupes, avec leurs MODÈLES de projet (ce que
 * propose « Fichier › Nouveau ▸ ») et leurs CONTRIBUTIONS au studio (commandes, menus, raccourcis,
 * modes d'affichage, générateurs). Le registre lit et écrit Domino.packs : les langages qui s'y inscrivent
 * eux-mêmes (D.packs.kanto = …) y sont visibles sans rien changer.
 *
 *   Domino.Languages.register(spec, { group: 'Langages', short: 'Kanto' });
 *   Domino.Languages.templates('kanto');   // [{ id: 'empty', … }, { id: 'example', … }, …spec.templates]
 *   Domino.Languages.importJSON(json, { trust: true });   // un langage écrit par l'Atelier
 *
 * Modèle de projet : { id, name, description?, project: v2 | () => v2 }.
 * Contributions (clé `contributes` du langage, lue par le studio) :
 *   { commands: [{ id, title, run(ctx) }], menus: { 'menubar/run': [{ command, group }] },
 *     keybindings: [{ key, command, when }], displays: [mode], generators: [descripteur] }
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const bus = new D.Emitter();
  const info = new Map();          // id → { group, short, order, source }
  let groupOrder = [];             // [[libellé, [ids]]] fixé par la configuration

  const packs = () => (D.packs = D.packs || {});

  /** Le projet vide d'un langage : une partie principale nommée comme celle de son exemple. */
  function emptyProject(L, name = 'Sans titre') {
    // La partie principale garde le nom générique de l'exemple (« Programme », « Flux »…), pas son titre propre.
    const ex = L.project && (L.project.parties || []).find((p) => p.id === 'main');
    const main = ex && ex.name && ex.name !== L.project.name ? ex.name : name;
    return {
      format: D.FORMAT, version: D.FORMAT_VERSION,
      editor: { id: L.id, name: L.name }, name,
      context: D.clone(L.context || {}),
      parties: [{ id: 'main', kind: 'main', name: main, dominos: [] }],
    };
  }
  /** Nombre de callbacks écrits en texte dans un langage JSON (ce qu'exécuterait son import). */
  function countCode(json) {
    let n = 0;
    for (const d of json.dominos || []) if (d && d.code) n += Object.keys(d.code).length;
    for (const r of (json.rules && json.rules.list) || []) if (r && r.when) n++;
    return n;
  }

  const Languages = {
    /**
     * Inscrit un langage (spécification, JSON ou Language). Rend le Language.
     * @param {object} spec
     * @param {{ group?: string, short?: string, order?: number, source?: 'builtin'|'import'|'user' }} o
     */
    register(spec, { group, short, order, source = 'builtin' } = {}) {
      const L = D.language(spec);
      packs()[L.id] = L;
      info.set(L.id, { group: group || (info.get(L.id) || {}).group || 'Langages', short: short || (info.get(L.id) || {}).short, order: order ?? info.size, source });
      bus.emit('register', { id: L.id, language: L });
      return L;
    },
    unregister(id) { if (packs()[id]) { delete packs()[id]; info.delete(id); bus.emit('unregister', { id }); } },
    /** Le langage d'identifiant id (ou null). Un pack écrit à la main est normalisé une fois. */
    get(id) {
      const p = packs()[id];
      if (!p) return null;
      if (!(p instanceof D.Language)) packs()[id] = D.language(p);
      return packs()[id];
    },
    has(id) { return !!packs()[id]; },
    /** Range les langages en groupes : [['Langages', ['kanto', …]], ['Domaines', […]]] (la configuration le donne). */
    setGroups(groups) {
      groupOrder = (groups || []).map(([label, ids]) => [label, [...ids]]);
      groupOrder.forEach(([label, ids]) => ids.forEach((id, k) => { const i = info.get(id) || { source: 'builtin' }; info.set(id, { ...i, group: label, order: k }); }));
    },
    /** Les groupes, dans l'ordre : ceux de la configuration, puis les langages inscrits ailleurs (« Autres »). */
    groups() {
      const seen = new Set(), out = [];
      for (const [label, ids] of groupOrder) { const have = ids.filter((id) => packs()[id]); have.forEach((id) => seen.add(id)); if (have.length) out.push({ label, ids: have }); }
      const rest = Object.keys(packs()).filter((id) => !seen.has(id));
      const byGroup = new Map();
      for (const id of rest) { const g = (info.get(id) || {}).group || 'Autres'; if (!byGroup.has(g)) byGroup.set(g, []); byGroup.get(g).push(id); }
      for (const [label, ids] of byGroup) { const ex = out.find((g) => g.label === label); if (ex) ex.ids.push(...ids); else out.push({ label, ids }); }
      return out;
    },
    /** Les langages, avec ce qu'en montre un menu : [{ id, name, short, color, group, description, source }]. */
    list({ group } = {}) {
      return Languages.groups().filter((g) => !group || g.label === group).flatMap((g) => g.ids.map((id) => {
        const L = Languages.get(id), i = info.get(id) || {};
        return { id, name: L.name, short: i.short || L.name, color: L.color, group: g.label, description: L.description, source: i.source || 'builtin' };
      }));
    },
    /** Les modèles de projet d'un langage : le projet vide, son exemple, puis ceux qu'il déclare (spec.templates). */
    templates(id) {
      const L = Languages.get(id);
      if (!L) return [];
      const out = [{ id: 'empty', name: 'Projet vide', description: 'Une table vide, prête à recevoir des pierres.', project: () => emptyProject(L) }];
      if (L.project) out.push({ id: 'example', name: `Exemple : ${L.project.name || L.name}`, description: 'Le projet de démonstration du langage.', project: () => D.clone(L.project) });
      for (const t of (L.spec && L.spec.templates) || []) out.push({ ...t, id: t.id || `t${out.length}` });
      return out;
    },
    /** Le projet (v2) d'un modèle, prêt à charger. */
    projectOf(id, templateId = 'empty', { name } = {}) {
      const t = Languages.templates(id).find((x) => x.id === templateId) || Languages.templates(id)[0];
      if (!t) throw new D.DominoError('lang.unknown', `Langage inconnu : « ${id} ».`);
      if (t.id === 'empty' && name) return emptyProject(Languages.get(id), name);
      const p = typeof t.project === 'function' ? t.project() : D.clone(t.project);
      return D.Resource && D.Resource.isResource(p) ? D.Resource.unwrap(p) : p;
    },
    emptyProject: (id, name) => emptyProject(Languages.get(id), name),
    /** Les contributions d'un langage au studio (vides si aucune). */
    contributions(id) { const L = Languages.get(id); return (L && L.spec && L.spec.contributes) || {}; },
    /**
     * Importe un langage écrit en JSON (format kantoaplo.language). Ses callbacks écrits en texte seront
     * exécutés : sans { trust: true }, l'import est refusé s'il en contient (l'interface demande d'abord).
     * @returns {{ language: Language, callbacks: number }}
     */
    importJSON(json, { trust = false, group = 'Importés' } = {}) {
      if (typeof json === 'string') json = JSON.parse(json);
      if (D.Resource && D.Resource.isResource(json) && json.kind === 'Language') json = json.spec;
      if (!json || json.format !== 'kantoaplo.language') throw new D.DominoError('lang.format', 'Ce JSON n’est pas un langage (format « kantoaplo.language »).');
      const callbacks = countCode(json);
      if (callbacks && !trust) throw new D.DominoError('lang.untrusted', `Ce langage contient ${D.plural(callbacks, 'fonction écrite', 'fonctions écrites')} en texte : ne l’ouvrez que si vous lui faites confiance.`, { callbacks });
      return { language: Languages.register(json, { group, source: 'import' }), callbacks };
    },
    countCode,
    on(type, fn) { return bus.on(type, fn); },
  };

  D.Languages = Languages;
})(typeof globalThis !== 'undefined' ? globalThis : window);
