/*!
 * Zeugma · modèle
 * L'espace de travail (Workspace) tient les pierres de toutes les parties, leurs connexions,
 * les fils, l'historique (annuler / rétablir) et le bus d'événements. Il ne connaît aucun domaine.
 *
 * Deux façons de relier des pierres :
 *
 * 1. Coller (comme au jeu). Une pierre a au plus un parent ; elle s'y rattache par `via` :
 *    'next'   elle suit le parent dans la chaîne, sur la sortie n° `pip` du parent ;
 *    'top'    adjacente haute, elle alimente l'entrée n° `pip` du parent ;
 *    'bottom' adjacente basse, elle consomme la sortie n° `pip` du parent.
 *    Les pierres collées forment une forêt d'arbres : simple à valider, à sérialiser, à générer.
 *
 * 2. Relier par un fil. Un fil va d'un point de sortie à un point d'entrée, entre deux pierres
 *    quelconques de la même partie (dans une chaîne ou libres). Il prend la couleur des deux points.
 *    Un fil peut être bloquant (l'appelant attend) ou non bloquant (l'appelant continue).
 *
 * Les parties : 'main' (la principale), 'declarations' (classes, bibliothèques, fonctions),
 * 'body' (le corps d'une déclaration), 'component' (la sous-partie d'une pierre conteneur).
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const t = (k, p) => D.i18n.t(k, p);
  const VIAS = ['next', 'top', 'bottom'];
  const PARTIE_LABEL = { main: 'la partie principale', declarations: 'la table des déclarations', body: 'le corps d’une déclaration', component: 'la partie d’un composant' };

  class Node {
    constructor(ws, o) {
      Object.defineProperty(this, 'ws', { value: ws, enumerable: false });
      this.id = o.id;
      this.type = o.type;
      this.partie = o.partie || 'main';
      this.fields = o.fields || {};
      this.label = o.label || '';
      this.turn = o.turn || null;
      this.position = o.position || null;
      this.parent = null;
      this.next = [];
      this.top = [];
      this.bottom = [];
      this.meta = o.meta || {};
      /** Note de l'utilisateur (commentaire), libre. */
      this.note = o.note || '';
      /** Neutralisée : l'effet domino la traverse sans l'exécuter (ses entrées passent). */
      this.disabled = !!o.disabled;
      /** Verrouillée : l'utilisateur ne peut ni la déplacer, ni la modifier, ni la supprimer (l'API garde la main). */
      this.locked = !!o.locked;
      this.tags = o.tags ? [...o.tags] : [];
      /** Provenance : création (quand, qui, comment, d'où) et dernière modification. Sérialisée. */
      this.trace = o.trace ? D.clone(o.trace) : null;
      /** État passager, jamais sérialisé : dernier passage, valeurs, diagnostics. */
      this.state = {};
    }
    get def() { return this.ws.registry.get(this.type); }
    get pips() { return this.ws.pipsOf(this); }
    get title() { return this.ws.titleOf(this); }
    get isRoot() { return !this.parent; }
  }
  D.Node = Node;

  /** Un fil : d'un point de sortie (from) à un point d'entrée (to). */
  class Wire {
    constructor(o) {
      this.id = o.id;
      this.from = { id: o.from.id, pip: o.from.pip };
      this.to = { id: o.to.id, pip: o.to.pip };
      this.blocking = o.blocking !== false;
      this.label = o.label || '';
      this.enabled = o.enabled !== false;
      this.meta = o.meta || {};
      this.trace = o.trace ? D.clone(o.trace) : null;
      /** Genre de lien (langage : `edges`) et ses champs : une transition, une relation, un flux… */
      this.type = o.type || null;
      this.fields = o.fields ? D.clone(o.fields) : {};
    }
  }
  D.Wire = Wire;
  /** Le libellé d'un fil : le sien, sinon le gabarit de son genre de lien (« {{event}} [{{guard}}] »), champs remplis. */
  D.edgeLabel = (ws, w) => {
    if (w.label) return w.label;
    const e = w.type && ws.registry.edge ? ws.registry.edge(w.type) : null;
    if (!e || !e.label) return '';
    if (typeof e.label === 'function') { try { return String(e.label(w, ws) || ''); } catch (_) { return ''; } }
    const show = (v) => (v == null ? '' : typeof v === 'object' && D.Expr ? D.Expr.text(v) : String(v));
    // Un gabarit simple ({{event}}) se remplit directement ; un gabarit avec des expressions ({{si(vide(guard), …)}})
    // s'évalue sur les champs du lien (les expressions y sont lues comme leur texte).
    const simple = /^([^{}]|\{\{\s*[\w.]+\s*\}\})*$/.test(e.label);
    let out;
    if (simple || !D.Behaviour) out = e.label.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, k) => show((w.fields || {})[k]));
    else {
      const scope = {};
      for (const k of Object.keys(e.fields || {})) scope[k] = null;
      for (const [k, v] of Object.entries(w.fields || {})) scope[k] = v && typeof v === 'object' && D.Expr ? D.Expr.text(v) : v;
      out = D.Behaviour.template(e.label, scope, (ws.language && ws.language.exprDialect) || D.Expr);
    }
    // Les morceaux vides (« [] », « / ») disparaissent.
    return out.replace(/\[\s*\]|\(\s*\)/g, '').replace(/\s+/g, ' ').replace(/^[\s/·]+|[\s/·]+$/g, '').trim();
  };

  class Workspace extends D.Emitter {
    /**
     * @param {{ registry?: object, types?: object, context?: object|D.Context, name?: string, options?: object,
     *           rules?: { chain?: 'types'|'count'|'both'|Function, wires?: boolean, list?: object[] }, modules?: boolean|object, language?: object }} o
     */
    constructor(o = {}) {
      super();
      this.types = o.types || (o.registry && o.registry.types) || new D.TypeSystem();
      this.registry = o.registry || new D.Registry(this.types);
      this.context = o.context instanceof D.Context ? o.context : new D.Context(o.context || {});
      /** Ressources du projet : documents JSON par clé (collection importée, environnements…). Voir setAsset(). */
      this.assets = new Map();
      this.assetsRev = 0;
      // Les portées nommées et les variables dynamiques du langage ({{token}} → env.token, {{$guid}}).
      if (o.language && o.language.variables) this.context.configure(o.language.variables);
      this.name = o.name || 'Projet';
      this.language = o.language || null;
      this.options = { historyLimit: 100, trace: true, journalLimit: 500, ...(o.options || {}) };
      /** Qui modifie (provenance des pierres et des fils, journal). */
      this.author = o.author || 'anonyme';
      /** Journal des opérations : une entrée par transaction, en JSON. */
      this.journal = [];
      const r = o.rules || {};
      /** Règles d'assemblage du langage. chain : 'types' (couleurs), 'count' (comme au jeu : même nombre de points), 'both', ou une fonction. */
      // cycles : les fils peuvent boucler (et revenir sur leur pierre) : machines à états, réseaux, graphes.
      this.rules = { chain: r.chain || 'types', wires: r.wires !== false, list: r.list || [], cycles: !!r.cycles };
      /** @type {Map<string, Node>} */
      this.nodes = new Map();
      /** @type {Map<string, Wire>} */
      this.wires = new Map();
      this.parties = new Map([['main', { id: 'main', name: 'Partie principale', owner: null, kind: 'main' }]]);
      this.logs = [];
      this.diagnostics = new Map();
      this._undo = []; this._redo = [];
      this._tx = null;
      this._seq = 0;
      /**
       * Révision : elle change à chaque modification (pierres, fils, champs, contexte, exécution).
       * Les caches s'y réfèrent : validate() ne refait rien si rien n'a changé.
       */
      this.rev = 0;
      // Index : les pierres par partie, les fils par pierre (entrants, sortants). Tenus par create, _dispose,
      // _addWire, _unwire et Serializer.load (_resetIndexes) : ce sont les seules écritures dans nodes et wires.
      this._byPartie = new Map();
      this._wTo = new Map();
      this._wFrom = new Map();
      this._wseq = 0;
      this.on('run:start', () => { this.rev++; });
      this.on('run:end', () => { this.rev++; });
      this.newId = D.idMaker('d', (id) => this.nodes.has(id));
      this.newWireId = D.idMaker('f', (id) => this.wires.has(id));
      this.context.on('change', (e) => { this.rev++; this.emit('context', { type: 'context', ...e, at: Date.now() }); });
      if (o.modules && D.Modules) new D.Modules(this, o.modules === true ? {} : o.modules);
    }

    // -------------------------------------------------------------------------
    // Lecture
    // -------------------------------------------------------------------------
    get(id) { return this.nodes.get(id) || null; }
    has(id) { return this.nodes.has(id); }
    require(id) {
      const n = this.nodes.get(id);
      if (!n) throw new D.DominoError('node.missing', `Aucune pierre « ${id} » dans l’espace.`, { id });
      return n;
    }
    nodesOf(partie = 'main') { const s = this._byPartie.get(partie); return s ? [...s] : []; }
    /** Vide les index (Serializer.load, après avoir vidé nodes et wires). */
    _resetIndexes() { this._byPartie.clear(); this._wTo.clear(); this._wFrom.clear(); }
    /** La validation est à refaire (règles ou langage changés hors d'une modification). */
    invalidate() { this.rev++; }
    roots(partie = 'main') { return this.nodesOf(partie).filter((n) => !n.parent); }
    parentOf(n) { return n && n.parent ? this.get(n.parent.id) : null; }
    partieKind(id) { const p = this.parties.get(id); return p ? p.kind || (id === 'main' ? 'main' : 'component') : 'main'; }

    /** Les faces de l'instance : celles de la définition, ou celles que rend le callback `pips`. */
    pipsOf(n) {
      const def = n.def;
      if (def.hooks.pips) {
        try {
          const r = def.hooks.pips(this.api(n)) || {};
          return { left: r.left ? D.normPips(r.left, 'left') : def.left, right: r.right ? D.normPips(r.right, 'right') : def.right };
        } catch (err) { this.log('error', `pips() de « ${def.name} » : ${err.message}`, { dominoId: n.id }); }
      }
      return { left: def.left, right: def.right };
    }
    titleOf(n) {
      if (n.label) return n.label;
      const def = n.def;
      if (def.hooks.title) { try { const s = def.hooks.title(this.api(n)); if (s) return String(s); } catch (_) { /* nom par défaut */ } }
      return def.name;
    }
    semanticsOf(n) { const p = this.pipsOf(n); return this.registry.semantics(p.left.length, p.right.length, n.def); }

    /** Enfants directs : [{ via, pip, node, link }]. */
    childrenOf(n) {
      const out = [];
      n.top.forEach((a) => out.push({ via: 'top', pip: a.pip, node: this.get(a.id) }));
      n.bottom.forEach((a) => out.push({ via: 'bottom', pip: a.pip, node: this.get(a.id) }));
      n.next.forEach((l, i) => { if (l) out.push({ via: 'next', pip: i, node: this.get(l.id), link: l }); });
      return out.filter((c) => c.node);
    }
    /** La pierre et tout ce qui y est collé (adjacentes et suite). */
    subtree(id, out = new Set()) {
      const n = this.get(id);
      if (!n || out.has(id)) return out;
      out.add(id);
      this.childrenOf(n).forEach((c) => this.subtree(c.node.id, out));
      return out;
    }
    /** `a` contient-il `b` (b est dans le sous-arbre de a) ? */
    contains(aId, bId) {
      for (let cur = this.get(bId), g = 0; cur && g < 10000; g++, cur = this.parentOf(cur)) if (cur.id === aId) return true;
      return false;
    }
    /** La tête de chaîne (racine) qui porte cette pierre. */
    rootOf(n) { let cur = n; while (cur && cur.parent) cur = this.parentOf(cur); return cur; }
    /** Profondeur d'adjacence (0 pour une pierre de chaîne). */
    adjacencyOf(n) {
      let depth = 0, side = null;
      for (let cur = n; cur && cur.parent && cur.parent.via !== 'next'; cur = this.parentOf(cur)) { depth++; side = side || cur.parent.via; }
      return { depth, side };
    }
    /** Une pierre posée libre sur la table : sans parent, et qui ne commence pas de chaîne. */
    isFree(n) { return !n.parent && !n.next.some(Boolean); }

    /**
     * Ce qui alimente chaque entrée : la pierre précédente (selon le câblage de la connexion), une adjacente haute ou un fil.
     * @returns {Array<{via:'prev'|'top'|'wire', node: Node, pip: number, wire?: Wire}|null>}
     */
    feedersOf(n) {
      const { left } = this.pipsOf(n);
      const out = left.map(() => null);
      const p = this.parentOf(n);
      if (p && n.parent.via === 'next') {
        const link = p.next[n.parent.pip];
        (link && link.map ? link.map : []).forEach((j) => { if (j < out.length) out[j] = { via: 'prev', node: p, pip: n.parent.pip }; });
      }
      n.top.forEach((a) => { if (a.pip < out.length && this.get(a.id)) out[a.pip] = { via: 'top', node: this.get(a.id), pip: 0 }; });
      for (const w of this._wTo.get(n.id) || []) if (w.to.pip < out.length && !out[w.to.pip] && this.get(w.from.id)) out[w.to.pip] = { via: 'wire', node: this.get(w.from.id), pip: w.from.pip, wire: w };
      return out;
    }
    /** Type de ce que fournit une pierre en adjacente haute (sa première sortie, ou `any` pour une valeur 0 | 0). */
    providedType(n) { const r = this.pipsOf(n).right; return r.length ? r[0].type : 'any'; }

    // Fils
    wiresOf(id) { return [...new Set([...(this._wFrom.get(id) || []), ...(this._wTo.get(id) || [])])].sort((a, b) => a._seq - b._seq); }
    wiresInto(id, pip) { const o = []; for (const w of this._wTo.get(id) || []) if (pip == null || w.to.pip === pip) o.push(w); return o; }
    wiresFrom(id, pip) { const o = []; for (const w of this._wFrom.get(id) || []) if (pip == null || w.from.pip === pip) o.push(w); return o; }
    wiresIn(partie = 'main') { return [...this.wires.values()].filter((w) => { const a = this.get(w.from.id); return a && a.partie === partie; }); }
    /** Genre d'un fil : 'call' (il porte une fonction), 'trigger' (il déclenche une pierre libre), 'data' (une valeur pour une pierre de chaîne). */
    wireKind(w) {
      const a = this.get(w.from.id), b = this.get(w.to.id);
      if (!a || !b) return 'data';
      const out = this.pipsOf(a).right[w.from.pip];
      if (out && this.types.kind(out.type) === 'call') return 'call';
      return !b.parent && !(b.def.instanceOf) ? 'trigger' : 'data';
    }

    // -------------------------------------------------------------------------
    // Règles d'assemblage
    // -------------------------------------------------------------------------
    _no(code, params) { return { ok: false, code, reason: t(code, params) }; }
    /** Règles du langage (rules.list), puis le dernier mot aux deux définitions. */
    /** Une pierre correspond-elle à une liste de permissions (types, genres, « ce que représente », '*') ? */
    _matches(list, n) { return list.includes('*') || list.includes(n.type) || (n.def.kind && list.includes(n.def.kind)) || (n.def.represents && list.includes(n.def.represents)); }
    /** Permissions des définitions : allow / deny de chaque côté de la connexion. */
    _permitted(p, c, via) {
      const sides = via === 'next' ? [[p, 'next', c], [c, 'prev', p]] : via === 'top' ? [[p, 'top', c]] : via === 'bottom' ? [[p, 'bottom', c]] : [[p, 'wireOut', c], [c, 'wireIn', p]];
      for (const [owner, key, other] of sides) {
        const k = owner.def.constraints || {};
        if (k.deny && k.deny[key] && this._matches(k.deny[key], other)) return this._no('connect.deny', { owner: this.titleOf(owner), other: this.titleOf(other), side: t(`side.${key}`) });
        if (k.allow && k.allow[key] && !this._matches(k.allow[key], other)) return this._no('connect.allow', { owner: this.titleOf(owner), other: this.titleOf(other), side: t(`side.${key}`), list: k.allow[key].join(', ') });
      }
      return null;
    }
    _lastWord(p, c, q) {
      const perm = this._permitted(p, c, q.via);
      if (perm) return perm;
      for (const rule of this.rules.list) {
        if (rule.on && ![].concat(rule.on).includes(q.via)) continue;
        let r;
        try { r = rule.check({ ...q, ws: this, parent: this.api(p), child: this.api(c) }); } catch (err) { r = err.message; }
        if (r !== true && r !== undefined && r !== null) return { ok: false, code: `rule.${rule.id || 'langage'}`, reason: String(r) };
      }
      for (const [n, role, other] of [[p, 'parent', c], [c, 'child', p]]) {
        const hook = n.def.hooks.canConnect;
        if (!hook) continue;
        let r;
        try { r = hook(this.api(n), { role, other: this.api(other), via: q.via, pip: q.pip, inPip: q.inPip }); } catch (err) { r = err.message; }
        if (r !== true && r !== undefined && r !== null) return { ok: false, code: 'connect.hook', reason: String(r) };
      }
      return null;
    }
    /** La règle de chaîne du langage : couleurs, nombre de points (comme au jeu), ou les deux. */
    _chainMatch(p, c, P, C, pip, skip) {
      const T = this.types, mode = this.rules.chain;
      const names = { parent: this.titleOf(p), child: this.titleOf(c) };
      if (typeof mode === 'function') {
        let r;
        try { r = mode({ parent: this.api(p), child: this.api(c), out: P.right[pip], right: P.right, left: C.left }); } catch (err) { r = err.message; }
        if (r !== true && r !== undefined && r !== null && typeof r !== 'number') return { error: { ok: false, code: 'rule.chain', reason: String(r) } };
        const j = typeof r === 'number' ? r : C.left.findIndex((_, k) => !skip.has(k));
        return j < 0 ? { error: this._no('connect.leftZero', names) } : { j };
      }
      if ((mode === 'count' || mode === 'both') && P.right.length !== C.left.length) return { error: this._no('connect.count', { ...names, right: P.right.length, left: C.left.length }) };
      const out = P.right[pip].type;
      // Une entrée « fonction » attend un fil depuis une méthode : la chaîne ne la remplit pas (sauf avec une fonction).
      const takes = (q, k) => !skip.has(k) && (T.kind(out) === 'call' || T.kind(q.type) !== 'call');
      const j = mode === 'count' ? C.left.findIndex(takes) : C.left.findIndex((q, k) => takes(q, k) && T.compatible(out, q.type, q.accepts));
      if (j < 0) return { error: this._no('connect.types', { ...names, out: T.label(out).toLowerCase(), in: [...new Set(C.left.map((q) => T.label(q.type).toLowerCase()))].join(', ') }) };
      return { j };
    }
    /**
     * Peut-on coller `childId` à `parentId` ? Ne modifie rien.
     * @param {'next'|'top'|'bottom'} via
     * @param {number} [pip] sortie (next, bottom) ou entrée (top) du parent ; choisie au mieux si absente
     * @param {{insert?: boolean}} [opts] next : insérer entre le parent et sa suite actuelle
     * @returns {{ok:true, via:string, pip:number, map?:number[]} | {ok:false, code:string, reason:string}}
     */
    canConnect(parentId, childId, via = 'next', pip, opts = {}) {
      const no = (code, params) => this._no(code, params);
      const p = this.get(parentId), c = typeof childId === 'object' ? childId : this.get(childId);
      if (!p || !c) return { ok: false, code: 'node.missing', reason: 'Pierre introuvable.' };
      if (!VIAS.includes(via)) return { ok: false, code: 'connect.via', reason: `Connexion inconnue « ${via} ».` };
      const names = { parent: this.titleOf(p), child: this.titleOf(c) };
      if (p.id === c.id) return no('connect.self', names);
      if (p.partie !== c.partie) return no('connect.partie', names);
      const cycle = () => this.contains(c.id, p.id);
      const P = this.pipsOf(p), C = this.pipsOf(c), T = this.types;
      const pdef = p.def;
      let res;
      if (via === 'next') {
        if (!pdef.chain) return no('connect.chainClosed', { child: names.parent });
        if (!c.def.chain) return no('connect.chainClosed', names);
        if (!P.right.length) return no('connect.rightZero', names);
        if (!C.left.length) return no('connect.leftZero', names);
        if (cycle()) return no('connect.cycle', names);
        if (pip == null) {
          pip = P.right.findIndex((_, i) => !p.next[i] || p.next[i].id === c.id);
          if (pip < 0) { if (opts.insert) pip = 0; else { const o = this.get(p.next[0].id); return no('connect.pipTaken', { ...names, pipName: P.right[0].name, other: this.titleOf(o) }); } }
        }
        if (pip >= P.right.length) return no('connect.noPip', { ...names, pip: pip + 1 });
        const taken = p.next[pip] && p.next[pip].id !== c.id ? this.get(p.next[pip].id) : null;
        if (taken && !opts.insert) return no('connect.pipTaken', { ...names, pipName: P.right[pip].name, other: this.titleOf(taken) });
        // Les entrées déjà alimentées (adjacente haute, fil) ne reçoivent pas la chaîne.
        const skip = new Set([...c.top.map((a) => a.pip), ...(typeof childId === 'object' ? [] : this.wiresInto(c.id).map((w) => w.to.pip))]);
        const m = this._chainMatch(p, c, P, C, pip, skip);
        if (m.error) return m.error;
        if (taken) {
          // Insertion : l'ancienne suite doit pouvoir suivre la pierre insérée.
          if (!C.right.length) return no('connect.rightZero', { parent: names.child });
          const m2 = this._chainMatch(c, taken, C, this.pipsOf(taken), 0, new Set(taken.top.map((a) => a.pip)));
          if (m2.error) return m2.error;
        }
        res = { ok: true, via, pip, map: [m.j], insert: !!taken };
      } else if (via === 'top') {
        if (!pdef.top.open) return no('connect.topClosed', names);
        const sem = this.registry.semantics(C.left.length, C.right.length, c.def);
        if (!sem.canBeTop) return no('connect.topSource', names);
        if (cycle()) return no('connect.cycle', names);
        const others = p.top.filter((a) => a.id !== c.id);
        if (others.length >= pdef.top.max) return no('connect.max', { ...names, max: pdef.top.max, side: t('side.top') });
        const out = this.providedType(c);
        const fed = this.feedersOf(p);
        const free = (j) => !fed[j] || (fed[j].via === 'top' && fed[j].node.id === c.id);
        const ok = (j) => j < P.left.length && T.compatible(out, P.left[j].type, P.left[j].accepts) && (!pdef.top.accepts || pdef.top.accepts.some((a) => T.isA(out, a)));
        if (pip == null) pip = P.left.findIndex((_, j) => free(j) && ok(j));
        if (pip == null || pip < 0) {
          return P.left.some((_, j) => ok(j)) ? no('connect.topFull', names)
            : no('connect.types', { parent: names.child, child: names.parent, out: T.label(out).toLowerCase(), in: [...new Set(P.left.map((q) => T.label(q.type).toLowerCase()))].join(', ') });
        }
        if (!ok(pip)) return no('connect.types', { parent: names.child, child: names.parent, out: T.label(out).toLowerCase(), in: T.label(P.left[pip].type).toLowerCase() });
        if (!free(pip)) return no('connect.topFull', names);
        res = { ok: true, via, pip };
      } else {
        if (!pdef.bottom.open || !P.right.length) return no('connect.bottomClosed', names);
        if (!C.left.length) return no('connect.bottomSink', names);
        if (!c.def.chain) return no('connect.chainClosed', names);
        if (cycle()) return no('connect.cycle', names);
        const others = p.bottom.filter((a) => a.id !== c.id);
        if (others.length >= pdef.bottom.max) return no('connect.max', { ...names, max: pdef.bottom.max, side: t('side.bottom') });
        const ok = (i) => i < P.right.length && C.left.some((q) => T.compatible(P.right[i].type, q.type, q.accepts)) && (!pdef.bottom.accepts || pdef.bottom.accepts.some((a) => T.isA(P.right[i].type, a)));
        if (pip == null) pip = P.right.findIndex((_, i) => ok(i));
        if (pip < 0 || !ok(pip)) return no('connect.types', { ...names, out: P.right.map((q) => T.label(q.type).toLowerCase()).join(', '), in: C.left.map((q) => T.label(q.type).toLowerCase()).join(', ') });
        res = { ok: true, via, pip };
      }
      return this._lastWord(p, c, { via, pip: res.pip }) || res;
    }

    /** `toId` dépend-il déjà de `fromId` (par collage ou par fil) ? Sert à refuser les fils qui bouclent. */
    _reaches(fromId, toId) {
      const seen = new Set(), stack = [fromId];
      while (stack.length) {
        const id = stack.pop();
        if (id === toId) return true;
        if (seen.has(id)) continue;
        seen.add(id);
        const n = this.get(id);
        if (!n) continue;
        n.next.forEach((l) => l && stack.push(l.id));
        n.bottom.forEach((a) => stack.push(a.id));
        if (n.parent && n.parent.via === 'top') stack.push(n.parent.id);
        for (const w of this._wFrom.get(id) || []) stack.push(w.to.id);
      }
      return false;
    }
    /**
     * Peut-on relier la sortie n° outPip de `fromId` à l'entrée n° inPip de `toId` par un fil ? Ne modifie rien.
     * inPip absent : la première entrée libre et compatible.
     * @param {{ replace?: string }} [opts] replace : le fil remplacé (déplacer une extrémité)
     * @returns {{ok:true, from:{id,pip}, to:{id,pip}} | {ok:false, code, reason}}
     */
    canWire(fromId, outPip, toId, inPip, opts = {}) {
      const no = (code, params) => this._no(code, params);
      if (!this.rules.wires) return no('wire.off');
      const a = typeof fromId === 'object' ? fromId : this.get(fromId), b = typeof toId === 'object' ? toId : this.get(toId);
      if (!a || !b) return { ok: false, code: 'node.missing', reason: 'Pierre introuvable.' };
      const names = { parent: this.titleOf(a), child: this.titleOf(b) };
      if (a.id === b.id && !this.rules.cycles) return no('connect.self', names);
      if (a.partie !== b.partie) return no('connect.partie', names);
      // Un genre de lien demandé : il doit exister, et permettre ces deux bouts.
      if (opts.type) {
        const e = this.registry.edge(opts.type);
        if (!e) return { ok: false, code: 'edge.unknown', reason: `Genre de lien inconnu : « ${opts.type} ».` };
        if (!D.edgeAllows(e, a, b)) return { ok: false, code: 'edge.ends', reason: `Un lien « ${e.name} » ne va pas de « ${this.titleOf(a)} » à « ${this.titleOf(b)} ».` };
      }
      // Une adjacente ne part pas par un fil ; une adjacente haute peut en recevoir un (une source collée sur une question…).
      for (const n of [a, b]) if (n.parent && n.parent.via !== 'next' && !(n === b && n.parent.via === 'top')) return no('wire.adjacent', { name: this.titleOf(n) });
      if (!a.def.wires || !b.def.wires) return no('wire.closed');
      const P = this.pipsOf(a).right, C = this.pipsOf(b).left, T = this.types;
      if (outPip == null) outPip = P.findIndex((q) => q.wire !== false);
      if (!(outPip >= 0 && outPip < P.length)) return no('wire.noOut', { parent: names.parent, pip: (outPip ?? 0) + 1 });
      const out = P[outPip];
      if (out.wire === false) return no('wire.closed');
      const fed = typeof toId === 'object' ? C.map(() => null) : this.feedersOf(b);
      const free = (j) => C[j].multiple || !fed[j] || (opts.replace && fed[j].via === 'wire' && fed[j].wire.id === opts.replace);
      const ok = (j) => C[j].wire !== false && T.compatible(out.type, C[j].type, C[j].accepts);
      if (inPip == null) {
        inPip = C.findIndex((_, j) => ok(j) && free(j));
        if (inPip < 0) return no('wire.full', { child: names.child, out: T.label(out.type).toLowerCase() });
      }
      if (!(inPip >= 0 && inPip < C.length)) return no('wire.noIn', { child: names.child, pip: inPip + 1 });
      if (C[inPip].wire === false) return no('wire.closed');
      if (!ok(inPip)) return no('connect.types', { ...names, out: T.label(out.type).toLowerCase(), in: T.label(C[inPip].type).toLowerCase() });
      if (!free(inPip)) return no('wire.taken', { pip: C[inPip].name, child: names.child, other: this.titleOf(fed[inPip].node) });
      if (!this.rules.cycles && T.kind(out.type) !== 'call' && typeof toId !== 'object' && typeof fromId !== 'object' && this._reaches(b.id, a.id)) return no('wire.cycle', names);
      return this._lastWord(a, b, { via: 'wire', pip: outPip, inPip }) || { ok: true, from: { id: a.id, pip: outPip }, to: { id: b.id, pip: inPip } };
    }

    /**
     * L'utilisateur peut-il faire cette action sur cette pierre ? 'delete', 'move', 'edit', 'duplicate'.
     * La vue demande avant d'agir ; l'API, elle, garde la main.
     */
    can(id, action) {
      const n = this.get(id);
      if (!n) return { ok: false, reason: 'Pierre introuvable.' };
      if (n.locked) return { ok: false, code: 'locked', reason: t('can.locked', { name: this.titleOf(n) }) };
      const c = n.def.constraints || {};
      const key = { delete: 'deletable', move: 'movable', edit: 'editable', duplicate: 'duplicable' }[action];
      if (key && c[key] === false) return { ok: false, code: `can.${action}`, reason: t(`can.${action}`, { name: this.titleOf(n) }) };
      if (action === 'duplicate' && c.max && [...this.nodes.values()].filter((x) => x.type === n.type).length >= c.max) return { ok: false, code: 'create.max', reason: t('create.max', { name: n.def.name, max: c.max }) };
      return { ok: true };
    }
    /** Un renvoi ({ $ref: id }) : sa cible (pierre, partie, déclaration ou variable). */
    resolveRef(v) {
      const id = v && typeof v === 'object' && v.$ref;
      if (!id) return null;
      if (this.nodes.has(id)) { const n = this.get(id); return { id, kind: n.def.kind === 'declaration' ? 'declaration' : n.def.kind === 'variable' ? 'variable' : 'domino', node: n, title: this.titleOf(n) }; }
      if (this.parties.has(id)) { const p = this.parties.get(id); return { id, kind: 'partie', partie: p, title: p.name }; }
      return { id, kind: 'missing', title: id };
    }

    // -------------------------------------------------------------------------
    // Modifications : chacune passe par une transaction (historique + événements groupés).
    // -------------------------------------------------------------------------
    /** Crée une pierre. `type` doit être déclaré ; un type inconnu donne une pierre « inconnue » qui garde ses données. */
    create(type, o = {}) {
      return this.transact(o.txLabel || 'Ajouter', () => {
        const known = this.registry.has(type);
        const def = this.registry.get(type);
        const id = o.id && !this.nodes.has(o.id) ? o.id : this.newId();
        const fields = {};
        for (const [k, f] of Object.entries(def.fields)) if (f.default !== undefined) fields[k] = D.clone(f.default);
        Object.assign(fields, D.clone(o.fields || {}));
        const n = new Node(this, { id, type: known ? type : 'domino.unknown', partie: o.partie || 'main', fields, label: o.label, turn: o.turn ? D.DIR_INTERNAL[o.turn] || o.turn : null, position: o.position || null, meta: D.clone(o.meta || {}), note: o.note, disabled: o.disabled, locked: o.locked, tags: o.tags, trace: o.trace });
        if (!n.trace && this.options.trace && !this._quiet) n.trace = { created: D.compact({ at: new Date().toISOString(), by: this.author, how: o.how || 'api', from: o.from }) };
        if (known && !this._quiet && !o.force) {
          const c = def.constraints || {};
          const same = [...this.nodes.values()].filter((x) => x.type === type);
          if (c.max && same.length >= c.max) throw new D.DominoError('create.max', t('create.max', { name: def.name, max: c.max }));
          if (c.maxPerPartie && same.filter((x) => x.partie === n.partie).length >= c.maxPerPartie) throw new D.DominoError('create.max', t('create.maxPartie', { name: def.name, max: c.maxPerPartie }));
        }
        if (!known) n.meta.unknownType = type;
        if (!this.parties.has(n.partie)) throw new D.DominoError('partie.missing', `Aucune partie « ${n.partie} ».`);
        const kind = this.partieKind(n.partie);
        if (known && !this._quiet && !def.where.includes(kind)) throw new D.DominoError('connect.where', t('connect.where', { child: def.name, where: PARTIE_LABEL[kind] || kind }));
        this.nodes.set(id, n);
        { let b = this._byPartie.get(n.partie); if (!b) this._byPartie.set(n.partie, (b = new Set())); b.add(n); }
        const fresh = def.container && !this.parties.has(id);
        if (fresh) this.parties.set(id, { id, name: def.name, owner: id, kind: def.container.partie || 'component' });
        this._hook(n, 'init');
        this._mut({ type: 'create', id, dominoType: n.type, partie: n.partie });
        // Un intérieur qui commence avec un contenu (comme un bloc Blockly livré avec ses blocs par défaut).
        if (fresh && def.inside && def.inside.template && !this._quiet) for (const j of def.inside.template) D.Serializer.loadNode(this, j, id, { freshIds: true });
        this._hook(n, 'onCreate');
        return n;
      });
    }

    /**
     * Colle `childId` au parent. La pierre quitte son ancienne place. Lève une DominoError expliquée si c'est interdit.
     * @param {{via?:'next'|'top'|'bottom', pip?:number, map?:number[], label?:string, insert?:boolean}} o
     */
    connect(parentId, childId, o = {}) {
      return this.transact(o.txLabel || 'Connecter', () => {
        const via = o.via || 'next';
        const r = this.canConnect(parentId, childId, via, o.pip, { insert: o.insert !== false });
        if (!r.ok) throw new D.DominoError(r.code, r.reason, { parentId, childId, via });
        const p = this.get(parentId), c = this.get(childId);
        if (c.parent) this._unlink(c);
        if (via === 'next') {
          const taken = p.next[r.pip] && p.next[r.pip].id !== c.id ? this.get(p.next[r.pip].id) : null;
          if (taken) this._unlink(taken);
          this._link(p, c, 'next', r.pip, { map: o.map || r.map, label: o.label || '', cond: o.cond || '', enabled: o.enabled !== false });
          if (taken) {
            const r2 = this.canConnect(c.id, taken.id, 'next', 0);
            if (r2.ok) this._link(c, taken, 'next', r2.pip, { map: r2.map }); else taken.position = null;
          }
        } else this._link(p, c, via, r.pip);
        return r;
      });
    }
    /**
     * Relie deux points par un fil. Lève une DominoError expliquée si c'est interdit.
     * @param {{ blocking?: boolean, label?: string, enabled?: boolean, replace?: string, id?: string }} o
     */
    wire(fromId, outPip, toId, inPip, o = {}) {
      return this.transact(o.txLabel || 'Relier', () => {
        const r = this.canWire(fromId, outPip, toId, inPip, { replace: o.replace, type: o.type });
        if (!r.ok) throw new D.DominoError(r.code, r.reason, { fromId, toId });
        if (o.replace && this.wires.has(o.replace)) this._unwire(this.wires.get(o.replace));
        // Sans genre demandé, le fil prend le genre de lien du langage qui convient (s'il en a), avec ses valeurs par défaut.
        const edge = o.type ? this.registry.edge(o.type) : this.registry.edges && this.registry.edges.size ? this.registry.edgeFor(this.get(r.from.id), this.get(r.to.id)) : null;
        const fields = {};
        if (edge) for (const [k, f] of Object.entries(edge.fields)) if (f.default !== undefined) fields[k] = D.clone(f.default);
        Object.assign(fields, D.clone(o.fields || {}));
        const w = new Wire({ id: o.id && !this.wires.has(o.id) ? o.id : this.newWireId(), from: r.from, to: r.to, blocking: o.blocking, label: o.label, enabled: o.enabled, meta: D.clone(o.meta || {}), type: edge ? edge.type : o.type, fields, trace: this.options.trace ? { created: D.compact({ at: new Date().toISOString(), by: this.author, how: o.how || 'api' }) } : null });
        this._addWire(w);
        return w;
      });
    }
    _addWire(w) {
      this.wires.set(w.id, w);
      Object.defineProperty(w, '_seq', { value: ++this._wseq, writable: true, configurable: true });
      for (const [m, k] of [[this._wTo, w.to.id], [this._wFrom, w.from.id]]) { let b = m.get(k); if (!b) m.set(k, (b = new Set())); b.add(w); }
      this._mut({ type: 'wire', id: w.id, from: { ...w.from }, to: { ...w.to }, blocking: w.blocking });
      const a = this.get(w.from.id), b = this.get(w.to.id);
      if (a) this._hook(a, 'onWire', { wire: w.id, side: 'out', pip: w.from.pip, other: w.to.id });
      if (b) this._hook(b, 'onWire', { wire: w.id, side: 'in', pip: w.to.pip, other: w.from.id });
    }
    unwire(id) {
      return this.transact('Retirer le fil', () => {
        const w = this.wires.get(id);
        if (!w) throw new D.DominoError('wire.missing', `Aucun fil « ${id} ».`);
        this._unwire(w);
      });
    }
    _unwire(w) {
      this.wires.delete(w.id);
      if (this._wTo.get(w.to.id)) this._wTo.get(w.to.id).delete(w);
      if (this._wFrom.get(w.from.id)) this._wFrom.get(w.from.id).delete(w);
      this._mut({ type: 'unwire', id: w.id, from: { ...w.from }, to: { ...w.to } });
      const a = this.get(w.from.id), b = this.get(w.to.id);
      if (a) this._hook(a, 'onUnwire', { wire: w.id, side: 'out', pip: w.from.pip, other: w.to.id });
      if (b) this._hook(b, 'onUnwire', { wire: w.id, side: 'in', pip: w.to.pip, other: w.from.id });
    }
    /** Réglages d'un fil : blocking (l'appelant attend ou continue), label, enabled. */
    setWire(id, patch) {
      return this.transact('Régler le fil', () => {
        const w = this.wires.get(id);
        if (!w) throw new D.DominoError('wire.missing', `Aucun fil « ${id} ».`);
        const old = { blocking: w.blocking, label: w.label, enabled: w.enabled, type: w.type, fields: D.clone(w.fields) };
        for (const k of ['blocking', 'label', 'enabled']) if (k in patch) w[k] = k === 'label' ? String(patch[k] || '') : patch[k] !== false;
        if (patch.meta) w.meta = { ...w.meta, ...D.clone(patch.meta) };
        // Le genre et les champs d'un lien (un champ à undefined est retiré).
        if ('type' in patch) {
          if (patch.type && !this.registry.edge(patch.type)) throw new D.DominoError('edge.unknown', `Genre de lien inconnu : « ${patch.type} ».`);
          w.type = patch.type || null;
        }
        if (patch.fields) for (const [k, v] of Object.entries(patch.fields)) { if (v === undefined) delete w.fields[k]; else w.fields[k] = D.clone(v); }
        this._mut({ type: 'wire:set', id, patch: D.clone(patch), old });
        // Un appel qui ne bloque plus gagne un point « suite » ; qui bloque à nouveau le perd : la suite branchée devient libre.
        const b = this.get(w.to.id);
        if (b) {
          const right = this.pipsOf(b).right.length;
          b.next.forEach((l, i) => { if (l && i >= right) { const c = this.get(l.id); this._unlink(c); c.position = b.position ? { x: b.position.x, y: b.position.y + 200 } : null; } });
        }
      });
    }
    /** Détache une pierre (avec ce qui y est collé) : elle devient une tête de chaîne libre. */
    detach(id, position = null) {
      return this.transact('Détacher', () => {
        const n = this.require(id);
        if (n.parent) this._unlink(n);
        n.position = position ? { x: Math.round(position.x), y: Math.round(position.y) } : n.position;
        if (position) this._mut({ type: 'move', id, x: n.position.x, y: n.position.y });
      });
    }
    /** Déplace une tête de chaîne. */
    move(id, x, y) {
      return this.transact('Déplacer', () => {
        const n = this.require(id);
        if (n.parent) this._unlink(n);
        n.position = { x: Math.round(x), y: Math.round(y) };
        this._mut({ type: 'move', id, x: n.position.x, y: n.position.y });
      });
    }
    /**
     * Supprime une pierre et ses adjacentes. Avec `heal`, la suite se recolle au parent si les règles le permettent
     * (comme on retire une pierre d'une rangée) ; sinon elle devient une chaîne libre.
     */
    remove(id, { heal = true } = {}) {
      return this.transact('Supprimer', () => {
        const n = this.require(id);
        const parent = this.parentOf(n), at = n.parent ? { ...n.parent } : null;
        const nexts = n.next.map((l) => l && this.get(l.id)).filter(Boolean);
        nexts.forEach((c) => this._unlink(c));
        if (n.parent) this._unlink(n);
        if (heal && parent && at && at.via === 'next' && nexts[0]) {
          const r = this.canConnect(parent.id, nexts[0].id, 'next', at.pip);
          if (r.ok) { this._link(parent, nexts[0], 'next', r.pip, { map: r.map }); nexts.shift(); }
        }
        nexts.forEach((c) => { c.position = n.position ? { x: n.position.x, y: n.position.y + 180 } : null; });
        this._dispose(n);
      });
    }
    _dispose(n) {
      [...n.top, ...n.bottom].forEach((a) => { const c = this.get(a.id); if (c) this._dispose(c); });
      if (this.parties.has(n.id)) { this.nodesOf(n.id).forEach((c) => this.nodes.has(c.id) && this._dispose(c)); this.parties.delete(n.id); }
      this.wiresOf(n.id).forEach((w) => this._unwire(w));
      this._hook(n, 'onDispose');
      this.nodes.delete(n.id);
      if (this._byPartie.get(n.partie)) this._byPartie.get(n.partie).delete(n);
      this.diagnostics.delete(n.id);
      this._mut({ type: 'delete', id: n.id, dominoType: n.type, partie: n.partie });
    }
    /** Copie une pierre avec ses adjacentes (pas sa suite). Rend la copie, posée en tête de chaîne. */
    duplicate(id, position) {
      return this.transact('Dupliquer', () => {
        const n = this.require(id);
        const json = D.Serializer.nodeToJSON(this, n, { next: false });
        const copy = D.Serializer.loadNode(this, json, n.partie, { freshIds: true });
        copy.position = position || (n.position ? { x: n.position.x + 40, y: n.position.y + 140 } : null);
        return copy;
      });
    }
    // -------------------------------------------------------------------------
    // Ressources du projet
    // -------------------------------------------------------------------------
    /** Une ressource du projet (copie), ou undefined. */
    getAsset(key) { return this.assets.has(key) ? D.clone(this.assets.get(key)) : undefined; }
    /**
     * Attache, remplace ou retire (value undefined) une ressource : un document JSON que le langage lit
     * (une collection d'API, des environnements, un jeu de données). Une entrée d'historique, émet « asset ».
     */
    setAsset(key, value, label = 'Modifier une ressource') {
      if (typeof key !== 'string' || !key) throw new D.DominoError('asset.key', 'Une ressource a une clé (texte).');
      return this.transact(label, () => {
        const had = this.assets.has(key);
        if (value === undefined) { if (!had) return; this.assets.delete(key); } else this.assets.set(key, D.clone(value));
        this.assetsRev++;
        this._assetsSig = null;
        this._mut({ type: 'asset', key, removed: value === undefined || undefined, added: !had || undefined });
        this.emit('asset', { type: 'asset', key, at: Date.now() });
      });
    }
    setField(id, key, value) {
      return this.transact('Modifier un champ', () => {
        const n = this.require(id);
        const old = n.fields[key];
        if (JSON.stringify(old) === JSON.stringify(value)) return;
        if (value === undefined) delete n.fields[key]; else n.fields[key] = D.clone(value);
        if (this.parties.has(n.id)) this.parties.get(n.id).name = this.titleOf(n);
        this._mut({ type: 'field', id, key, value, old });
        this._hook(n, 'onChange', { kind: 'field', key, value, old });
      });
    }
    setLabel(id, label) {
      return this.transact('Renommer', () => {
        const n = this.require(id);
        const old = n.label;
        n.label = label || '';
        if (this.parties.has(n.id)) this.parties.get(n.id).name = this.titleOf(n);
        this._mut({ type: 'label', id, value: n.label, old });
      });
    }
    /** Sens de la suite : null (la table décide), 'straight', 'E'|'S'|'W'|'N' ou 'right'|'down'|'left'|'up'. */
    setTurn(id, dir) {
      return this.transact('Tourner la suite', () => {
        const n = this.require(id);
        const v = dir == null ? null : D.DIR_INTERNAL[dir] || dir;
        if (v !== null && v !== 'straight' && !D.HEADINGS.includes(v)) throw new D.DominoError('turn.value', `Sens inconnu « ${dir} ».`);
        const old = n.turn;
        if (old === v) return;
        n.turn = v;
        this._mut({ type: 'turn', id, value: v, old });
        this._hook(n, 'onChange', { kind: 'turn', value: v, old });
      });
    }
    /** Réglages d'une connexion de chaîne : label, cond, enabled, map (entrées câblées). */
    setLink(parentId, pip, patch) {
      return this.transact('Régler la connexion', () => {
        const p = this.require(parentId);
        const l = p.next[pip];
        if (!l) throw new D.DominoError('link.missing', `La sortie n° ${pip + 1} de « ${this.titleOf(p)} » n’est pas connectée.`);
        const old = { ...l };
        Object.assign(l, D.clone(patch));
        this._mut({ type: 'link', parent: parentId, pip, patch, old });
      });
    }
    /** Note de l'utilisateur. */
    setNote(id, note) {
      return this.transact('Annoter', () => { const n = this.require(id); const old = n.note; n.note = String(note || ''); if (old !== n.note) this._mut({ type: 'note', id, value: n.note, old }); });
    }
    /** Drapeau d'une pierre : 'disabled' (neutralisée) ou 'locked' (verrouillée). */
    setFlag(id, flag, value) {
      if (!['disabled', 'locked'].includes(flag)) throw new D.DominoError('flag.unknown', `Drapeau inconnu « ${flag} » (disabled, locked).`);
      return this.transact(flag === 'disabled' ? (value ? 'Neutraliser' : 'Réactiver') : value ? 'Verrouiller' : 'Déverrouiller', () => {
        const n = this.require(id); const old = n[flag]; n[flag] = !!value;
        if (old !== n[flag]) { this._mut({ type: 'flag', id, flag, value: n[flag], old }); this._hook(n, 'onChange', { kind: flag, value: n[flag], old }); }
      });
    }
    setTags(id, tags) {
      return this.transact('Étiqueter', () => { const n = this.require(id); const old = n.tags; n.tags = [...new Set((tags || []).map(String).filter(Boolean))]; this._mut({ type: 'tags', id, value: n.tags, old }); });
    }
    setMeta(id, key, value) {
      return this.transact('Métadonnée', () => { const n = this.require(id); n.meta[key] = D.clone(value); this._mut({ type: 'meta', id, key, value }); });
    }

    _link(p, c, via, pip, link = {}) {
      c.parent = { id: p.id, via, pip };
      c.position = null;
      if (via === 'next') p.next[pip] = { id: c.id, map: link.map || null, label: link.label || '', cond: link.cond || '', enabled: link.enabled !== false };
      else {
        const list = via === 'top' ? p.top : p.bottom;
        const k = list.findIndex((a) => a.pip > pip);
        list.splice(k < 0 ? list.length : k, 0, { id: c.id, pip });
      }
      this._mut({ type: 'connect', parent: p.id, child: c.id, via, pip });
      this._hook(c, 'onAttach', { parent: p.id, via, pip });
      this._hook(p, 'onConnect', { child: c.id, via, pip });
    }
    _unlink(c) {
      const p = this.parentOf(c);
      const at = c.parent;
      c.parent = null;
      if (!p) return;
      if (at.via === 'next') { if (p.next[at.pip] && p.next[at.pip].id === c.id) p.next[at.pip] = undefined; while (p.next.length && !p.next[p.next.length - 1]) p.next.pop(); }
      else { const list = at.via === 'top' ? p.top : p.bottom; const k = list.findIndex((a) => a.id === c.id); if (k >= 0) list.splice(k, 1); }
      this._mut({ type: 'disconnect', parent: p.id, child: c.id, via: at.via, pip: at.pip });
      this._hook(c, 'onDetach', { parent: p.id, via: at.via, pip: at.pip });
      this._hook(p, 'onDisconnect', { child: c.id, via: at.via, pip: at.pip });
    }

    // -------------------------------------------------------------------------
    // Transactions, historique, événements
    // -------------------------------------------------------------------------
    /** Groupe des modifications : une seule entrée d'historique, un seul `change`. Une erreur annule tout. */
    transact(label, fn) {
      if (this._tx) return fn();
      // L'historique garde des instantanés en texte (trois fois plus légers que des objets) ; l'état « avant »
      // d'une transaction est presque toujours l'« après » de la précédente : la même chaîne est alors partagée.
      let before = JSON.stringify(D.Serializer.toJSON(this, { context: false }));
      const prev = this._undo[this._undo.length - 1];
      if (prev && prev.after === before) before = prev.after;
      this._tx = { label, events: [] };
      let result;
      try { result = fn(); } catch (err) {
        const tx = this._tx; this._tx = null;
        if (tx.events.length) this._restore(before);
        throw err;
      }
      const tx = this._tx; this._tx = null;
      if (tx.events.length) {
        this._undo.push({ label, before, after: JSON.stringify(D.Serializer.toJSON(this, { context: false })) });
        if (this._undo.length > this.options.historyLimit) this._undo.shift();
        this._redo = [];
        // Le journal garde chaque opération, sous une forme courte et lisible.
        this.journal.push({ seq: this._seq, at: new Date().toISOString(), by: this.author, label, events: tx.events.map((e) => D.compact({ type: e.type, id: e.id, parent: e.parent, child: e.child, via: e.via, pip: e.pip, key: e.key, flag: e.flag, from: e.from && e.from.id, to: e.to && e.to.id, dominoType: e.dominoType, partie: e.partie })) });
        if (this.journal.length > this.options.journalLimit) this.journal.splice(0, this.journal.length - this.options.journalLimit);
        this.emit('transaction', { type: 'transaction', label, count: tx.events.length, at: Date.now() });
        this.emit('change', { type: 'change', reason: label, events: tx.events });
      }
      return result;
    }
    _mut(ev) {
      ev.seq = ++this._seq;
      this.rev++;
      ev.at = Date.now();
      if (this._tx) this._tx.events.push(ev);
      if (!this._quiet) {
        this._touch(ev);
        this.emit(ev.type, ev);
      }
    }
    /** Provenance : la dernière modification de chaque pierre touchée (quand, qui, combien de fois). */
    _touch(ev) {
      if (!this.options.trace || ev.type === 'create' || ev.type === 'delete') return;
      const ids = [ev.id, ev.parent, ev.child, ev.from && ev.from.id, ev.to && ev.to.id].filter((x) => typeof x === 'string');
      const at = new Date(ev.at).toISOString();
      for (const id of new Set(ids)) {
        const n = this.nodes.get(id);
        if (!n) continue;
        n.trace = n.trace || {};
        n.trace.modified = { at, by: this.author, count: ((n.trace.modified && n.trace.modified.count) || 0) + 1, last: ev.type };
      }
    }
    /**
     * Marqueur d'historique : l'entrée au sommet de la pile d'annulation. Un document est « modifié » quand ce
     * marqueur diffère de celui noté à l'enregistrement (annuler jusqu'à l'état enregistré le rend propre).
     */
    historyMark() { return this._undo[this._undo.length - 1] || null; }
    get canUndo() { return this._undo.length > 0; }
    get canRedo() { return this._redo.length > 0; }
    undo() {
      const e = this._undo.pop();
      if (!e) return false;
      this._redo.push(e);
      this._restore(e.before);
      this.emit('undo', { type: 'undo', label: e.label, at: Date.now() });
      this.emit('change', { type: 'change', reason: 'undo' });
      return true;
    }
    redo() {
      const e = this._redo.pop();
      if (!e) return false;
      this._undo.push(e);
      this._restore(e.after);
      this.emit('redo', { type: 'redo', label: e.label, at: Date.now() });
      this.emit('change', { type: 'change', reason: 'redo' });
      return true;
    }
    /**
     * Change de langage à chaud (le Concepteur recompile) : le projet est relu avec les nouvelles définitions ;
     * l'historique est gardé (ses instantanés sont du JSON). Rend le rapport du chargement.
     */
    setLanguage(L) {
      const json = D.Serializer.toJSON(this, { context: false });
      const reg = L.createRegistry();
      this.language = L;
      this.registry = reg;
      this.types = reg.types;
      this.rules = { chain: L.rules.chain || 'types', wires: L.rules.wires !== false, list: L.rules.list || [], cycles: !!L.rules.cycles };
      if (L.modules && D.Modules) new D.Modules(this, L.modules === true ? {} : L.modules);
      this.editorInfo = { ...(this.editorInfo || {}), id: L.id, name: L.name };
      this.context.configure(L.variables || {});
      this._vsig = null;
      const rep = D.Serializer.load(this, json, { history: false, context: false, silent: true });
      this.rev++;
      this.emit('language', { type: 'language', id: L.id, at: Date.now() });
      this.emit('change', { type: 'change', reason: 'language' });
      return rep;
    }
    /**
     * Remplace tout le projet (une projection texte, un import) en une seule entrée d'historique.
     * → le rapport du chargement ; s'il échoue, rien ne change.
     */
    replace(json, label = 'Remplacer') {
      const before = JSON.stringify(D.Serializer.toJSON(this, { context: false }));
      const rep = D.Serializer.load(this, json, { history: false, context: false, silent: true });
      if (!rep.ok) { this._restore(before); return rep; }
      const after = JSON.stringify(D.Serializer.toJSON(this, { context: false }));
      if (after === before) return rep;
      this._undo.push({ label, before, after });
      if (this._undo.length > this.options.historyLimit) this._undo.shift();
      this._redo = [];
      this.emit('transaction', { type: 'transaction', label, count: 1, at: Date.now() });
      this.emit('change', { type: 'change', reason: label });
      return rep;
    }
    _restore(json) { D.Serializer.load(this, json, { history: false, context: false, silent: true }); }

    _hook(n, name, arg) {
      const fn = n.def.hooks[name];
      if (!fn || (this._restoring && name !== 'init')) return undefined;
      try { return fn(this.api(n), arg); } catch (err) { this.log('error', `${name}() de « ${n.def.name} » : ${err.message}`, { dominoId: n.id }); return undefined; }
    }

    /** Journal : alimente la console de l'inspecteur. */
    log(level, message, extra = {}) {
      const entry = { type: 'log', level, message: String(message), at: Date.now(), ...extra };
      this.logs.push(entry);
      if (this.logs.length > 800) this.logs.splice(0, this.logs.length - 800);
      this.emit('log', entry);
      return entry;
    }

    /**
     * API donnée aux callbacks d'une pierre : tout ce dont le développeur a besoin, rien de plus.
     * Le même objet sert aux callbacks de définition, aux règles et aux onglets de l'inspecteur.
     */
    api(n) {
      const ws = this;
      return {
        domino: n, id: n.id, type: n.type, def: n.def, workspace: ws, context: ws.context, language: ws.language,
        /** Valeur d'un champ, liaisons et gabarits résolus. */
        field: (key) => ws.context.resolve(n.fields[key]),
        raw: (key) => n.fields[key],
        set: (key, value) => ws.setField(n.id, key, value),
        title: () => ws.titleOf(n),
        pips: () => ws.pipsOf(n),
        semantics: () => ws.semanticsOf(n),
        parent: () => ws.parentOf(n),
        children: () => ws.childrenOf(n),
        feeders: () => ws.feedersOf(n),
        wires: () => ws.wiresOf(n.id),
        wireInto: (pip) => ws.wiresInto(n.id, pip)[0] || null,
        /** La cible d'un champ renvoi : { id, kind, node | partie, title }. */
        ref: (key) => ws.resolveRef(n.fields[key]),
        can: (action) => ws.can(n.id, action),
        partieKind: () => ws.partieKind(n.partie),
        log: (level, message, data) => ws.log(level, message, { dominoId: n.id, data }),
        emit: (name, payload) => ws.emit(`custom:${name}`, { type: `custom:${name}`, dominoId: n.id, payload, at: Date.now() }),
        meta: (key, value) => (value === undefined ? n.meta[key] : ws.setMeta(n.id, key, value)),
        state: n.state,
      };
    }

    // -------------------------------------------------------------------------
    // Diagnostics
    // -------------------------------------------------------------------------
    /** Vérifie tout l'espace. Rend la liste des diagnostics { level, code, message, dominoId, pip? }. */
    /**
     * Diagnostics de toutes les pierres. Mémorisés : refaits seulement si le projet a changé depuis (révision),
     * ou si les règles ont changé. Rend une copie (on peut la trier).
     */
    validate() {
      const sig = `${this.rev}|${this.rules.chain}|${this.rules.wires}|${this.rules.list.length}|${this.registry.defs ? this.registry.defs.size : 0}`;
      if (this._vsig === sig && this._vall) return this._vall.slice();
      const all = [];
      this.diagnostics.clear();
      // Les variables que des pierres définissent à l'exécution (« Définir », « Extraire »…) : le langage les nomme,
      // une liaison vers elles n'est pas une faute (variables.declared(ws) → noms).
      const V = this.language && this.language.variables;
      this._declared = V && typeof V.declared === 'function' ? new Set((() => { try { return V.declared(this) || []; } catch (_) { return []; } })()) : null;
      for (const n of this.nodes.values()) {
        const list = this.diagnose(n);
        this.diagnostics.set(n.id, list);
        all.push(...list);
      }
      // Ce que le moteur d'exécution du langage demande (un état initial, un début…).
      if (D.Engines) for (const pid of this.parties.keys()) if (this.partieKind(pid) === 'main') all.push(...D.Engines.check(this, pid).map((d) => ({ ...d, partie: pid })));
      this._vsig = sig;
      this._vall = all;
      return all.slice();
    }
    /** Vérifie des valeurs de champs contre leurs définitions (une pierre, ou un lien typé : n vaut alors null). */
    _checkFields(defs, values, add, n) {
      for (const [key, f] of Object.entries(defs || {})) {
        const raw = values[key];
        if (D.Context.isBinding(raw)) continue;
        const v = this.context.resolve(raw), label = f.label || key;
        const empty = v === undefined || v === null || v === '' || (Array.isArray(v) && !v.length);
        if (f.required && empty) { add('warn', 'field.required', t('diag.required', { field: label }), { field: key }); continue; }
        if (empty && f.kind === 'table' && f.min) add('warn', 'field.min', `« ${label} » : au moins ${f.min} ligne(s).`, { field: key });
        if (empty) continue;
        if (f.kind === 'number' && typeof v === 'number') {
          if (f.min != null && v < f.min) add('warn', 'field.min', t('diag.min', { field: label, min: f.min }), { field: key });
          if (f.max != null && v > f.max) add('warn', 'field.max', t('diag.max', { field: label, max: f.max }), { field: key });
        }
        if (f.pattern && typeof v === 'string' && !new RegExp(f.pattern, 'u').test(v)) add('warn', 'field.pattern', t('diag.pattern', { field: label }), { field: key });
        if (f.kind === 'ref') {
          const r = this.resolveRef(raw);
          if (!r || r.kind === 'missing') add('error', 'ref.missing', t('diag.refMissing', { field: label }), { field: key });
          else if (f.to && ![].concat(f.to).some((x) => x === r.kind || (r.node && (r.node.type === x || r.node.def.kind === x)))) add('warn', 'ref.kind', t('diag.refKind', { field: label, to: [].concat(f.to).join(', ') }), { field: key });
        }
        // Une expression : bien formée (opérateurs connus, nombre d'arguments) dans le dialecte du langage.
        if (f.kind === 'expr' && D.Expr) {
          const E = (this.language && this.language.exprDialect) || D.Expr;
          const r = E.read(v);
          if (r.errors.length) add('error', 'field.expr', `« ${label} » : ${r.errors[0]}`, { field: key });
        }
        // Un tableau : nombre de lignes, colonnes requises, expressions des colonnes.
        if (f.kind === 'table') {
          const rows = Array.isArray(v) ? v : [];
          if (!Array.isArray(v)) add('error', 'field.table', `« ${label} » : une liste de lignes est attendue.`, { field: key });
          if (f.min != null && rows.length < f.min) add('warn', 'field.min', `« ${label} » : au moins ${f.min} ligne(s).`, { field: key });
          if (f.max != null && rows.length > f.max) add('warn', 'field.max', `« ${label} » : au plus ${f.max} ligne(s).`, { field: key });
          const E = (this.language && this.language.exprDialect) || D.Expr;
          rows.forEach((row, i) => {
            for (const [ck, c] of Object.entries(f.columns || {})) {
              const cv = row ? row[ck] : undefined;
              if (c.required && (cv === undefined || cv === null || cv === '')) add('warn', 'field.required', `« ${label} », ligne ${i + 1} : « ${c.label || ck} » est requis.`, { field: key, row: i });
              if (c.kind === 'expr' && cv != null && cv !== '' && E) { const r = E.read(cv); if (r.errors.length) add('error', 'field.expr', `« ${label} », ligne ${i + 1}, « ${c.label || ck} » : ${r.errors[0]}`, { field: key, row: i }); }
            }
          });
        }
        if (f.validate) { let m; try { m = f.validate(v, n ? this.api(n) : null); } catch (err) { m = err.message; } if (m && m !== true) add('warn', 'field.custom', String(m), { field: key }); }
      }
    }
    diagnose(n) {
      const out = [];
      const add = (level, code, message, extra = {}) => out.push({ level, code, message, dominoId: n.id, ...extra });
      if (n.meta.unknownType) add('error', 'unknownType', t('diag.unknownType', { type: n.meta.unknownType }));
      const { left } = this.pipsOf(n);
      const fed = this.feedersOf(n);
      const kind = this.partieKind(n.partie);
      // Une déclaration montre ce qu'elle exige : ses entrées ne sont pas à alimenter ici.
      if (n.def.kind !== 'declaration') left.forEach((q, j) => {
        if (q.required !== false && !fed[j]) {
          // Une pierre en adjacente basse reçoit la sortie de son parent sur sa première entrée.
          if (n.parent && n.parent.via === 'bottom' && j === 0) return;
          // Dans une sous-partie, la tête de chaîne reçoit les entrées du conteneur.
          if (!n.parent && kind === 'component' && n.type === 'domino.entry') return;
          add('warn', 'unfed', t('diag.unfed', { pip: q.name, type: this.types.label(q.type).toLowerCase() }), { pip: j });
        }
      });
      // Câblage de la connexion entrante : chaque fil doit porter un type accepté.
      const p = this.parentOf(n);
      if (p && n.parent.via === 'next' && this.rules.chain !== 'count' && typeof this.rules.chain !== 'function') {
        const link = p.next[n.parent.pip];
        const outT = this.pipsOf(p).right[n.parent.pip];
        (link && link.map || []).forEach((j) => {
          if (left[j] && outT && !this.types.compatible(outT.type, left[j].type, left[j].accepts)) add('error', 'mapType', t('diag.mapType', { pip: left[j].name, out: this.types.label(outT.type).toLowerCase(), in: this.types.label(left[j].type).toLowerCase() }), { pip: j });
        });
      }
      // Fils : un point disparu (faces dynamiques) ou des couleurs qui ne vont plus ensemble ; les champs d'un lien typé.
      for (const w of this.wiresInto(n.id)) {
        const e = w.type ? this.registry.edge(w.type) : null;
        if (w.type && !e) add('warn', 'edge.unknown', `Le fil « ${w.id} » a un genre de lien inconnu : « ${w.type} ».`, { wire: w.id });
        if (e) {
          this._checkFields(e.fields, w.fields || {}, (level, code, message, extra) => add(level, code, `Lien ${w.label ? `« ${w.label} »` : w.id} : ${message}`, { wire: w.id, ...extra }), null);
          if (e.validate) { try { (e.validate(w, this) || []).forEach((d) => add(d.level || 'warn', d.code || 'edge.custom', d.message, { wire: w.id })); } catch (err) { add('error', 'hook', `validate du lien : ${err.message}`, { wire: w.id }); } }
        }
        const a = this.get(w.from.id), outT = a && this.pipsOf(a).right[w.from.pip];
        if (!left[w.to.pip] || !outT) add('error', 'wirePip', `Un fil arrive sur un point qui n’existe plus (entrée n° ${w.to.pip + 1}).`, { wire: w.id });
        else if (!this.types.compatible(outT.type, left[w.to.pip].type, left[w.to.pip].accepts)) add('error', 'wireType', t('diag.mapType', { pip: left[w.to.pip].name, out: this.types.label(outT.type).toLowerCase(), in: this.types.label(left[w.to.pip].type).toLowerCase() }), { wire: w.id });
      }
      for (const [key, v] of Object.entries(n.fields)) {
        for (const path of D.Context.pathsOf(v)) if (!this.context.resolves(path) && !(this._declared && this._declared.has(path))) add('warn', 'binding', t('diag.binding', { path }), { field: key });
      }
      // Chaque champ dit ce qu'il accepte : requis, bornes, motif, renvoi, validation propre.
      this._checkFields(n.def.fields, n.fields, add, n);
      if (n.def.deprecated) add('info', 'deprecated', t('diag.deprecated', { name: n.def.name, why: n.def.deprecated }));
      const hook = n.def.hooks.validate;
      if (hook) {
        try { (hook(this.api(n)) || []).forEach((d) => add(d.level || 'warn', d.code || 'custom', d.message, d)); } catch (err) { add('error', 'hook', `validate() : ${err.message}`); }
      }
      if (n.state.runError) add('error', 'run', n.state.runError);
      return out;
    }
  }
  D.Workspace = Workspace;
})(typeof globalThis !== 'undefined' ? globalThis : window);
