/*!
 * Zeugma · registre des importeurs (point d'extension)
 *
 * Un importeur lit un fichier venu d'un autre outil (une collection Postman, un environnement, un schéma
 * OpenAPI, un tableur exporté…) et en fait un projet, ou l'ajoute au projet ouvert. Le studio les propose
 * dans « Fichier › Importer ▸ » et les essaie d'eux-mêmes quand on ouvre ou dépose un fichier.
 *
 *   Domino.Importers.register({
 *     id: 'tnr/postman-collection', language: 'tnr', label: 'Collection Postman (v2.1)…',
 *     extensions: ['json'], description: '…',
 *     detect(json, name) { return json && json.info && /getpostman/.test(json.info.schema) ? 1 : 0; },   // 0 : non ; plus haut : plus sûr
 *     import(json, ctx) {                    // ctx : { name, ws?, language }  (ws : le projet ouvert, s'il est du même langage)
 *       return { project };                  // un nouveau projet (format v2)…
 *       return { apply(ws) { … }, summary }; // … ou des changements apportés au projet ouvert (une entrée d'historique)
 *     },
 *   });
 *   Domino.Importers.detect(json, 'fichier.json')  → l'importeur le plus sûr, ou null
 *   Domino.Importers.run(id, json, { ws, name })   → { project?, applied?, warnings, summary }
 *
 * Sans DOM : un importeur se teste dans Node.
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const reg = new Map();

  function normalize(d) {
    if (!d || typeof d.id !== 'string' || !d.id) throw new D.DominoError('importer.id', 'Un importeur a un identifiant (id).');
    if (typeof d.import !== 'function') throw new D.DominoError('importer.fn', `L’importeur « ${d.id} » n’a pas de fonction import(json, ctx).`);
    return { language: '*', label: d.id, description: '', extensions: ['json'], detect: () => 0, ...d };
  }

  const Importers = {
    /** Inscrit un importeur ; rend une fonction qui le retire. */
    register(d) {
      const imp = normalize(d);
      reg.set(imp.id, imp);
      return () => { if (reg.get(imp.id) === imp) reg.delete(imp.id); };
    },
    get(id) { return reg.get(id) || null; },
    list(language) { return [...reg.values()].filter((d) => !language || d.language === '*' || d.language === language); },
    /** L'importeur qui reconnaît le mieux ce contenu (score de detect le plus haut, > 0), ou null. */
    detect(json, name = '') {
      let best = null, score = 0;
      for (const d of reg.values()) {
        let s;
        try { s = Number(d.detect(json, name)) || 0; } catch (_) { s = 0; }
        if (s > score) { best = d; score = s; }
      }
      return best;
    },
    /**
     * Importe. Avec ctx.ws (un projet ouvert du même langage) et un importeur qui sait compléter un projet,
     * les changements y sont appliqués en une seule entrée d'historique ; sinon un nouveau projet est rendu.
     * @returns {{ project?: object, applied?: boolean, warnings: string[], summary?: string, importer: string }}
     */
    run(id, json, ctx = {}) {
      const d = reg.get(id);
      if (!d) throw new D.DominoError('importer.unknown', `Importeur inconnu : « ${id} ».`);
      const sameLang = ctx.ws && ctx.ws.language && (d.language === '*' || ctx.ws.language.id === d.language);
      const res = d.import(json, { name: ctx.name || '', ws: sameLang ? ctx.ws : null, language: d.language }) || {};
      const out = { warnings: res.warnings || [], summary: res.summary, importer: d.id };
      if (res.apply && sameLang) {
        ctx.ws.transact(res.label || d.label.replace(/…$/, ''), () => res.apply(ctx.ws));
        out.applied = true;
      } else if (res.project) out.project = res.project;
      else if (res.apply) throw new D.DominoError('importer.needsProject', `« ${d.label.replace(/…$/, '')} » complète un projet : ouvrez d’abord un projet du langage « ${d.language} ».`);
      return out;
    },
  };

  D.Importers = Importers;
})(typeof globalThis !== 'undefined' ? globalThis : window);
