/*!
 * Zeugma · langage
 * Un éditeur est une instance d'un langage. Le langage dit tout ce qui change d'un éditeur à l'autre :
 *
 *   types       les couleurs des points et ce qu'elles transportent (valeur, fonction…) ;
 *   dominos     les pierres, leurs faces, leurs champs, leurs callbacks (en JS ou en texte) ;
 *   semantics   ce que veut dire le nombre de points à gauche et à droite ;
 *   rules       comment les pierres se collent (couleurs, nombre de points comme au jeu, les deux,
 *               ou une fonction), si les fils sont permis, et des règles nommées pour chaque connexion ;
 *   faces       la couleur des façades selon le genre ou le rôle d'une pierre, avec sa légende ;
 *   modules     les déclarations (classes, bibliothèques, fonctions), renommables ou retirées ;
 *   context, project, generators, inspector, options, setup, events.
 *
 *   const lang = Domino.language({ id: 'kanto', name: 'Kanto', types: […], dominos: […], rules: { chain: 'both' } });
 *   const editor = Domino.create('#host', lang);          // avec la vue
 *   const { ws, runtime } = lang.instantiate();           // sans la vue (Node, serveur, tests)
 *
 * Un langage écrit en JSON (callbacks dans `code`) se charge avec Domino.language(json) : il peut être
 * enregistré, partagé, généré… par un autre éditeur Domino (voir la démo « Atelier »).
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const CHAIN_RULES = ['types', 'count', 'both'];

  class Language {
    constructor(spec = {}) {
      if (spec instanceof Language) return spec;
      if (spec.format === 'kantoaplo.language' && spec.version > 1) throw new D.DominoError('lang.version', `Version de langage ${spec.version} non prise en charge.`);
      this.spec = spec;
      this.id = spec.id || 'langage';
      this.name = spec.name || this.id;
      this.color = spec.color || '#B8893B';
      this.description = spec.description || '';
      const r = spec.rules || {};
      if (r.chain && typeof r.chain !== 'function' && !CHAIN_RULES.includes(r.chain)) throw new D.DominoError('lang.rules', `rules.chain vaut ${CHAIN_RULES.join(', ')} ou une fonction.`);
      // Une règle peut être écrite en texte : { id, on, when: "q.child.type === 'x'", message } (langages en JSON),
      // ou, sans code, en expression déclarative : { id, on, if: 'child.kind == "fin" et parent.kind == "début"', message }.
      const list = (r.list || []).map((x) => {
        if (typeof x.check !== 'function' && x.if != null && D.Behaviour) {
          const X = spec.expr && spec.expr.ops && D.Expr ? D.Expr.extend(spec.expr.ops) : D.Expr;
          const e = D.Behaviour.exprOf(x.if, X);
          return { ...x, check: (q) => { const scope = { parent: D.Behaviour.summaryOf(q.parent), child: D.Behaviour.summaryOf(q.child), via: q.via, pip: q.pip }; return X.test(e, scope) ? D.Behaviour.template(x.message || `Refusé par la règle « ${x.id || 'du langage'} ».`, scope, X) : true; } };
        }
        if (typeof x.check === 'function' || !x.when) return x;
        let fn;
        try { fn = new Function('q', `"use strict"; return (${x.when});`); } catch (err) { throw new D.DominoError('lang.rule', `Règle « ${x.id || '?'} » : la condition ne se compile pas : ${err.message}`); }
        return { ...x, check: (q) => (fn(q) ? x.message || `Refusé par la règle « ${x.id || 'du langage'} ».` : true) };
      });
      this.rules = { chain: r.chain || 'types', wires: r.wires !== false, list, cycles: !!r.cycles };
      /** Genres de liens : des fils typés qui portent des champs (transition, relation…). */
      this.edges = spec.edges || [];
      /** Le moteur d'exécution : { engine: 'statemachine' | 'tokens' | 'decision' } ; sans moteur, l'effet domino. */
      this.execution = spec.execution || null;
      /** Les projections proposées : { default: 'dominos', list: ['diagram', 'text', 'grid'] }. */
      this.projections = spec.projections || null;
      this.faces = spec.faces || null;
      this.modules = spec.modules || false;
      this.semantics = typeof spec.semantics === 'function' ? spec.semantics : null;
      this.events = spec.events || {};
      // Les clés connues d'un « pack » restent lisibles telles quelles (rétrocompatibilité).
      for (const k of ['types', 'dominos', 'generators', 'inspector', 'context', 'project', 'options', 'setup']) this[k] = spec[k];
      /** Ce que la vue montre ou cache pour ce langage : { pioche: { hide: [catégories], order: [catégories] }, coach: false }. */
      this.ui = spec.ui || {};
      /** Les variables : portées nommées où chercher un nom court, variables dynamiques ({ scopes, dynamic }). */
      this.variables = spec.variables || null;
      /** Les sources de la boîte à outils dynamique : nom → (ctx) → entrées (domino.toolbox.js). */
      this.toolboxSources = spec.toolboxSources || {};
      /** La boîte à outils en JSON : catégories, sous-catégories, pierres, textes, aide, liens (domino.toolbox.js). */
      this.toolbox = spec.toolbox || null;
      /** Kits inclus (domino.kits.js) : des pierres prêtes à l'emploi, renommables. */
      this.kits = spec.kits || [];
      /** Le dialecte d'expressions du langage : les opérateurs de base, plus les siens (spec.expr.ops). */
      this.exprDialect = D.Expr ? (spec.expr && spec.expr.ops ? D.Expr.extend(spec.expr.ops) : D.Expr) : null;
      if (!this.context && spec.project && spec.project.context) this.context = spec.project.context;
    }

    _kits() { return this.kits.length && D.Kits ? D.Kits.resolve(this.kits) : { types: [], dominos: [] }; }
    createTypes() {
      const ts = new D.TypeSystem().defineAll(this.types || []);
      // Les types d'un kit ne remplacent pas ceux du langage (même nom : le langage l'emporte).
      for (const t of this._kits().types) if (!ts.has(t.name)) ts.define(t.name, t);
      return ts;
    }
    createRegistry(types = this.createTypes()) {
      const own = this.dominos || [];
      const fromKits = this._kits().dominos.filter((d) => !own.some((x) => x.type === d.type));
      const reg = new D.Registry(types, { semantics: this.semantics }).defineAll([...own, ...fromKits]);
      for (const e of this.edges) reg.defineEdge(e);
      return reg;
    }
    /** Un espace de travail vide pour ce langage (avec ses règles et ses modules). */
    createWorkspace(registry = this.createRegistry(), o = {}) {
      const ws = new D.Workspace({
        registry, types: registry.types, language: this, rules: this.rules, modules: this.modules,
        context: o.context !== undefined ? o.context : D.clone(this.context || {}),
        name: o.name || (this.project && this.project.name) || this.name,
      });
      ws.editorInfo = { id: this.id, name: this.name };
      for (const [type, fn] of Object.entries(this.events)) if (typeof fn === 'function') ws.on(type, (e) => fn(e, ws));
      return ws;
    }
    /** Sans vue : espace, exécution, générateurs ; le projet du langage est chargé (ou celui donné). */
    instantiate(project = this.project, o = {}) {
      const ws = this.createWorkspace(undefined, o);
      const report = project ? D.Serializer.load(ws, project) : { ok: true, errors: [], warnings: [] };
      const generators = (this.generators || []).map((g) => (typeof g === 'function' ? g(D) : g)).filter((g) => g && typeof g.forType === 'function');
      return { ws, runtime: new D.Runtime(ws), generators, report, generate: (name) => { const g = generators.find((x) => x.name === name) || generators[0]; return g ? g.generate(D.Serializer.toJSON(ws)) : ''; } };
    }

    /** Couleurs des façades d'une pierre selon le langage (genre, puis rôle). */
    facesFor(def, role) {
      const f = this.faces;
      if (!f) return null;
      return (def.kind && f.kinds && f.kinds[def.kind]) || (f.roles && f.roles[role]) || null;
    }
    /** Légende des façades : [{ label, left, right }]. */
    faceLegend() { return (this.faces && this.faces.legend) || []; }

    /**
     * Le langage en JSON : types, pierres (callbacks en texte s'ils ont été écrits en texte), règles, façades, modules.
     * Les callbacks écrits en JavaScript sont listés par leur nom (`callbacks`), pas leur code.
     */
    toJSON(registry = this.createRegistry()) {
      return D.compact({
        format: 'kantoaplo.language', version: 1,
        id: this.id, name: this.name, color: this.color, description: this.description,
        types: registry.types.toJSON().filter((t) => !t.builtin),
        rules: D.compact({ chain: typeof this.rules.chain === 'function' ? 'fonction' : this.rules.chain, wires: this.rules.wires, cycles: this.rules.cycles || undefined, list: this.rules.list.map((r) => D.compact({ id: r.id, on: r.on, description: r.description, when: r.when, if: r.if, message: r.message })) }),
        execution: this.execution || undefined,
        projections: this.projections || undefined,
        edges: this.edges.length ? this.edges.map((e) => D.compact({ type: e.type, name: e.name, description: e.description, color: e.color, dash: e.dash || undefined, fields: e.fields, label: typeof e.label === 'string' ? e.label : undefined, from: e.from, to: e.to, default: e.default || undefined })) : undefined,
        faces: this.faces || undefined,
        modules: this.modules || undefined,
        ui: Object.keys(this.ui).length ? this.ui : undefined,
        toolbox: this.toolbox || undefined,
        variables: this.variables ? D.compact({ scopes: this.variables.scopes, dynamic: this.variables.dynamic === true ? true : undefined }) : undefined,
        kits: this.kits.length ? this.kits.map((k) => (typeof k === 'string' ? k : D.compact({ id: k.id, only: k.only, patch: k.patch }))) : undefined,
        templates: (this.spec.templates || []).filter((t) => t.project && typeof t.project === 'object').map((t) => D.compact({ id: t.id, name: t.name, description: t.description, project: t.project })),
        // Les pierres des kits ne sont pas recopiées : la clé « kits » suffit à les retrouver.
        dominos: registry.toJSON().filter((d) => !/^(ctx\.|domino\.|decl\.|call$|await$)/.test(d.type) && !this._kits().dominos.some((k) => k.type === d.type && !(this.dominos || []).some((x) => x.type === d.type))),
      });
    }
  }

  /**
   * JSON Schema (2020-12) d'un langage : ce que le développeur peut écrire, clé par clé.
   * Les callbacks écrits en JavaScript sont des fonctions (hors JSON) ; écrits en texte, ils vont dans `code`.
   */
  const pip = {
    type: 'object', required: ['type'],
    properties: {
      name: { type: 'string' }, type: { type: 'string', description: 'Un type déclaré (sa couleur).' }, label: { type: 'string' },
      accepts: { type: 'array', items: { type: 'string' } }, required: { type: 'boolean', description: 'Entrée : faut-il l’alimenter ? (vrai par défaut)' },
      color: { type: 'string', description: 'Couleur imposée au point.' }, help: { type: 'string' },
      wire: { const: false, description: 'Ce point ne se relie pas par un fil.' }, multiple: { type: 'boolean', description: 'Entrée qui reçoit plusieurs fils (liste).' },
    },
  };
  const field = {
    type: 'object',
    properties: {
      kind: { enum: ['text', 'textarea', 'number', 'select', 'toggle', 'code', 'color', 'json', 'list', 'ref', 'expr', 'table'] },
      columns: { type: 'object', description: 'table : les colonnes, chacune un champ (text, number, toggle, select, expr, color).' },
      jump: { type: 'boolean', description: 'ref : un saut (l’exécution continue à la cible).' },
      label: { type: 'string' }, default: {}, options: { type: 'array', description: 'Valeurs possibles (ou une fonction de l’instance).' },
      bindable: { type: 'boolean', description: 'Peut se lier au contexte ({ $bind }).' }, help: { type: 'string' }, placeholder: { type: 'string' },
      required: { type: 'boolean' }, min: { type: 'number' }, max: { type: 'number' }, pattern: { type: 'string', description: 'Expression régulière (Unicode).' },
      to: { description: 'Renvoi : domino, partie, declaration, variable, ou des types de pierres.', anyOf: [{ type: 'string' }, { type: 'array', items: { type: 'string' } }] },
      unit: { type: 'string' }, group: { type: 'string' }, hidden: { type: 'boolean' }, readonly: { type: 'boolean' },
    },
  };
  const perms = { type: 'object', additionalProperties: { type: 'array', items: { type: 'string' } }, description: 'next, prev, top, bottom, wireIn, wireOut → types, genres, « ce que représente », ou « * ».' };
  Language.schema = {
    $schema: 'https://json-schema.org/draft/2020-12/schema',
    $id: 'https://kantoaplo.dev/schema/domino/language-1.json',
    title: 'Langage Zeugma',
    description: 'Ce qu’un éditeur instancie : types, pierres, sens des faces, règles, façades, modules.',
    type: 'object', required: ['id'],
    properties: {
      format: { const: 'kantoaplo.language' }, version: { const: 1 },
      id: { type: 'string' }, name: { type: 'string' }, color: { type: 'string' }, description: { type: 'string' },
      types: { type: 'array', items: { type: 'object', required: ['name', 'color'], properties: { name: { type: 'string' }, label: { type: 'string' }, color: { type: 'string' }, kind: { type: 'string', description: 'data (valeur), call (fonction), ou un genre propre au langage.' }, extends: { type: 'string' }, accepts: { type: 'array', items: { type: 'string' } }, description: { type: 'string' } } } },
      dominos: { type: 'array', items: { $ref: '#/$defs/domino' } },
      execution: { type: 'object', description: 'Le moteur d’exécution (sans moteur : l’effet domino).', properties: { engine: { enum: ['dataflow', 'statemachine', 'tokens', 'decision'] } } },
      projections: { type: 'object', description: 'Les vues du même modèle : dominos, diagram, grid, text.', properties: { default: { type: 'string' }, list: { type: 'array', items: { type: 'string' } } } },
      edges: { type: 'array', description: 'Genres de liens : des fils typés qui portent des champs (transition, relation, flux…).', items: { type: 'object', required: ['type'], properties: { type: { type: 'string' }, name: { type: 'string' }, description: { type: 'string' }, color: { type: 'string' }, dash: { type: 'boolean' }, fields: { type: 'object', additionalProperties: field }, label: { type: 'string', description: 'Gabarit affiché sur le fil : « {{event}} [{{guard}}] ».' }, from: { type: 'array', items: { type: 'string' } }, to: { type: 'array', items: { type: 'string' } }, default: { type: 'boolean' } } } },
      rules: { type: 'object', properties: { chain: { enum: ['types', 'count', 'both'] }, wires: { type: 'boolean' }, cycles: { type: 'boolean', description: 'Les fils peuvent boucler (machines à états, graphes).' }, list: { type: 'array', items: { type: 'object', required: ['id'], properties: { id: { type: 'string' }, on: { anyOf: [{ enum: ['next', 'top', 'bottom', 'wire'] }, { type: 'array' }] }, when: { type: 'string', description: 'Expression JavaScript : refus si vraie (q.parent, q.child, q.via, q.pip).' }, if: { description: 'Expression déclarative (texte ou JSON), sans code : refus si vraie (parent, child, via, pip).' }, message: { type: 'string' }, description: { type: 'string' } } } } } },
      faces: { type: 'object', properties: { kinds: { type: 'object' }, roles: { type: 'object' }, legend: { type: 'array' } } },
      modules: { description: 'true, false, ou { title, class, library, function, variable, faces } (chaque genre : false ou { name, uses, description }).' },
      ui: { type: 'object', description: '{ pioche: { hide, order }, toolboxTitle, coach }' },
      toolbox: { type: 'object', description: 'La boîte à outils (pioche) : { mode, rest, contents: [catégorie | pierre | groupe | texte | séparateur | dynamique] }. Schéma : toolbox.schema.json.' },
      variables: { type: 'object', description: 'Portées où chercher un nom court ({{token}} → local.token, env.token…) et variables dynamiques ({{$guid}}).', properties: { scopes: { type: 'array', items: { type: 'string' } }, dynamic: { type: 'boolean' } } },
      templates: { type: 'array', description: 'Modèles de projet proposés par « Fichier › Nouveau ▸ » (en plus du projet vide et de l’exemple).', items: { type: 'object', required: ['id', 'name'], properties: { id: { type: 'string' }, name: { type: 'string' }, description: { type: 'string' }, project: { type: 'object' } } } },
      contributes: { type: 'object', description: 'Contributions au studio : commands, menus, keybindings, displays, generators (fonctions : hors JSON).' },
      kits: { type: 'array', description: 'Kits de pierres inclus : « flow », « data »… ou { id, only, patch }.', items: { anyOf: [{ type: 'string' }, { type: 'object', required: ['id'], properties: { id: { type: 'string' }, only: { type: 'array', items: { type: 'string' } }, patch: { type: 'object' } } }] } },
      expr: { type: 'object', description: 'Le dialecte d’expressions du langage : { ops } (fonctions : hors JSON).' },
    },
    $defs: {
      pip, field,
      domino: {
        type: 'object', required: ['type'],
        properties: {
          type: { type: 'string' }, name: { type: 'string' }, category: { type: 'string' }, description: { type: 'string' }, help: { type: 'string' },
          kind: { type: 'string', description: 'Genre : façades et règles du langage s’y réfèrent.' },
          represents: { type: 'string', description: 'Ce que la pierre représente : variable, instruction, classe, module, projet, scénario, algorithme, idée…' },
          meaning: { type: 'object', properties: { left: { type: 'string' }, right: { type: 'string' }, zeroLeft: { type: 'string' }, zeroRight: { type: 'string' } } },
          left: { anyOf: [{ type: 'integer' }, { type: 'array', items: pip }] }, right: { anyOf: [{ type: 'integer' }, { type: 'array', items: pip }] },
          chain: { type: 'boolean', description: 'false : pierre libre, reliée par des fils seulement.' }, wires: { type: 'boolean' }, async: { type: 'boolean' },
          where: { type: 'array', items: { enum: ['main', 'body', 'component', 'declarations'] } },
          top: { anyOf: [{ const: false }, { type: 'object', properties: { max: { type: 'integer' }, accepts: { type: 'array', items: { type: 'string' } } } }] },
          bottom: { anyOf: [{ const: false }, { type: 'object', properties: { max: { type: 'integer' }, accepts: { type: 'array', items: { type: 'string' } } } }] },
          fields: { type: 'object', additionalProperties: field },
          inside: { anyOf: [{ type: 'boolean' }, { type: 'object', properties: { kind: { type: 'string' }, partie: { enum: ['component', 'body'] }, template: { type: 'array', description: 'Les pierres posées à la création (JSON de pierres).' }, title: { type: 'string' } } }] },
          constraints: { type: 'object', properties: { deletable: { type: 'boolean' }, movable: { type: 'boolean' }, editable: { type: 'boolean' }, duplicable: { type: 'boolean' }, max: { type: 'integer' }, maxPerPartie: { type: 'integer' }, allow: perms, deny: perms } },
          faces: { type: 'object', properties: { left: { type: 'string' }, right: { type: 'string' } } },
          tint: { type: 'string' }, identity: { type: 'string' }, tags: { type: 'array', items: { type: 'string' } }, hidden: { type: 'boolean' },
          display: { type: 'string', description: 'Mode d’affichage propre à la pierre : stone, compact, card, outline, ou un mode inscrit.' },
          traits: { type: 'array', description: 'Traits composés : « nommé », « état », { id: "état", final: true }…', items: { anyOf: [{ type: 'string' }, { type: 'object', required: ['id'] }] } },
          behaviour: { type: 'object', description: 'Comportement déclaré, sans code : title (gabarit), validate, faces, pips (each), canConnect, run (set, log, wait, jump, out).' },
          roles: { type: 'object', description: 'Rôles sémantiques lus par les moteurs d’exécution (state, flow, decision…).' },
          notation: { type: 'object', description: 'Comment la pierre se dessine dans chaque projection (diagram : shape, label…).' },
          version: { type: 'string' }, deprecated: { type: 'string' }, examples: { type: 'array' },
          code: { type: 'object', description: 'Callbacks écrits en texte : run, title, pips, validate, canConnect…', additionalProperties: { type: 'string' } },
        },
      },
    },
  };

  D.Language = Language;
  /** Normalise un langage (objet, JSON, ou pack d'une version précédente). */
  D.language = (spec) => (spec instanceof Language ? spec : new Language(spec));
  /** Raccourci sans vue. */
  D.headless = (spec, project, o) => D.language(spec).instantiate(project, o);
})(typeof globalThis !== 'undefined' ? globalThis : window);
