/*!
 * Zeugma · kits : des pierres prêtes à l'emploi, pour tous les langages
 *
 * Un kit est un petit ensemble de types et de pierres qu'un langage inclut d'une ligne, et renomme
 * s'il le veut, au lieu de les réécrire :
 *
 *   Domino.language({ id: 'quiz', kits: ['flow', { id: 'data', patch: { 'data.map': { name: 'Composer' } } }], … })
 *
 * Kits livrés :
 *   flow   flow.switch « Aiguillage » : N cas (un tableau), une sortie par cas, plus « sinon » ;
 *          flow.set « Retenir » : écrit une valeur calculée dans l'objet qui passe (ou le contexte).
 *   data   data.json « Données », data.filter « Filtrer », data.map « Transformer », data.sort « Trier »,
 *          data.take « Garder les premiers » : des listes d'objets, traitées par des expressions
 *          déclaratives (domino.expr.js). Utiles dans le corps d'une méthode : une classe qui rend du JSON.
 *
 *   Domino.Kits.register('monKit', { types: [...], dominos: [...] });   // un kit à soi
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const kits = new Map();
  const E = () => D.Expr;
  /** Lit une expression stockée (JSON) ou écrite en texte. */
  const exprOf = (v) => (typeof v === 'string' ? E().read(v).expr : v);

  const Kits = {
    /** @param {string} id @param {{ types?: object[], dominos: object[], description?: string }} kit */
    register(id, kit) { kits.set(id, { id, types: [], dominos: [], ...kit }); return () => kits.delete(id); },
    get(id) { return kits.get(id) || null; },
    list() { return [...kits.values()]; },
    /**
     * Les types et les pierres des kits demandés : 'flow' ou { id, only?: [types], patch?: { type: { name, category, … } } }.
     * @returns {{ types: object[], dominos: object[] }}
     */
    resolve(list = []) {
      const types = [], dominos = [];
      for (const entry of [].concat(list)) {
        const ref = typeof entry === 'string' ? { id: entry } : entry;
        const kit = kits.get(ref.id);
        if (!kit) throw new D.DominoError('kit.unknown', `Kit inconnu : « ${ref.id} » (connus : ${[...kits.keys()].join(', ')}).`);
        for (const t of kit.types) if (!types.some((x) => x.name === t.name)) types.push(t);
        for (const d of kit.dominos) {
          if (ref.only && !ref.only.includes(d.type)) continue;
          dominos.push({ ...d, ...((ref.patch || {})[d.type] || {}) });
        }
      }
      return { types, dominos };
    },
  };

  // ---------------------------------------------------------------------------
  // Kit « flow » : aiguillage à N cas
  // ---------------------------------------------------------------------------
  /** Les cas d'un aiguillage : [{ label, value, when }] (when : une expression ; sinon value comparée au sujet). */
  const casesOf = (raw) => (Array.isArray(raw) ? raw : []).map((c, i) => ({ label: String((c && c.label) || (c && c.value) || `cas ${i + 1}`), value: c ? c.value : undefined, when: c && c.when ? exprOf(c.when) : null }));
  Kits.register('flow', {
    description: 'Contrôle : aiguillage à N cas, valeur retenue.',
    dominos: [
      {
        type: 'flow.switch', name: 'Aiguillage', category: 'Embranchements', represents: 'condition', kind: 'aiguillage',
        description: 'Selon (switch / case) : un sujet calculé, une sortie par cas (sa valeur, ou sa propre condition), plus « sinon ». La première qui convient l’emporte.',
        meaning: { left: 'ce qui passe', right: 'une sortie par cas, puis « sinon »' },
        left: [{ name: 'entrée', type: 'any' }], right: [{ name: 'sinon', type: 'any' }],
        top: false,
        fields: {
          on: { kind: 'expr', label: 'Selon', default: { var: 'value' }, help: 'Le sujet comparé à la valeur de chaque cas (une expression : réponses.domaine, score…).' },
          cases: {
            kind: 'table', label: 'Cas', default: [{ label: 'A', value: 'A' }, { label: 'B', value: 'B' }],
            columns: { label: { kind: 'text', label: 'Sortie', width: 0.8 }, value: { kind: 'text', label: 'Si le sujet vaut' }, when: { kind: 'expr', label: 'ou si (condition)', width: 1.4 } },
          },
          fallback: { kind: 'text', label: 'Nom de « sinon »', default: 'sinon', bindable: false },
        },
        // Une sortie par cas, plus « sinon » : la face de sortie compte les chemins.
        pips: (api) => ({ right: [...casesOf(api.raw('cases')).map((c) => ({ name: c.label, type: 'any' })), { name: api.raw('fallback') || 'sinon', type: 'any' }] }),
        title: (api) => { const on = exprOf(api.raw('on')); return `selon ${on == null ? '?' : E().text(on)}`; },
        validate: (api) => {
          const out = [], cs = casesOf(api.raw('cases'));
          if (!cs.length) out.push({ level: 'warn', code: 'switch.empty', message: 'Aucun cas : tout passe par « sinon ».' });
          const labels = cs.map((c) => c.label);
          const dup = labels.find((l, i) => labels.indexOf(l) !== i);
          if (dup) out.push({ level: 'warn', code: 'switch.dup', message: `Deux cas s’appellent « ${dup} ».` });
          return out;
        },
        run: (rc) => {
          const cs = casesOf(rc.fields.cases);
          const subject = rc.expr(exprOf(rc.fields.on));
          let k = cs.findIndex((c) => (c.when ? E().truthy(rc.expr(c.when, { subject })) : E().same(c.value, subject)));
          if (k < 0) k = cs.length;
          rc.log('info', `selon ${JSON.stringify(subject)} → ${k < cs.length ? cs[k].label : rc.fields.fallback || 'sinon'}`);
          return [...cs.map((_, i) => (i === k ? rc.inputs[0] : undefined)), k === cs.length ? rc.inputs[0] : undefined];
        },
      },
      {
        type: 'flow.set', name: 'Retenir', category: 'Embranchements', represents: 'état', kind: 'état',
        description: 'Calcule une valeur (une expression) et la retient : dans l’objet qui passe (clé), ou dans le contexte (« contexte.chemin »). Puis laisse passer.',
        left: [{ name: 'entrée', type: 'any' }], right: [{ name: 'sortie', type: 'any' }],
        fields: { key: { kind: 'text', label: 'Retenir sous', default: 'vars.x', bindable: false }, value: { kind: 'expr', label: 'Valeur', default: 1 } },
        title: (api) => `${api.raw('key')} ← ${E().text(exprOf(api.raw('value')))}`,
        run: (rc) => {
          const v = rc.expr(exprOf(rc.fields.value)), key = String(rc.fields.key || '');
          if (key.startsWith('contexte.')) { rc.ctx.set(key.slice(9), v); return [rc.inputs[0]]; }
          const input = D.isPlainObject(rc.inputs[0]) ? D.clone(rc.inputs[0]) : {};
          const parts = key.split('.');
          let cur = input;
          parts.slice(0, -1).forEach((p) => { cur = cur[p] = D.isPlainObject(cur[p]) ? cur[p] : {}; });
          cur[parts[parts.length - 1]] = v;
          return [input];
        },
      },
    ],
  });

  // ---------------------------------------------------------------------------
  // Kit « data » : des listes d'objets, traitées par des expressions
  // ---------------------------------------------------------------------------
  const listIn = { name: 'liste', type: 'liste' };
  const argIn = { name: 'argument', type: 'any', required: false };
  /** La portée d'une expression appliquée à un élément : item, index, arg (2e entrée), args (paramètres de la méthode), self. */
  const itemScope = (rc, item, index) => ({ item, index, arg: rc.inputs[1] !== undefined ? rc.inputs[1] : rc.args && rc.args[0], args: rc.args });
  Kits.register('data', {
    description: 'Données : listes d’objets, filtrées, transformées, triées par des expressions.',
    types: [{ name: 'liste', label: 'Liste', color: '#13A3A0', description: 'Une liste de valeurs ou d’objets (JSON).' }],
    dominos: [
      {
        type: 'data.json', name: 'Données', category: 'Données', represents: 'donnée', kind: 'donnée',
        description: 'Une valeur JSON (souvent une liste d’objets). En adjacente haute, elle alimente l’entrée « liste ».',
        right: [{ name: 'liste', type: 'liste' }],
        fields: { value: { kind: 'json', label: 'JSON', default: [{ nom: 'a' }, { nom: 'b' }], bindable: false } },
        title: (api) => { const v = api.raw('value'); return Array.isArray(v) ? `données · ${v.length}` : 'données'; },
        run: (rc) => [D.clone(rc.fields.value)],
      },
      {
        type: 'data.filter', name: 'Filtrer', category: 'Données', represents: 'expression',
        description: 'Garde les éléments pour lesquels la condition est vraie. Portée : item, index, arg (la 2e entrée, ou le 1er paramètre de la méthode).',
        left: [listIn, argIn], right: [{ name: 'liste', type: 'liste' }],
        fields: { where: { kind: 'expr', label: 'Garder si', default: { eq: [{ var: 'item.type' }, { var: 'arg' }] } } },
        title: (api) => `garder si ${E().text(exprOf(api.raw('where')))}`,
        run: (rc) => { const w = exprOf(rc.fields.where); return [(Array.isArray(rc.inputs[0]) ? rc.inputs[0] : []).filter((item, i) => E().truthy(rc.expr(w, itemScope(rc, item, i))))]; },
      },
      {
        type: 'data.map', name: 'Transformer', category: 'Données', represents: 'expression',
        description: 'Transforme chaque élément par une expression (souvent un objet : { "object": { … } }). Portée : item, index, arg, args.',
        left: [listIn, argIn], right: [{ name: 'liste', type: 'liste' }],
        fields: { to: { kind: 'expr', label: 'Devient', default: { var: 'item' } } },
        title: (api) => `→ ${E().text(exprOf(api.raw('to')))}`,
        run: (rc) => { const t = exprOf(rc.fields.to); return [(Array.isArray(rc.inputs[0]) ? rc.inputs[0] : []).map((item, i) => rc.expr(t, itemScope(rc, item, i)))]; },
      },
      {
        type: 'data.sort', name: 'Trier', category: 'Données', represents: 'expression',
        description: 'Trie par une clé calculée (expression), croissant ou décroissant.',
        left: [listIn], right: [{ name: 'liste', type: 'liste' }],
        fields: { by: { kind: 'expr', label: 'Par', default: { var: 'item' } }, desc: { kind: 'toggle', label: 'Décroissant', default: false, bindable: false } },
        title: (api) => `trier par ${E().text(exprOf(api.raw('by')))}${api.raw('desc') ? ' ↓' : ''}`,
        run: (rc) => {
          const by = exprOf(rc.fields.by), xs = (Array.isArray(rc.inputs[0]) ? rc.inputs[0] : []).map((item, i) => ({ item, k: rc.expr(by, itemScope(rc, item, i)) }));
          xs.sort((a, b) => (a.k > b.k ? 1 : a.k < b.k ? -1 : 0) * (rc.fields.desc ? -1 : 1));
          return [xs.map((x) => x.item)];
        },
      },
      {
        type: 'data.take', name: 'Garder les premiers', category: 'Données', represents: 'expression',
        description: 'Garde les N premiers éléments.',
        left: [listIn], right: [{ name: 'liste', type: 'liste' }],
        fields: { n: { kind: 'number', label: 'Combien', default: 3, min: 0, bindable: false } },
        title: (api) => `les ${api.raw('n')} premiers`,
        run: (rc) => [(Array.isArray(rc.inputs[0]) ? rc.inputs[0] : []).slice(0, Math.max(0, Number(rc.fields.n) || 0))],
      },
    ],
  });

  D.Kits = Kits;
})(typeof globalThis !== 'undefined' ? globalThis : window);
