/*!
 * Zeugma · exécution (effet domino)
 *
 * Les chaînes, c'est l'ordre ; les fils, ce sont les valeurs et les appels.
 *
 *  - Toutes les chaînes d'une partie tombent ensemble. Dans une chaîne, chaque pierre tombe quand la
 *    précédente lui donne sa valeur : adjacentes hautes, fils entrants, la pierre, adjacentes basses, la suite.
 *    Une sortie `undefined` ne tombe pas : c'est ainsi qu'une condition choisit sa branche.
 *  - Une sortie qui est une promesse (un résultat qui arrivera plus tard) fait tomber sa branche à son arrivée,
 *    sans retenir le reste : c'est l'appel non bloquant.
 *  - Un fil lit la valeur de sa source. Une source libre (valeur, instance, calcul sans chaîne) est évaluée à la
 *    demande, une seule fois. Une source dans une chaîne est attendue jusqu'à ce qu'elle tombe.
 *  - Un fil qui arrive sur une pierre libre la déclenche (et sa chaîne, si elle en a une) quand toutes ses
 *    entrées poussées sont là. Bloquant : la chaîne qui pousse attend la fin ; non bloquant : elle continue.
 *  - Appeler la méthode d'une instance exécute la chaîne de cette méthode dans le corps de la déclaration,
 *    avec sa propre portée et l'instance (this).
 *  - Si toutes les chaînes attendent une valeur qui ne viendra jamais, l'exécution s'arrête et le dit.
 *
 * Callback `run(rc)` d'une définition :
 *   rc.inputs        valeurs des entrées (tableau, dans l'ordre des points)
 *   rc.in.<nom>      les mêmes, par nom de point
 *   rc.fields        champs, liaisons et gabarits résolus
 *   rc.ctx           contexte de l'exécution (lecture, écriture)
 *   rc.log(level, …) console de l'inspecteur
 *   rc.call(j, …args) appelle la fonction reçue sur l'entrée j (bloquant ou non selon son fil)
 *   rc.wireInto(j)   le fil qui alimente l'entrée j
 *   rc.self, rc.args dans le corps d'une déclaration : l'instance (this) et les paramètres de l'appel
 *   rc.sleep(ms)     attendre (pour les pierres asynchrones)
 *   rc.runPartie()   exécute la sous-partie d'une pierre conteneur, rend ses résultats
 *   rc.jump(cible, v) saut : l'exécution continue à la pierre visée (même partie), avec la valeur v ;
 *                    rend false si les passages permis sont épuisés (option { max })
 *   rc.expr(e, portée) évalue une expression déclarative (domino.expr.js, dialecte du langage) ; la portée
 *                    par défaut : la valeur reçue (value, et ses clés si c'est un objet), le contexte (ctx), args, self
 *   rc.report(genre, { status, summary, ms, details }) ajoute une entrée au rapport de l'exécution (res.reports,
 *                    événement run:report) : ce qu'un testeur veut lire (requête, réponse, vérification, variable…).
 *                    status : 'ok' | 'fail' | 'error' | 'skip' | 'info'. L'inspecteur (onglet Rapport) et la vue
 *                    « Déroulé » les montrent ; un gabarit « report.<genre> » (Domino.Templates) en dessine le détail.
 *   rc.rootCtx       le contexte de toute l'exécution (une sous-partie a sa propre portée, rc.ctx)
 *
 * Options de run() : partie, from (l'identifiant d'une pierre : seule sa chaîne tombe), delay, context, silent,
 * signal, maxSteps, idle. Un langage dont execution.chains vaut 'sequential' fait tomber les chaînes d'une partie
 * l'une après l'autre (de haut en bas), au lieu de toutes ensemble : une campagne de tests, un script.
 * Rend un tableau de sorties, un objet { nomDeSortie: valeur }, ou une seule valeur (première sortie).
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const isThenable = (v) => v != null && typeof v.then === 'function';
  const ENTRIES = new Set(['decl.ctor', 'decl.method', 'decl.params']);

  /** Une portée d'exécution : la partie principale, une sous-partie, ou l'appel d'une méthode. */
  class Frame {
    constructor(o) {
      this.partie = o.partie;
      this.ctx = o.ctx;
      this.label = o.label || o.partie;
      this.parent = o.parent || null;
      /** Le chemin d'appel : partie principale › méthode › … */
      this.path = this.parent ? [...this.parent.path, this.label] : [this.label];
      /** Étape qui a fait tomber chaque pierre (causalité). */
      this.stepOf = new Map();
      this.self = o.self || null;
      this.args = o.args || [];
      this.partieInputs = o.partieInputs || [];
      this.results = {};
      this.result = undefined;
      this.returned = false;
      this.last = undefined;
      /** Sorties des pierres déjà tombées. */
      this.out = new Map();
      /** Évaluations à la demande en cours (une seule fois par pierre). */
      this.lazy = new Map();
      /** Pierres qui attendent qu'une autre tombe. */
      this.waiters = new Map();
      /** Valeurs poussées par des fils vers des pierres libres. */
      this.inbox = new Map();
    }
  }

  class Runtime {
    constructor(ws) { this.ws = ws; this.running = false; }

    /**
     * @param {{ partie?: string, delay?: number, context?: object, silent?: boolean, signal?: AbortSignal, maxSteps?: number, idle?: number }} o
     * @returns {Promise<{ ok: boolean, trace: object[], stoppedAt: string|null, error: string|null, ms: number, context: object, instances: object[] }>}
     */
    async run(o = {}) {
      const ws = this.ws;
      // Un langage à moteur (machine à états, jetons, décision) s'exécute par ce moteur ; la trace garde la même forme.
      if (D.Engines && D.Engines.of(ws) && !o.dataflow) return D.Engines.run(this, o);
      // « from » : seule la chaîne de cette pierre tombe (dans sa partie).
      const fromNode = o.from ? ws.get(o.from) : null;
      const partie = fromNode ? fromNode.partie : o.partie || 'main';
      // Une exécution « à blanc » écrit dans sa propre portée et ne prévient personne.
      const ctx = o.context || o.silent ? ws.context.child('exécution', o.context || {}, { bubble: !o.silent }) : ws.context;
      const run = {
        trace: [], stoppedAt: null, error: null, steps: 0, maxSteps: o.maxSteps || Math.max(4000, ws.nodes.size * 4), delay: o.delay || 0, signal: o.signal,
        t0: now(), silent: !!o.silent, tasks: 0, blocked: 0, background: new Set(), waiters: new Set(), instances: [], calls: 0, progress: 0, sleeping: 0,
        seq: 0, vars: new Map(), id: `r${Date.now().toString(36)}`, startedAt: new Date().toISOString(),
        jumps: new Map(), jumpCount: 0, maxJumps: o.maxJumps || 1000,
        reports: [], reportSeq: 0, only: fromNode ? ws.rootOf(fromNode).id : null,
        sequential: !!(ws.language && ws.language.execution && ws.language.execution.chains === 'sequential'),
      };
      if (!run.silent) {
        this.running = true;
        for (const n of ws.nodes.values()) { delete n.state.runError; n.state.lastRun = null; delete n.state.tint; delete n.state.report; }
        ws.emit('run:start', { type: 'run:start', partie, at: Date.now() });
      }
      const frame = new Frame({ partie, ctx, label: (ws.parties.get(partie) || {}).name || partie });
      run.root = frame;
      // Filet de sécurité : sans progrès pendant `idle` ms alors que des pierres attendent, on arrête.
      let lastProgress = -1, still = 0;
      const idle = o.idle || 4000;
      const dog = setInterval(() => {
        if (run.progress !== lastProgress || run.sleeping) { lastProgress = run.progress; still = 0; return; }
        if (run.waiters.size && (still += 500) >= idle) this._release(run, new Error('attente sans fin : une pierre attend une valeur qui ne vient pas.'));
      }, 500);
      if (dog.unref) dog.unref();
      try {
        await this._task(run, () => this._partie(run, frame, partie, [], 0));
        while (run.background.size) await Promise.allSettled([...run.background]);
      } catch (err) {
        if (!run.error) run.error = err && err.message ? err.message : String(err);
      } finally { clearInterval(dog); }
      const vars = {};
      for (const [id, v] of run.vars) { const d = ws.get(id); vars[d ? d.fields.name : id] = v; }
      const res = { id: run.id, startedAt: run.startedAt, ok: !run.error, reports: run.reports, trace: run.trace, stoppedAt: run.stoppedAt, error: run.error, ms: Math.round(now() - run.t0), context: ctx, instances: run.instances, calls: run.calls, variables: vars, jumps: run.jumpCount };
      if (run.silent) return res;
      this.running = false;
      this.last = res;
      ws.emit('run:end', { type: 'run:end', ok: res.ok, stoppedAt: res.stoppedAt, error: res.error, ms: res.ms, steps: run.trace.length, reports: run.reports.length, at: Date.now() });
      return res;
    }

    // -------------------------------------------------------------------------
    // Tâches : compter qui travaille et qui attend, pour reconnaître une attente sans fin.
    // -------------------------------------------------------------------------
    async _task(run, fn) {
      run.tasks++;
      try { return await fn(); } finally { run.tasks--; this._deadlock(run); }
    }
    /** Une tâche de fond (branche non bloquante) : l'exécution ne se termine qu'à sa fin. */
    _spawn(run, fn) {
      const p = this._task(run, fn).catch((err) => { this._fail(run, null, err); });
      run.background.add(p);
      p.finally(() => run.background.delete(p));
      return p;
    }
    /** Suivre une promesse lancée sans être attendue (son erreur arrête l'exécution, sa fin est attendue). */
    _track(run, p) {
      const q = Promise.resolve(p).catch((err) => { this._fail(run, null, err); });
      run.background.add(q);
      q.finally(() => run.background.delete(q));
    }
    _deadlock(run) {
      if (run.waiters.size && run.blocked > 0 && run.blocked >= run.tasks) this._release(run, new Error('attente sans fin : chaque chaîne attend une valeur qu’aucune autre ne donnera.'));
    }
    _release(run, err) {
      for (const w of [...run.waiters]) { run.waiters.delete(w); w.reject(err); }
    }
    _fail(run, n, err) {
      if (run.error) return;
      run.error = n ? `« ${this.ws.titleOf(n)} » : ${err && err.message ? err.message : err}` : (err && err.message ? err.message : String(err));
      if (n) run.stoppedAt = n.id;
      if (!run.silent) this.ws.log('error', run.error, n ? { dominoId: n.id } : {});
    }
    /** Attendre qu'une pierre tombe dans une portée. */
    _waitFor(run, frame, id) {
      const p = new Promise((resolve, reject) => {
        const entry = { resolve, reject, id };
        if (!frame.waiters.has(id)) frame.waiters.set(id, []);
        frame.waiters.get(id).push(entry);
        run.waiters.add(entry);
      });
      run.blocked++;
      this._deadlock(run);
      return p.finally(() => { run.blocked--; });
    }
    _produced(run, frame, id, outputs) {
      frame.out.set(id, outputs);
      run.progress++;
      for (const w of frame.waiters.get(id) || []) { run.waiters.delete(w); w.resolve(outputs); }
      frame.waiters.delete(id);
    }

    // -------------------------------------------------------------------------
    // Parties et chaînes
    // -------------------------------------------------------------------------
    /** Une pierre libre qui ne tombe que si on la lit : instance, valeur, ou calcul dont toutes les entrées se lisent. */
    _isLazy(n, guard = 0) {
      const ws = this.ws;
      if (n.parent || n.next.some(Boolean) || guard > 32) return false;
      if (n.def.instanceOf) return true;
      const left = ws.pipsOf(n).left, fed = ws.feedersOf(n);
      if (!left.length) return ws.wiresFrom(n.id).length > 0;
      return left.every((q, j) => (fed[j] ? fed[j].via === 'top' || (fed[j].via === 'wire' && this._isLazy(fed[j].node, guard + 1)) : q.required === false));
    }
    async _partie(run, frame, partie, inputs, depth, cause = { via: 'start' }) {
      const ws = this.ws;
      const starts = [];
      for (const h of ws.roots(partie)) {
        if (run.error) break;
        const def = h.def;
        if (def.kind === 'declaration' || ENTRIES.has(h.type)) continue;
        if (this._isLazy(h)) continue;
        if (run.only && depth === 0 && h.id !== run.only) continue;
        const left = ws.pipsOf(h).left, fed = ws.feedersOf(h);
        // Déclenchée par ses fils : elle tombera quand on lui poussera ses valeurs.
        if (left.some((_, j) => fed[j] && fed[j].via === 'wire')) continue;
        if (left.length && !inputs.length && !left.every((q, j) => (fed[j] && fed[j].via === 'top') || q.required === false)) {
          this._step(run, h, { status: 'skipped', depth, reason: 'aucune entrée' });
          continue;
        }
        starts.push(h);
      }
      if (run.sequential) {
        // L'une après l'autre, de haut en bas puis de gauche à droite.
        const at = (h) => h.position || { x: 0, y: 0 };
        starts.sort((a, b) => at(a).y - at(b).y || at(a).x - at(b).x);
        for (const h of starts) { if (run.error) break; await this._task(run, () => this._chain(run, frame, h, inputs, depth, cause)); }
      } else await Promise.all(starts.map((h) => this._task(run, () => this._chain(run, frame, h, inputs, depth, cause))));
      return frame.results;
    }

    async _chain(run, frame, n, incoming, depth, cause) {
      if (run.error) return;
      if (run.signal && run.signal.aborted) throw new Error('Exécution interrompue.');
      if (++run.steps > run.maxSteps) throw new Error(`Plus de ${run.maxSteps} étapes : exécution arrêtée.`);
      run.progress++;
      const pendingJumps = [];
      const outputs = await this._exec(run, frame, n, incoming, depth, 'chain', cause, pendingJumps);
      const me = frame.stepOf.get(n.id);
      if (!outputs || run.error) return;
      // Les sauts demandés par la pierre : l'exécution continue à leur cible.
      for (const j of pendingJumps) {
        if (run.error) return;
        if (run.delay) { run.sleeping++; await sleep(run.delay); run.sleeping--; }
        if (!run.silent) this.ws.emit('run:jump', { type: 'run:jump', from: n.id, to: j.target.id, at: Date.now() });
        await this._chain(run, frame, j.target, [j.value], depth + 1, { via: 'jump', step: me, from: n.id });
      }
      if (outputs[0] !== undefined && !isThenable(outputs[0])) frame.last = outputs[0];
      await this._push(run, frame, n, outputs, depth);
      const ws = this.ws;
      for (let i = 0; i < n.next.length; i++) {
        const l = n.next[i];
        if (!l || outputs[i] === undefined) continue;
        const c = ws.get(l.id);
        if (!c) continue;
        if (l.enabled === false) { this._step(run, c, { status: 'skipped', depth: depth + 1, reason: 'connexion désactivée', cause: { via: 'chain', step: me } }); continue; }
        const go = async (v) => {
          if (l.cond) {
            let pass;
            try { pass = !!evalCond(l.cond, v, frame.ctx); } catch (_) { pass = true; }
            if (!pass) { this._step(run, c, { status: 'skipped', depth: depth + 1, reason: `condition « ${l.cond} » fausse`, cause: { via: 'chain', step: me } }); return; }
          }
          const ins = [];
          (l.map || [0]).forEach((j) => { ins[j] = v; });
          if (run.delay) { run.sleeping++; await sleep(run.delay); run.sleeping--; }
          await this._chain(run, frame, c, ins, depth + 1, { via: 'chain', step: me, pip: i });
        };
        // Une valeur qui arrivera plus tard : sa branche tombera à son arrivée, sans retenir la suite.
        if (isThenable(outputs[i])) this._spawn(run, async () => go(await outputs[i]));
        else await go(outputs[i]);
        if (run.error) return;
      }
    }

    /** Les fils sortants : la valeur part vers chaque cible ; une pierre libre se déclenche. */
    async _push(run, frame, n, outputs, depth) {
      const ws = this.ws;
      for (const w of ws.wiresFrom(n.id)) {
        if (w.enabled === false || outputs[w.from.pip] === undefined) continue;
        const t = ws.get(w.to.id);
        if (!t) continue;
        const v = outputs[w.from.pip];
        this._wireEvent(run, w, v);
        if (t.parent || t.def.instanceOf) continue; // lue à la demande par la cible
        const box = frame.inbox.get(t.id) || new Map();
        frame.inbox.set(t.id, box);
        const fire = async () => {
          const val = isThenable(v) ? await v : v;
          box.set(w.to.pip, val);
          // Toutes les entrées poussées sont-elles là ? (les autres se lisent à la demande)
          const pushed = ws.wiresInto(t.id).filter((x) => x.enabled !== false && ws.get(x.from.id) && !this._isLazy(ws.get(x.from.id)));
          if (!pushed.every((x) => box.has(x.to.pip))) return;
          const ins = [];
          for (const [j, val2] of box) ins[j] = val2;
          frame.inbox.delete(t.id);
          await this._chain(run, frame, t, ins, depth + 1, { via: 'wire', wire: w.id, step: frame.stepOf.get(n.id) });
        };
        if (isThenable(v) || w.blocking === false) this._spawn(run, fire);
        else await this._task(run, fire);
        if (run.error) return;
      }
    }

    /** Lire la valeur d'un fil : déjà là, évaluée à la demande, ou attendue. */
    async _pull(run, frame, w, depth, step) {
      const ws = this.ws, src = ws.get(w.from.id);
      if (!src) return undefined;
      let outs = frame.out.get(src.id);
      if (!outs) {
        if (this._isLazy(src)) {
          if (!frame.lazy.has(src.id)) frame.lazy.set(src.id, this._exec(run, frame, src, [], depth, 'pull', { via: 'pull', wire: w.id, step }));
          outs = await frame.lazy.get(src.id);
        } else outs = await this._waitFor(run, frame, src.id);
      }
      const v = outs ? outs[w.from.pip] : undefined;
      this._wireEvent(run, w, v);
      return v;
    }
    _wireEvent(run, w, v) {
      if (run.silent) return;
      run.progress++;
      this.ws.emit('run:wire', { type: 'run:wire', wire: w.id, from: w.from.id, to: w.to.id, value: isThenable(v) ? '⏳' : v, at: Date.now() });
    }

    /** Exécute une pierre : adjacentes hautes, fils entrants, la pierre, adjacentes basses. Rend ses sorties (tableau) ou null si arrêt. */
    async _exec(run, frame, n, incoming, depth, as, cause, jumps = null) {
      const ws = this.ws;
      const { left, right } = ws.pipsOf(n);
      const inputs = left.map((_, j) => incoming[j]);
      const stepId = `s${++run.seq}`;
      frame.stepOf.set(n.id, stepId);
      // Neutralisée : elle laisse passer ses entrées, sans s'exécuter ni exécuter ses adjacentes.
      if (n.disabled) {
        const outputs = right.map((_, i) => (inputs[i] !== undefined ? inputs[i] : inputs[0]));
        this._step(run, n, { id: stepId, cause, status: 'disabled', depth, inputs: inputs.map(show), outputs: outputs.map(show), as, frame: frame.parent ? frame.label : undefined, path: frame.path });
        this._produced(run, frame, n.id, outputs);
        return outputs;
      }
      // 1. Les adjacentes hautes alimentent leurs entrées.
      for (const a of n.top) {
        const c = ws.get(a.id);
        if (!c) continue;
        const out = await this._exec(run, frame, c, [], depth, 'top', { via: 'top', step: stepId, pip: a.pip });
        if (!out) return null;
        const ident = ws.pipsOf(c).right.length ? out[0] : (out[0] !== undefined ? out[0] : frame.ctx.resolve(c.fields.value));
        inputs[a.pip] = ident;
      }
      // 2. Les fils entrants : la valeur de leur source.
      for (let j = 0; j < left.length; j++) {
        if (inputs[j] !== undefined) continue;
        const ins = ws.wiresInto(n.id, j).filter((w) => w.enabled !== false);
        if (!ins.length) continue;
        try {
          inputs[j] = left[j].multiple ? await Promise.all(ins.map((w) => this._pull(run, frame, w, depth, stepId))) : await this._pull(run, frame, ins[0], depth, stepId);
        } catch (err) { this._fail(run, n, err); this._step(run, n, { id: stepId, cause, status: 'error', depth, error: err.message, as }); return null; }
        if (run.error) return null;
      }
      // 3. La pierre.
      const def = n.def;
      const fields = frame.ctx.resolve(n.fields);
      const t0 = now();
      let raw, status = 'ok', error = null;
      const rc = {
        domino: { id: n.id, type: n.type, title: ws.titleOf(n), fields },
        node: n, inputs, silent: run.silent, frame, self: frame.self, args: frame.args, step: stepId,
        /** Variables du programme (déclarées) : lues et écrites par leur identifiant. */
        vars: {
          get: (id) => { if (!run.vars.has(id)) { const d = ws.get(id); run.vars.set(id, d ? D.clone(frame.ctx.resolve(d.fields.initial)) : undefined); } return run.vars.get(id); },
          set: (id, v) => { run.vars.set(id, v); const d = ws.get(id); if (!run.silent) ws.emit('run:var', { type: 'run:var', id, name: d ? d.fields.name : id, value: show(v), at: Date.now() }); },
        },
        in: Object.fromEntries(left.map((q, j) => [q.name, inputs[j]])),
        fields, ctx: frame.ctx, results: frame.results,
        partieInputs: frame.partieInputs,
        log: (level, ...msg) => (run.silent ? null : ws.log(level, msg.map((m) => (typeof m === 'object' ? safeJSON(m) : String(m))).join(' '), { dominoId: n.id })),
        api: ws.api(n),
        rootCtx: run.root.ctx,
        report: (kind, data = {}) => {
          const entry = D.compact({
            id: `${stepId}.${++run.reportSeq}`, kind: String(kind), step: stepId, dominoId: n.id, title: ws.titleOf(n), path: frame.path,
            at: Date.now(), status: data.status || 'info', summary: data.summary || '', ms: data.ms, details: data.details,
          });
          run.reports.push(entry);
          if (!run.silent) { n.state.report = entry; ws.emit('run:report', { type: 'run:report', entry, at: entry.at }); }
          return entry;
        },
        sleep: async (ms) => { run.sleeping++; try { await sleep(ms); } finally { run.sleeping--; run.progress++; } },
        wireInto: (j) => ws.wiresInto(n.id, j)[0] || null,
        call: async (j, ...args) => {
          const fn = inputs[j];
          if (!fn || typeof fn.call !== 'function') throw new Error(`l’entrée « ${(left[j] || {}).name || j} » ne reçoit pas de fonction.`);
          const w = ws.wiresInto(n.id, j)[0];
          const p = fn.call(args, { via: 'call', step: rc.step, wire: w && w.id });
          if (w && w.blocking === false) { this._track(run, p); return undefined; }
          return await p;
        },
        invoke: (declId, member, self, args) => this.invoke(run, frame, declId, member, self, args, depth, { via: 'call', step: stepId }),
        newInstance: (declId, args) => this._construct(run, frame, declId, args, n, depth),
        callable: (declId, member, self, async) => this._callable(run, frame, declId, member, self, async),
        jump: (target, value, { max = 100 } = {}) => {
          const id = target && typeof target === 'object' ? target.$ref : target;
          const t = id && ws.get(id);
          if (!t) throw new Error(`saut : la cible « ${id || '?'} » n’existe pas.`);
          if (t.partie !== n.partie) throw new Error(`saut : « ${ws.titleOf(t)} » est dans une autre partie.`);
          if (!jumps) throw new Error('un saut ne part que d’une pierre de chaîne.');
          const count = (run.jumps.get(n.id) || 0) + 1;
          if (count > Math.max(1, Number(max) || 1)) return false;
          if (++run.jumpCount > run.maxJumps) throw new Error(`plus de ${run.maxJumps} sauts : boucle arrêtée.`);
          run.jumps.set(n.id, count);
          jumps.push({ target: t, value });
          return true;
        },
        expr: (e, scope) => {
          const E = (ws.language && ws.language.exprDialect) || D.Expr;
          const v = inputs[0];
          const base = { ...(D.isPlainObject(v) ? v : {}), value: v, ctx: frame.ctx.merged ? frame.ctx.merged() : {}, args: frame.args, self: frame.self ? frame.self.props : undefined };
          return E.evaluate(e, scope ? { ...base, ...scope } : base);
        },
        /** Exécute la sous-partie de la pierre (ou, avec { partie }, celle d'une autre pierre conteneur : un scénario réutilisé). */
        runPartie: async (inputsForPartie = inputs, { partie: other } = {}) => {
          const owner = other ? ws.get(other) : n;
          if (!owner || !ws.parties.has(owner.id)) throw new Error(`la partie « ${other} » n’existe pas.`);
          if (frame.path.length > 32) throw new Error('trop d’appels imbriqués (une partie s’appelle elle-même ?).');
          const sub = new Frame({ partie: owner.id, ctx: frame.ctx.child(ws.titleOf(owner)), label: ws.titleOf(owner), parent: frame, partieInputs: inputsForPartie, self: frame.self, args: frame.args });
          if (!run.silent) ws.emit('run:enter', { type: 'run:enter', dominoId: owner.id, at: Date.now() });
          await this._partie(run, sub, owner.id, inputsForPartie, depth + 1, { via: 'inside', step: stepId });
          if (!run.silent) ws.emit('run:leave', { type: 'run:leave', dominoId: owner.id, at: Date.now() });
          return sub.results;
        },
      };
      try {
        if (def.hooks.run) raw = await def.hooks.run(rc);
        else if (def.container) { const sub = await rc.runPartie(); raw = right.map((q) => (q.name in sub ? sub[q.name] : Object.values(sub)[0] ?? inputs[0])); }
        else raw = right.map((_, i) => (inputs[i] !== undefined ? inputs[i] : inputs[0]));
      } catch (err) { status = 'error'; error = err && err.message ? err.message : String(err); }
      const outputs = status === 'ok' ? normOutputs(raw, right) : [];
      // Une sortie sans valeur ne fait rien tomber, mais une source sans sortie reste valide.
      if (as === 'top' && !right.length && status === 'ok') outputs[0] = raw !== undefined && !Array.isArray(raw) ? raw : (raw && raw[0]);
      // Une promesse lancée et non attendue : l'exécution attendra sa fin.
      outputs.forEach((v) => { if (isThenable(v)) this._track(run, v); });
      const ms = Math.round((now() - t0) * 100) / 100;
      if (!run.silent) {
        n.state.lastRun = { status, inputs: inputs.map(show), outputs: outputs.map(show), ms, error, at: Date.now(), frame: frame.parent ? frame.label : undefined };
        if (error) n.state.runError = error;
      }
      this._step(run, n, { id: stepId, cause, status, depth, inputs: inputs.map(show), outputs: outputs.map(show), ms, error, as, frame: frame.parent ? frame.label : undefined, path: frame.path });
      if (status === 'error') {
        this._fail(run, n, error);
        this._produced(run, frame, n.id, []);
        return null;
      }
      this._produced(run, frame, n.id, outputs);
      // 4. Les adjacentes basses reçoivent la sortie qu'elles consomment (plus tard si elle arrive plus tard).
      for (const a of n.bottom) {
        const c = ws.get(a.id);
        const v = outputs[a.pip];
        if (!c || v === undefined) continue;
        if (isThenable(v)) { this._spawn(run, async () => { await this._exec(run, frame, c, [await v], depth, 'bottom', { via: 'bottom', step: stepId }); }); continue; }
        const r = await this._exec(run, frame, c, [v], depth, 'bottom', { via: 'bottom', step: stepId });
        if (!r) return null;
      }
      return outputs;
    }

    // -------------------------------------------------------------------------
    // Modules : instances, appels de méthodes et de fonctions déclarées
    // -------------------------------------------------------------------------
    /**
     * Appelle un membre d'une déclaration : '#ctor' (constructeur), '#fn' (fonction déclarée) ou le nom d'une méthode.
     * La chaîne du membre tombe dans le corps de la déclaration, dans sa propre portée. Rend la valeur de « Retour »,
     * ou la dernière valeur de la chaîne.
     */
    async invoke(run, frame, declId, member, self, args, depth = 0, cause = { via: 'call' }) {
      const ws = this.ws, mods = ws.modules;
      const decl = ws.get(declId);
      if (!mods || !decl) throw new Error(`déclaration « ${declId} » introuvable.`);
      const entry = mods.entry(declId, member);
      const sig = mods.signature(decl);
      const name = member === '#ctor' ? `${sig.name}.constructeur` : member === '#fn' ? sig.name : `${self && self.name ? self.name : sig.name}.${member}`;
      if (!entry) {
        if (member === '#ctor') return undefined;
        throw new Error(`« ${member} » n’existe pas dans « ${sig.name} ».`);
      }
      run.calls++;
      run.progress++;
      if (++run.steps > run.maxSteps) throw new Error(`Plus de ${run.maxSteps} étapes : exécution arrêtée.`);
      // Le contexte reste celui du programme (ses écritures se voient partout) ; this et les paramètres sont propres à l'appel.
      const f = new Frame({ partie: declId, ctx: run.root.ctx, label: name, parent: frame, self, args: args || [] });
      if (!run.silent) ws.emit('run:call', { type: 'run:call', decl: declId, member, name, phase: 'start', at: Date.now() });
      await this._task(run, () => this._chain(run, f, entry, [], depth + 1, { ...cause, member: name }));
      if (!run.silent) ws.emit('run:call', { type: 'run:call', decl: declId, member, name, phase: 'end', at: Date.now() });
      if (run.error) throw new Error(run.error);
      return f.returned ? f.result : f.last;
    }
    async _construct(run, frame, declId, args, node, depth) {
      const ws = this.ws, sig = ws.modules.signature(declId);
      const self = { $instance: true, class: sig.name, kind: sig.kind, decl: declId, node: node.id, name: ws.titleOf(node).split(' : ')[0], props: {} };
      Object.defineProperty(self, 'toJSON', { value: () => ({ [`${self.name} : ${self.class}`]: self.props }), enumerable: false });
      run.instances.push(self);
      await this.invoke(run, frame, declId, '#ctor', self, args, depth, { via: 'construct', step: frame.stepOf.get(node.id) });
      return self;
    }
    _callable(run, frame, declId, member, self, async) {
      const ws = this.ws, sig = ws.modules.signature(declId);
      const name = `${self && self.name ? self.name : sig.name}.${member}`;
      const fn = { $callable: true, name, decl: declId, member, async: !!async, call: (args = [], cause) => this.invoke(run, frame, declId, member, self, args, 0, cause || { via: 'call' }) };
      Object.defineProperty(fn, 'toJSON', { value: () => `ƒ ${name}()`, enumerable: false });
      return fn;
    }

    /**
     * Appelle un membre d'une déclaration hors d'une exécution complète : une fonction déclarée ('#fn'),
     * ou la méthode d'une classe ou d'une bibliothèque (une instance neuve est créée, sans paramètre,
     * sauf `self` donné). Sert aux sources de données (un lecteur demande des choix à une classe), aux tests,
     * à un serveur. Silencieux par défaut : rien n'est écrit dans le contexte du projet.
     * @returns {Promise<any>}
     */
    async call(declId, member = '#fn', args = [], { self = null, silent = true, context } = {}) {
      const ws = this.ws;
      if (!ws.modules || !ws.modules.declOf(declId)) throw new D.DominoError('call.decl', `Déclaration « ${declId} » introuvable.`);
      const ctx = ws.context.child('appel', context || {}, { bubble: !silent });
      const run = {
        trace: [], stoppedAt: null, error: null, steps: 0, maxSteps: 4000, delay: 0, t0: now(), silent, tasks: 0, blocked: 0, background: new Set(), waiters: new Set(),
        instances: [], calls: 0, progress: 0, sleeping: 0, seq: 0, vars: new Map(), id: `c${Date.now().toString(36)}`, startedAt: new Date().toISOString(), jumps: new Map(), jumpCount: 0, maxJumps: 1000,
      };
      const frame = new Frame({ partie: 'main', ctx, label: 'appel' });
      run.root = frame;
      const kind = ws.modules.kindOf(ws.get(declId));
      let me = self;
      if (!me && member !== '#fn' && kind !== 'function') {
        const sig = ws.modules.signature(declId);
        me = { $instance: true, class: sig.name, kind: sig.kind, decl: declId, node: null, name: sig.name, props: {} };
        await this.invoke(run, frame, declId, '#ctor', me, [], 0, { via: 'construct' });
      }
      const r = await this.invoke(run, frame, declId, member, me, args, 0, { via: 'call' });
      while (run.background.size) await Promise.allSettled([...run.background]);
      if (run.error) throw new Error(run.error);
      return r;
    }

    _step(run, n, info) {
      if (!n) return;
      const step = { dominoId: n.id, title: this.ws.titleOf(n), at: Math.round(now() - run.t0), ...info };
      run.trace.push(step);
      if (run.silent) return;
      if (info.status === 'skipped') n.state.lastRun = { status: 'skipped', reason: info.reason, at: Date.now() };
      this.ws.emit('run:step', { type: 'run:step', ...step });
    }
  }

  function normOutputs(raw, right) {
    if (Array.isArray(raw)) return right.map((_, i) => raw[i]);
    if (D.isPlainObject(raw) && right.some((q) => q.name in raw)) return right.map((q) => raw[q.name]);
    return right.map((_, i) => (i === 0 ? raw : undefined));
  }
  /** Ce qu'on garde d'une valeur pour la trace et l'inspecteur (une promesse n'est pas encore une valeur). */
  function show(v) { return isThenable(v) ? '⏳ en cours' : v; }
  function safeJSON(v) { try { return JSON.stringify(v); } catch (_) { return String(v); } }
  /** Conditions de connexion : une expression courte, avec `value` (la sortie) et `ctx`. */
  function evalCond(expr, value, ctx) {
    // Une expression déclarative (objet JSON, domino.expr.js) : évaluée sans code.
    if (expr && typeof expr === 'object' && D.Expr) return D.Expr.test(expr, { ...(D.isPlainObject(value) ? value : {}), value, ctx: ctx.merged ? ctx.merged() : {} });
     
    return Function('value', 'ctx', `"use strict"; return (${expr});`)(value, { get: (p) => ctx.get(p) });
  }
  function now() { return typeof performance !== 'undefined' ? performance.now() : Date.now(); }

  D.Runtime = Runtime;
  D.Frame = Frame;
})(typeof globalThis !== 'undefined' ? globalThis : window);
