/*!
 * Zeugma · types de points
 * La couleur d'un point EST son type de connexion. Un type peut en étendre un autre
 * (un `json` est une `donnée`) ou déclarer les types qu'il accepte en plus.
 *
 * Genre d'un type (`kind`) : ce que transporte un point de ce type.
 *   'data'  une valeur (par défaut) ;
 *   'call'  une fonction à appeler (méthode d'une instance, fonction d'une bibliothèque) ;
 *   autre   libre : le langage lui donne le sens qu'il veut (événement, signal…).
 * Un point « call » ne se relie qu'à un point « call » (ou « any »).
 */
(function (root) {
  'use strict';
  const D = root.Domino;

  class TypeSystem {
    constructor() {
      /** @type {Map<string, {name:string,label:string,color:string,extends?:string,accepts:string[],description?:string}>} */
      this.types = new Map();
      this.define('any', { label: 'Tout', color: '#151718', description: 'Accepte et fournit n’importe quelle valeur.' });
    }

    /**
     * Déclare un type de point.
     * @param {string} name identifiant stable (utilisé dans le JSON)
     * @param {{label?:string,color:string,extends?:string,accepts?:string[],description?:string}} spec
     */
    define(name, spec = {}) {
      if (!name || typeof name !== 'string') throw new D.DominoError('type.name', 'Un type de point doit avoir un nom.');
      if (spec.extends && !this.types.has(spec.extends)) throw new D.DominoError('type.extends', `Le type « ${name} » étend « ${spec.extends} », qui n’est pas déclaré.`, { name });
      this.types.set(name, { name, label: spec.label || name, color: spec.color || '#151718', extends: spec.extends, accepts: [...(spec.accepts || [])], description: spec.description || '', kind: spec.kind || (spec.extends && this.types.get(spec.extends).kind) || 'data', builtin: !!spec.builtin });
      return this;
    }
    defineAll(list) { (list || []).forEach((s) => this.define(s.name, s)); return this; }
    has(name) { return this.types.has(name); }
    get(name) { return this.types.get(name) || this.types.get('any'); }
    color(name) { return this.get(name).color; }
    label(name) { return this.get(name).label; }
    kind(name) { return this.get(name).kind; }

    /** `a` est-il un `b` (égal, ou par héritage) ? */
    isA(a, b) {
      for (let cur = a, guard = 0; cur && guard < 32; guard++) {
        if (cur === b) return true;
        cur = this.types.get(cur) && this.types.get(cur).extends;
      }
      return false;
    }

    /**
     * Une sortie de type `out` peut-elle alimenter une entrée de type `inp` ?
     * Oui si l'un des deux est `any`, si `out` est un `inp`, ou si `inp` l'accepte explicitement.
     */
    compatible(out, inp, extraAccepts = []) {
      if (!out || !inp || out === 'any' || inp === 'any') return true;
      if ((this.kind(out) === 'call') !== (this.kind(inp) === 'call')) return false;
      if (this.isA(out, inp)) return true;
      const spec = this.types.get(inp);
      return !!((spec && spec.accepts.some((a) => this.isA(out, a))) || extraAccepts.some((a) => this.isA(out, a)));
    }

    /** Message d'explication quand deux types ne vont pas ensemble. */
    explain(out, inp) { return `${this.label(out).toLowerCase()} → ${this.label(inp).toLowerCase()}`; }

    toJSON() {
      return [...this.types.values()].filter((s) => s.name !== 'any').map((s) => D.compact({ name: s.name, label: s.label, color: s.color, kind: s.kind === 'data' ? undefined : s.kind, extends: s.extends, accepts: s.accepts, description: s.description, builtin: s.builtin || undefined }));
    }
  }
  D.TypeSystem = TypeSystem;
})(typeof globalThis !== 'undefined' ? globalThis : window);
